CARDIO.register({"item":"d114","meta":{"num":"d114","label":"114","spe":"dermato","short":"Exanthème, érythrodermie","title":"Exanthème et érythrodermie de l'enfant et de l'adulte (items 114 et 164)","section":"D","chapter":4,"pages":"82-93","sdd":[{"num":37,"label":"Éruptions chez l'enfant"},{"num":85,"label":"Érythème"},{"num":88,"label":"Prurit"},{"num":178,"label":"Demande/prescription raisonnée et choix d'un examen diagnostique"},{"num":219,"label":"Hyperéosinophilie"},{"num":235,"label":"Découverte, diagnostic positif, dépistage rapide VIH"},{"num":310,"label":"Prévention chez un malade contagieux"}]},"objectives":[{"id":"d114-obj-01","rank":"A","rubric":"Définition","title":"Définition d'un exanthème","desc":"Érythème d'apparition brutale et transitoire"},{"id":"d114-obj-02","rank":"A","rubric":"Définition","title":"Définition d'une érythrodermie","desc":"Érythème, plus de 90 % de la surface corporelle, évolution d'au moins 6 semaines, prurit, desquamation, altération de l'état général"},{"id":"d114-obj-03","rank":"A","rubric":"Diagnostic positif","title":"Reconnaître les trois types séméiologiques d'exanthème","desc":"Exanthème roséoliforme, morbilliforme, scarlatiniforme"},{"id":"d114-obj-04","rank":"B","rubric":"Diagnostic positif","title":"Reconnaître l'éruption du mégalérythème épidémique","desc":"Atteinte œdémateuse du visage, éruption en gants et chaussettes"},{"id":"d114-obj-05","rank":"B","rubric":"Diagnostic positif","title":"Reconnaître le rash à l'ampicilline lors d'une infection à Epstein-Barr virus","desc":"Complication classique ne devant pas être confondue avec une toxidermie aux pénicillines"},{"id":"d114-obj-06","rank":"A","rubric":"Diagnostic positif","title":"Connaître les complications systémiques de l'érythrodermie","desc":"Complications hydro-électrolytiques, infectieuses, de décubitus, décompensation de tares sous-jacentes, décès"},{"id":"d114-obj-07","rank":"A","rubric":"Diagnostic positif","title":"Savoir diagnostiquer une épidermolyse staphylococcique","desc":"Terrain (nouveau-né et jeune enfant), infection du cordon et impétigo, fièvre et altération de l'état général, lésions péri-orificielles, décollements bulleux"},{"id":"d114-obj-08","rank":"A","rubric":"Identifier une urgence","title":"Connaître les signes cliniques du syndrome de Kawasaki","desc":"Terrain, fièvre, adénopathies, atteinte caractéristique des muqueuses"},{"id":"d114-obj-09","rank":"A","rubric":"Identifier une urgence","title":"Savoir que l'érythrodermie est une urgence et savoir la prendre en charge","desc":"Hospitalisation et mise en condition du malade (réchauffement, rééquilibration hydro-électrolytique, détecter l'infection...)"},{"id":"d114-obj-10","rank":"A","rubric":"Étiologies","title":"Connaître la principale cause d'exanthème chez l'enfant et chez l'adulte","desc":"Origine virale"},{"id":"d114-obj-11","rank":"B","rubric":"Étiologies","title":"Connaître les trois causes d'exanthème à évoquer systématiquement chez l'adulte","desc":"VIH, syphilis, médicaments"},{"id":"d114-obj-12","rank":"B","rubric":"Étiologies","title":"Connaître les quatre causes principales d'exanthème roséoliforme","desc":"Exanthème subit, rubéole, primo-infection VIH, syphilis secondaire"},{"id":"d114-obj-13","rank":"B","rubric":"Étiologies","title":"Connaître les trois causes principales d'exanthème morbilliforme","desc":"Rougeole, mégalérythème épidémique, mononucléose infectieuse"},{"id":"d114-obj-14","rank":"B","rubric":"Étiologies","title":"Connaître les deux causes principales d'exanthème scarlatiniforme","desc":"Scarlatine, syndrome de Kawasaki"},{"id":"d114-obj-15","rank":"B","rubric":"Étiologies","title":"Connaître les quatre principaux exanthèmes à risque chez la femme enceinte","desc":"Rubéole (mort fœtale ou malformations), parvovirus B19 (anasarque fœtale), toxoplasmose, syphilis (forme congénitale)"},{"id":"d114-obj-16","rank":"A","rubric":"Étiologies","title":"Savoir évoquer une rougeole chez l'enfant et chez l'adulte","desc":""},{"id":"d114-obj-17","rank":"A","rubric":"Étiologies","title":"Connaître trois causes d'érythrodermie chez l'adulte","desc":"Psoriasis, eczéma, syndrome de Sézary, toxidermie (DRESS), VIH, gale hyperkératosique"},{"id":"d114-obj-18","rank":"B","rubric":"Contenu multimédia","title":"Reconnaître une langue framboisée","desc":"Image : langue framboisée"},{"id":"d114-obj-19","rank":"A","rubric":"Contenu multimédia","title":"Reconnaître un exanthème morbilliforme","desc":""},{"id":"d114-obj-20","rank":"A","rubric":"Contenu multimédia","title":"Reconnaître un exanthème scarlatiniforme","desc":""},{"id":"d114-obj-21","rank":"A","rubric":"Contenu multimédia","title":"Reconnaître une érythrodermie","desc":"Image d'érythrodermie"},{"id":"d114-obj-22","rank":"B","rubric":"Contenu multimédia","title":"Reconnaître un mégalérythème","desc":"Image de mégalérythème chez l'enfant"},{"id":"d114-obj-23","rank":"A","rubric":"Diagnostic positif","title":"Exanthèmes fébriles de l'enfant : type d'éruption","desc":""},{"id":"d114-obj-24","rank":"A","rubric":"Identifier une urgence","title":"Exanthèmes fébriles de l'enfant : évaluation de la gravité","desc":""},{"id":"d114-obj-25","rank":"A","rubric":"Diagnostic positif","title":"Exanthèmes fébriles de l'enfant : orientation diagnostique","desc":""},{"id":"d114-obj-26","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : rougeole","desc":"Épidémiologie (A), prévention (A), caractéristiques cliniques (A), signes de gravité (A), complications (A), principes de conduite à tenir autour d'un cas (A)"},{"id":"d114-obj-27","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : rubéole","desc":"Épidémiologie (B), prévention (A), caractéristiques cliniques (A), risque particulier en cours de grossesse (A), fœtopathie (B)"},{"id":"d114-obj-28","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : mégalérythème épidémique","desc":"Épidémiologie (B), caractéristiques cliniques (A), risque pour femme enceinte (A)"},{"id":"d114-obj-29","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : exanthème subit","desc":"Épidémiologie (B), caractéristiques cliniques (A)"},{"id":"d114-obj-30","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : mononucléose infectieuse","desc":"Épidémiologie (A), caractéristiques cliniques (A), signes de gravité, complications (A), diagnostic différentiel (A), évolution naturelle (B)"},{"id":"d114-obj-31","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : scarlatine","desc":"Épidémiologie (A), caractéristiques cliniques (A), complications et orientation (A), éviction scolaire (A)"},{"id":"d114-obj-32","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : maladie de Kawasaki","desc":"Épidémiologie (B), caractéristiques cliniques (A), orientation (hospitalisation) (A), prise en charge (B)"},{"id":"d114-obj-33","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : varicelle","desc":"Épidémiologie (A), caractéristiques cliniques (A), contre-indication aspirine (A), complications (A), connaître les sujets à risque (A)"}],"course":{"sections":[{"id":"d114-sec-01","title":"Exanthème : définition, démarche, bilan","rank":"A","objectives":["d114-obj-01","d114-obj-10","d114-obj-11","d114-obj-23","d114-obj-24","d114-obj-25"],"content":"### Définition\n- **Exanthème** = **érythème d'apparition brutale et transitoire** : intense ou non, diffus ou de siège particulier, isolé ou accompagné d'autres signes ; une atteinte des muqueuses (**énanthème**) peut s'y associer ; **bénin ou potentiellement grave**.\n- **2 causes principales** : **infectieuses** et **médicamenteuses**. Chez l'**enfant**, les causes infectieuses sont surtout **virales** ; chez l'**adulte**, ce sont notamment des infections sexuellement transmissibles : **syphilis**, **VIH** (virus de l'immunodéficience humaine).\n\n### Démarche devant un exanthème\n1. **Anamnèse** : contexte **épidémique**, **contage** possible, **prise de médicament**.\n2. **Type d'éruption** : roséoliforme, morbilliforme ou scarlatiniforme (section suivante).\n3. **Signes associés** :\n   - origine **virale** : **fièvre**, **syndrome grippal**, **énanthème**, **polyadénopathie** ;\n   - origine **médicamenteuse** : **prurit**, éruption **polymorphe**, **hyperéosinophilie** sanguine.\n\n### Gravité [B]\n- Exanthème diffus **scarlatiniforme**, **fébrile**, d'apparition **brutale** → rechercher un **choc toxique staphylococcique** et des signes de **retentissement hémodynamique**.\n\n### Bilan [B]\n- **Enfant** : **aucun examen** indispensable, sauf suspicion de **scarlatine** (numération-formule sanguine ou NFS, prélèvement de gorge) ou de **Kawasaki** (NFS, plaquettes, échographie cardiaque).\n- **Adulte** (sans cause évidente) : NFS, tests hépatiques, sérodiagnostic de mononucléose, **test tréponémique**, **charge virale VIH** et sérologie VIH combinée.\n- **Femme enceinte** : sérologies de **toxoplasmose, rubéole, CMV (cytomégalovirus), parvovirus B19, syphilis**.","keyPoints":["**Exanthème** = **érythème brutal et transitoire** (± **énanthème**), bénin ou grave.","Causes : **virales** (surtout chez l'**enfant**) ; **VIH, syphilis** et **médicaments** chez l'**adulte**.","**Viral** : fièvre, syndrome grippal, énanthème, adénopathies. **Médicamenteux** : **prurit**, éruption **polymorphe**, **hyperéosinophilie**.","[B] Enfant : **pas d'examen** sauf **scarlatine** (gorge) ou **Kawasaki** (échographie cardiaque)."],"pitfalls":["Chez l'adulte, penser au **VIH**, à la **syphilis** et aux **médicaments** (toxidermie).","Exanthème = **brutal et transitoire** ; ne pas le confondre avec l'**érythrodermie** (durable : au moins 6 semaines)."],"src":"p. 84-85, 90"},{"id":"d114-sec-02","title":"Les 3 types d'exanthème et leurs causes","rank":"A","objectives":["d114-obj-03","d114-obj-12","d114-obj-13","d114-obj-14","d114-obj-19","d114-obj-20"],"content":"| Type | Aspect | Causes principales [B] |\n|---|---|---|\n| **Roséoliforme** (ou rubéoliforme) | **petites macules rosées, pâles, bien séparées** | **exanthème subit**, **rubéole**, **primo-infection VIH**, **syphilis secondaire** |\n| **Morbilliforme** | **maculo-papules rouges**, parfois **confluentes en plaques** séparées par de la **peau saine** | **rougeole**, **mégalérythème épidémique**, **mononucléose infectieuse** |\n| **Scarlatiniforme** | **plaques diffuses rouge vif**, un peu granitées au toucher, **sans peau saine** entre elles, chaudes ou cuisantes, **plus marquées dans les plis** ; desquamation secondaire en larges lambeaux possible | **scarlatine**, **syndrome de Kawasaki** |\n\n- [B] Autres causes d'exanthème **morbilliforme** : **primo-infection VIH**, **toxidermie** (bêta-lactamines, sulfamides, anticomitiaux, c'est-à-dire antiépileptiques), syndrome de Kawasaki.","keyPoints":["3 types : **roséoliforme** (petites macules rosées séparées), **morbilliforme** (maculo-papules, **peau saine** entre les plaques), **scarlatiniforme** (rouge vif, **sans peau saine**, plis).","[B] **Roséoliforme** : exanthème subit, rubéole, primo-infection VIH, syphilis secondaire.","[B] **Morbilliforme** : rougeole, mégalérythème épidémique, mononucléose infectieuse.","[B] **Scarlatiniforme** : scarlatine, syndrome de Kawasaki."],"pitfalls":["**Scarlatiniforme** = **aucun intervalle de peau saine** ; **morbilliforme** = **peau saine entre les plaques**."],"src":"p. 85-86, 88"},{"id":"d114-sec-03","title":"Roséoliforme : exanthème subit et rubéole","rank":"A","objectives":["d114-obj-12","d114-obj-15","d114-obj-27","d114-obj-29"],"content":"### Exanthème subit (roséole infantile)\n- **Primo-infection par le virus HHV6** (human herpesvirus 6), chez le **nourrisson de 6 à 18 mois** ; souvent **asymptomatique**.\n- **Fièvre élevée (39-40 °C) isolée pendant 48-72 heures (3 jours)**, **puis** **éruption roséoliforme prédominant sur le tronc**, en une seule poussée.\n- Complications **rares** : convulsions fébriles, méningite virale, hépatite aiguë, pneumopathie, syndrome mononucléosique.\n\n### Rubéole\n- [B] **Épidémiologie** : virus de la rubéole ; âge de survenue **15 à 25 ans** ; incubation **3 semaines** ; contagiosité de **7 jours avant** à **14 jours après** le début de l'éruption.\n- **Clinique** : **exanthème discret** (2 à 4 jours), **arthralgies**, **conjonctivite**.\n- **Femme enceinte non immunisée** : risque de **mort fœtale** ou de **malformations** neurologiques et sensorielles.\n- **Pas d'éviction** de la collectivité recommandée ; **informer** le personnel, les parents et la femme enceinte.","keyPoints":["**Exanthème subit** : **nourrisson 6-18 mois**, **HHV6**, **fièvre isolée 3 jours** puis **éruption roséoliforme du tronc**.","Rubéole : **pas d'éviction** de la collectivité ; **informer** le personnel, les parents et la femme enceinte.","**Rubéole** (15-25 ans) : **exanthème discret**, arthralgies, conjonctivite.","**Rubéole chez une femme enceinte non immunisée** → **mort fœtale** ou **malformations** graves."],"pitfalls":["Nourrisson : éruption roséoliforme **après 3 jours de fièvre isolée** → **exanthème subit**.","Rubéole : le danger est pour la **femme enceinte non immunisée** (fœtus), pas pour l'enfant."],"src":"p. 85, 90"},{"id":"d114-sec-04","title":"Rougeole : exanthème morbilliforme typique","rank":"A","objectives":["d114-obj-16","d114-obj-19","d114-obj-26"],"content":"- **Évoquer une rougeole** devant l'association **catarrhe oculo-nasal + conjonctivite + exanthème fébrile**.\n- **Morbillivirus** (paramyxovirus) ; incubation **10-12 jours** ; contagiosité de **3-5 jours avant** à **4 jours après** l'éruption.\n\n### Déroulement\n1. **Phase pré-éruptive** : **fièvre élevée (39-40 °C)**, **catarrhe oculo-nasal**, **conjonctivite**, **signe de Köplick** (semis de papules sur la face interne des joues).\n2. **Exanthème morbilliforme** : début **derrière les oreilles (rétro-auriculaire)**, puis **extension à tout le corps en une seule poussée**.\n\n### Complications\n- **Pneumopathie**, **hépatite**, **pancréatite**, **encéphalite** (grave), **kératite** (risque de cécité).\n\n### Conduite à tenir\n- **Maladie à déclaration obligatoire**.\n- **Éviction de la collectivité jusqu'à 5 jours après le début de l'éruption** ; informer le personnel et les parents.","keyPoints":["**Rougeole** = **catarrhe oculo-nasal + conjonctivite + exanthème fébrile** ; **signe de Köplick**.","Exanthème **morbilliforme** : début **rétro-auriculaire**, extension en **une seule poussée**.","Complications : **pneumopathie**, **hépatite**, **pancréatite**, **encéphalite** (grave), **kératite** (cécité).","**Déclaration obligatoire** ; **éviction jusqu'à 5 jours après le début de l'éruption**."],"pitfalls":["La rougeole est **contagieuse avant l'éruption** (3-5 jours avant) et jusqu'à **4 jours après**.","Le **signe de Köplick** (semis de papules sur la face interne des joues) apparaît en **phase pré-éruptive**."],"src":"p. 86, 90"},{"id":"d114-sec-05","title":"Morbilliforme : mégalérythème épidémique et mononucléose infectieuse","rank":"A","objectives":["d114-obj-04","d114-obj-05","d114-obj-13","d114-obj-15","d114-obj-22","d114-obj-28","d114-obj-30"],"content":"### Mégalérythème épidémique (parvovirus B19)\n- **Enfant de 5 à 10 ans** [B] ; incubation **14 jours** [B] ; contagiosité **limitée à la phase pré-éruptive** ; fièvre modérée.\n- **Visage** : érythème et **œdème des joues** (aspect « souffleté ») → puis **tronc** : érythème à **bords émiettés** (en guirlande) → **érythème en « gants et chaussettes »**. Arthralgies possibles.\n- **Grossesse** : **pas de risque tératogène** ; infection au 2e trimestre : risque d'**anasarque fœtale**, de myocardite et d'anémie fœtale. Autres personnes à risque de complications : **immunodéprimé**, patient avec **anémie chronique**.\n\n### Mononucléose infectieuse (MNI)\n- **Epstein-Barr virus (EBV)**, surtout chez l'**adolescent** ; incubation **4 à 6 semaines** ; contagiosité maximale pendant la **phase aiguë** (jusqu'à 6 mois).\n- **Fièvre**, **asthénie importante**, **polyadénopathie**, **splénomégalie** ; **lymphocytose élevée avec lymphocytes hyperbasophiles**.\n- **Exanthème inconstant (5-10 %)**, **sauf en cas de prescription de pénicilline A** : c'est le **rash à l'ampicilline**, à **ne pas confondre avec une toxidermie** aux pénicillines.\n- Complications **rares** : hépatite, méningo-encéphalite, **rupture splénique**, agranulocytose.","keyPoints":["**Mégalérythème épidémique** (**parvovirus B19**, enfant **5-10 ans**) : **joues œdémateuses**, tronc à **bords émiettés**, puis **gants et chaussettes**.","Parvovirus B19 et **grossesse** : **anasarque fœtale** (2e trimestre), **pas de risque tératogène**.","**MNI** (**EBV**, **adolescent**) : fièvre, asthénie, polyadénopathie, splénomégalie ; **lymphocytes hyperbasophiles**.","MNI : **exanthème inconstant** (5-10 %) **sauf sous pénicilline A** → **rash à l'ampicilline**, **pas une toxidermie**."],"pitfalls":["**Rash à l'ampicilline** d'une MNI : ne pas conclure à une **allergie** aux pénicillines (toxidermie).","Parvovirus B19 chez la femme enceinte : **pas tératogène**, mais risque d'**anasarque fœtale**."],"src":"p. 82, 86-87, 90"},{"id":"d114-sec-06","title":"Scarlatiniforme : scarlatine et scarlatine staphylococcique","rank":"A","objectives":["d114-obj-07","d114-obj-14","d114-obj-18","d114-obj-20","d114-obj-31"],"content":"### Scarlatine (streptocoque)\n- **Streptocoque du groupe A** (exotoxines) ; **enfant de 5 à 10 ans** ; incubation **2 à 4 jours** ; contamination **aérienne** ; contagiosité **2 à 3 semaines** (elle persiste 48 h après le début du traitement).\n- **Début brutal** : fièvre 39-40 °C, douleurs pharyngées, céphalées, **angine rouge**, adénopathies sous-maxillaires.\n- **Éruption** des **grands plis** (scarlatiniforme) ; **langue framboisée** (dépapillation progressive en « V ») ; puis desquamation fine ou en lambeaux.\n- **Prélèvement de gorge** ; **amoxicilline** ; **éviction scolaire jusqu'à 48 h après le début du traitement**.\n- **Complications post-streptococciques** : **glomérulonéphrite**, **rhumatisme articulaire aigu**.\n\n### Scarlatine staphylococcique (= épidermolyse staphylococcique)\n- **Staphylococcus aureus** sécréteur de toxines ; terrain : **nouveau-né, nourrisson, jeune enfant** ou **adulte immunodéprimé** ; contexte d'**infection du cordon** (nouveau-né) ou d'**impétigo**.\n- **Pas d'angine** ; fièvre et altération de l'état général ; éruption débutant aux **grands plis** et aux **régions péri-orificielles**, puis **décollement bulleux**.\n- Forme sévère : **choc toxique staphylococcique**. Traitement : **oxacilline** ; prélèvements bactériologiques.","keyPoints":["**Scarlatine** : **streptocoque A**, **5-10 ans**, début **brutal** + **angine**, éruption des **grands plis**, **langue framboisée**.","Scarlatine : **prélèvement de gorge**, **amoxicilline**, **éviction 48 h** après le début du traitement.","Complications **post-streptococciques** : **glomérulonéphrite**, **rhumatisme articulaire aigu**.","**Scarlatine staphylococcique** : **pas d'angine**, grands plis et zones péri-orificielles puis **décollement bulleux** ; **oxacilline**.","[B] **Exanthème scarlatiniforme fébrile brutal** → chercher un **choc toxique** staphylococcique."],"pitfalls":["**Pas d'angine** + éruption des plis puis **décollements bulleux** : **scarlatine staphylococcique**.","Antibiotique : **amoxicilline** (streptocoque) ≠ **oxacilline** (staphylocoque).","La **langue framboisée** se voit dans la **scarlatine** et dans le **Kawasaki**."],"src":"p. 88-90"},{"id":"d114-sec-07","title":"Syndrome de Kawasaki","rank":"A","objectives":["d114-obj-08","d114-obj-14","d114-obj-18","d114-obj-32"],"content":"- **Vasculite systémique aiguë** (syndrome adéno-cutanéo-muqueux) de l'**enfant de moins de 5 ans**.\n- **Diagnostic** : **au moins 5 critères sur 6** :\n  1. **fièvre élevée > 38,5 °C pendant plus de 5 jours**, avec altération de l'état général ;\n  2. **conjonctivite bilatérale** avec œdème des paupières ;\n  3. **énanthème** : **chéilite** et **langue framboisée** ;\n  4. **érythème et œdème des extrémités** ;\n  5. **exanthème polymorphe** ;\n  6. **lymphadénite**, souvent asymétrique.\n- Évolution : **desquamation en « doigt de gant »**.\n- [B] **Biologie** : syndrome inflammatoire (protéine C-réactive ou **CRP** élevée), **hyperleucocytose à polynucléaires neutrophiles**, **thrombocytose**. Bilan : NFS, plaquettes, **échographie cardiaque**.\n\n### Gravité\n- **Complications cardiaques** : **anévrismes coronariens** (surtout en cas de **retard thérapeutique**), troubles du rythme, décès par myocardite ou infarctus.\n- **Hospitalisation indispensable**.","keyPoints":["**Kawasaki** : **vasculite** aiguë de l'**enfant < 5 ans**, **fièvre > 38,5 °C pendant plus de 5 jours**.","Diagnostic : **≥ 5 critères sur 6** (fièvre, conjonctivite bilatérale, chéilite + langue framboisée, érythème et œdème des extrémités, exanthème polymorphe, lymphadénite).","Risque : **anévrismes coronariens** (retard thérapeutique) → **hospitalisation indispensable**.","[B] Syndrome inflammatoire (CRP élevée), hyperleucocytose à polynucléaires neutrophiles, **thrombocytose** ; **échographie cardiaque**."],"pitfalls":["Fièvre **> 5 jours** + **conjonctivite bilatérale** + lèvres/langue framboisée chez un enfant **< 5 ans** : penser **Kawasaki**, **hospitaliser** (risque coronarien).","Ne pas oublier que la **langue framboisée** existe aussi dans la **scarlatine**."],"src":"p. 88, 90"},{"id":"d114-sec-08","title":"Érythrodermie : définir et reconnaître","rank":"A","objectives":["d114-obj-02","d114-obj-21"],"content":"- **Érythrodermie** = syndrome **rare**, **diagnostiqué cliniquement** : **érythème confluent + desquamation** sur **plus de 90 % de la surface corporelle**, **depuis au moins 6 semaines**.\n- **Urgence dermatologique** : prise en charge **immédiate** (traitement et recherche de la cause) ; **hospitalisation** dans un service spécialisé.\n- L'aspect clinique **ne préjuge pas de la cause**.\n\n### Signes cliniques\n- **Érythème généralisé**, inflammatoire, **plus violacé dans les zones déclives**, dont l'intensité **varie d'un jour à l'autre**.\n- **Desquamation constante** (fine ou en larges lambeaux).\n- **Prurit constant** et **dysrégulation thermique** (épisodes de **fièvre** et d'**hypothermie**).\n- **Pachydermie** (visible dans les plis), **œdème du visage** (ectropion possible), atteinte des **muqueuses** (chéilite, conjonctivite, stomatite).\n- Après quelques semaines : chute des **cheveux, sourcils, cils** ; **ongles** dystrophiques (ligne de Beau).\n- **Polyadénopathie** fréquente ; pertes **hydro-électrolytiques et/ou protéiques** ; **altération de l'état général**.\n\n### Ce qui n'est PAS une érythrodermie\n- Une éruption érythémato-squameuse faite d'éléments multiples **séparés par de la peau saine**.\n- Un **exanthème** ou une **nécrolyse épidermique** décollante, d'évolution **aiguë**.","keyPoints":["**Érythrodermie** = **érythème + desquamation** sur **> 90 %** de la surface corporelle, **depuis ≥ 6 semaines**.","**Prurit constant**, **dysrégulation thermique** (fièvre, hypothermie), **pachydermie**, **œdème du visage**, polyadénopathie.","**Urgence** : **hospitalisation** en service spécialisé ; l'aspect clinique ne donne **pas la cause**.","**≠ exanthème** (aigu) ; **≠ éruption à éléments séparés par de la peau saine**."],"pitfalls":["L'érythrodermie **n'est pas synonyme d'érythème ni d'exanthème**.","Elle est **durable** (≥ 6 semaines) : un exanthème aigu, même diffus, n'en est pas une."],"src":"p. 90-91, 93"},{"id":"d114-sec-09","title":"Érythrodermie : causes et bilan étiologique","rank":"A","objectives":["d114-obj-17"],"content":"### Causes principales (adulte)\n| Groupe | Causes |\n|---|---|\n| **Dermatoses inflammatoires** | **psoriasis** (+++), **eczéma / dermatite atopique** (+++), **toxidermie : DRESS** (Drug Rash with hyper-Eosinophilia and Systemic Symptoms) (+++), lichen plan [B] |\n| **Lymphome** | **syndrome de Sézary** (+++) = lymphome T cutané épidermotrope |\n| **Infections** | **VIH** (+), **gale croûteuse** (++) |\n| Sans cause [B] | **idiopathique** : 10 à 15 % des cas |\n\n- **Enfant** : nouveau-né et nourrisson de moins de 3 mois : maladie de Leiner-Moussous ; après 3 mois : **dermatite atopique** (+++), puis mêmes causes que l'adulte.\n\n### Chercher la cause\n- **Interrogatoire** : ancienneté de l'éruption, antécédents dermatologiques et généraux, **prise de médicament**, traitements locaux utilisés, **contexte infectieux**.\n- **Biopsie cutanée** : peut montrer des signes de la maladie en cause ; **à répéter** si l'on suspecte un **lymphome cutané**.\n- **Prélèvements bactériologiques ou parasitologiques** si besoin (fièvre, complications infectieuses).","keyPoints":["Causes : **psoriasis**, **dermatite atopique/eczéma**, **toxidermie (DRESS)**, **syndrome de Sézary** ; aussi **VIH**, **gale croûteuse**.","**Biopsie cutanée** : à **répéter** si suspicion de **lymphome cutané**.","**Interrogatoire** : ancienneté, antécédents, **médicaments**, traitements locaux, contexte infectieux.","[B] **10 à 15 %** d'érythrodermies **idiopathiques**."],"pitfalls":["Ne pas oublier la **toxidermie (DRESS)** : toujours chercher une **prise médicamenteuse**.","Le **syndrome de Sézary** est un **lymphome** : biopsie **répétée** si doute."],"src":"p. 91-92"},{"id":"d114-sec-10","title":"Érythrodermie : complications et prise en charge","rank":"A","objectives":["d114-obj-06","d114-obj-09"],"content":"### Complications\nLa gravité dépend du **terrain** et des **complications**.\n- **Hydro-électrolytiques** : pertes dues à la vasodilatation cutanée, à la desquamation, au suintement, à l'œdème et à la fièvre ; elles peuvent **décompenser** une insuffisance cardiaque, respiratoire ou rénale.\n- **Décubitus** : dénutrition, cachexie, **escarres**.\n- **Infectieuses** : infections cutanées bactériennes (**staphylocoque**) ou virales (**herpès**, varicelle-zona) ; infections générales (**pneumopathies, septicémies**).\n- **Décès** : mortalité **jusqu'à 20 %**, liée aux complications, surtout **infectieuses**.\n\n### Prise en charge\n- **Hospitalisation en urgence**.\n- **Examens biologiques** pour évaluer la gravité ; **rééquilibration hydro-électrolytique** ; traitement des **défaillances viscérales** ; **recherche et traitement de la cause**.\n- **Traitement symptomatique** : **réchauffement** du malade (limite les pertes caloriques, l'hypercatabolisme, la dénutrition) ; dans les **formes graves**, **corticothérapie locale de niveau 1** (très forte) = amélioration rapide.","keyPoints":["Complications : **hydro-électrolytiques**, **décubitus** (escarres, dénutrition), **infectieuses**, **décès** (jusqu'à **20 %**).","**Hospitalisation en urgence** : examens biologiques, **rééquilibration hydro-électrolytique**, défaillances viscérales, **cause**.","**Réchauffement** ; formes graves : **corticothérapie locale de niveau 1** (très forte)."],"pitfalls":["Ne pas attendre la cause pour traiter : **réhydratation, réchauffement** et recherche **étiologique** se mènent **ensemble**.","La mortalité vient surtout des **complications infectieuses**."],"src":"p. 92-93"}],"essentials":[{"id":"d114-ess-01","rank":"A","text":"Définition d'un exanthème : **érythème d'apparition brutale et transitoire** (± énanthème), bénin ou potentiellement grave.","src":"p. 84","q":"Comment définit-on un exanthème (mode d'apparition, composante muqueuse, gravité) ?"},{"id":"d114-ess-02","rank":"A","text":"Causes d'exanthème selon l'âge : **virales** chez l'enfant ; **VIH, syphilis et médicaments** chez l'adulte.","src":"p. 84, 90","q":"Quelles sont les causes d'exanthème selon l'âge (enfant, adulte) ?"},{"id":"d114-ess-03","rank":"A","text":"Trois types sémiologiques d'exanthème : **roséoliforme** (petites macules rosées séparées), **morbilliforme** (peau saine entre les plaques), **scarlatiniforme** (rouge vif, sans peau saine, plis).","src":"p. 85","q":"Pouvez-vous citer les 3 types sémiologiques d'exanthème et leur description ?"},{"id":"d114-ess-04","rank":"A","text":"Orientation étiologique d'un exanthème : **viral** = fièvre, syndrome grippal, énanthème, adénopathies ; **médicamenteux** = prurit, éruption polymorphe, hyperéosinophilie.","src":"p. 85","q":"Quels éléments orientent vers une cause virale ou médicamenteuse devant un exanthème ?"},{"id":"d114-ess-05","rank":"B","text":"Examens d'un exanthème de l'enfant : **aucun** sauf suspicion de **scarlatine** (numération-formule sanguine ou NFS, gorge) ou de **Kawasaki** (NFS, plaquettes, échographie cardiaque).","src":"p. 85","q":"Quels examens demander devant un exanthème de l'enfant, et dans quels cas ?"},{"id":"d114-ess-06","rank":"A","text":"Exanthème subit, tableau clinique typique : **nourrisson de 6 à 18 mois**, **HHV6**, **fièvre isolée 3 jours** puis éruption roséoliforme du tronc, en une seule poussée.","src":"p. 85, 90","q":"Comment décrire le tableau typique de l'exanthème subit (âge, virus, évolution) ?"},{"id":"d114-ess-07","rank":"A","text":"Rubéole et grossesse : chez la femme enceinte **non immunisée**, risque de **mort fœtale** ou de **malformations** graves.","src":"p. 85, 90","q":"Quel est le risque de la rubéole chez la femme enceinte non immunisée ?"},{"id":"d114-ess-08","rank":"A","text":"Rougeole, comment l'évoquer en pratique ? **Catarrhe oculo-nasal + conjonctivite + exanthème fébrile** ; **signe de Köplick** ; exanthème débutant derrière les oreilles.","src":"p. 86, 90","q":"Quels éléments cliniques permettent d'évoquer une rougeole ?"},{"id":"d114-ess-09","rank":"A","text":"Complications de la rougeole : **pneumopathie**, **hépatite**, **pancréatite**, **encéphalite** (grave), **kératite** (cécité).","src":"p. 86","q":"Pouvez-vous citer les complications de la rougeole ?"},{"id":"d114-ess-10","rank":"A","text":"Conduite à tenir devant une rougeole : **déclaration obligatoire** ; **éviction de la collectivité jusqu'à 5 jours après le début de l'éruption**.","src":"p. 86","q":"Quelle est la conduite à tenir devant une rougeole (déclaration, éviction) ?"},{"id":"d114-ess-11","rank":"A","text":"Mégalérythème épidémique, tableau clinique typique : **parvovirus B19**, **enfant de 5 à 10 ans**, **joues œdémateuses**, tronc à bords émiettés, puis érythème en **gants et chaussettes**.","src":"p. 86-87","q":"Comment décrire le tableau typique du mégalérythème épidémique (virus, âge, séquence des signes) ?"},{"id":"d114-ess-12","rank":"A","text":"Parvovirus B19 chez la femme enceinte : risque d'**anasarque fœtale** ; **pas de risque tératogène**.","src":"p. 86, 90","q":"Quel est le risque du parvovirus B19 chez la femme enceinte ?"},{"id":"d114-ess-13","rank":"A","text":"Mononucléose infectieuse, tableau clinique typique : virus d'Epstein-Barr (**EBV**), **adolescent**, fièvre, asthénie, polyadénopathie, splénomégalie ; **lymphocytes hyperbasophiles**.","src":"p. 86","q":"Comment décrire le tableau typique de la mononucléose infectieuse (virus, terrain, signes cliniques et biologiques) ?"},{"id":"d114-ess-14","rank":"A","text":"Rash à l'ampicilline : au cours de la mononucléose, exanthème **inconstant (5-10 %)** sauf sous **pénicilline A** ; **à ne pas confondre avec une toxidermie**.","src":"p. 82, 86","q":"Qu'est-ce que le rash à l'ampicilline et dans quel contexte survient-il ?"},{"id":"d114-ess-15","rank":"A","text":"Scarlatine, tableau clinique typique : **streptocoque A**, enfant de 5 à 10 ans, début brutal avec **angine**, éruption des **grands plis**, **langue framboisée**.","src":"p. 88","q":"Comment décrire le tableau typique de la scarlatine (agent, âge, début, éruption, langue) ?"},{"id":"d114-ess-16","rank":"A","text":"Prise en charge d'une scarlatine : **prélèvement de gorge**, **amoxicilline**, **éviction scolaire jusqu'à 48 h** après le début du traitement.","src":"p. 88","q":"Quelle est la prise en charge d'une scarlatine (prélèvement, traitement, éviction) ?"},{"id":"d114-ess-17","rank":"A","text":"Complications post-streptococciques de la scarlatine : **glomérulonéphrite** et **rhumatisme articulaire aigu**.","src":"p. 88","q":"Quelles sont les complications post-streptococciques de la scarlatine ?"},{"id":"d114-ess-18","rank":"A","text":"Scarlatine staphylococcique, tableau clinique : **pas d'angine**, grands plis et zones péri-orificielles puis **décollement bulleux** ; traitement par **oxacilline**.","src":"p. 88","q":"Comment décrire le tableau de la scarlatine staphylococcique et son traitement ?"},{"id":"d114-ess-19","rank":"B","text":"Exanthème scarlatiniforme diffus, fébrile, d'apparition brutale : rechercher un **choc toxique staphylococcique** et des signes de retentissement hémodynamique.","src":"p. 90","q":"Devant un exanthème scarlatiniforme diffus, fébrile, d'apparition brutale, que doit-on rechercher ?"},{"id":"d114-ess-20","rank":"A","text":"Syndrome de Kawasaki, diagnostic : vasculite de l'**enfant < 5 ans**, **fièvre > 38,5 °C pendant plus de 5 jours**, **au moins 5 critères sur 6**.","src":"p. 88","q":"Quels sont les critères diagnostiques du syndrome de Kawasaki (terrain, fièvre, nombre de critères) ?"},{"id":"d114-ess-21","rank":"A","text":"Risque et prise en charge du Kawasaki : **anévrismes coronariens** (retard thérapeutique) ; **hospitalisation indispensable**.","src":"p. 88, 90","q":"Quel est le risque du syndrome de Kawasaki et quelle prise en charge ?"},{"id":"d114-ess-22","rank":"A","text":"Définition de l'érythrodermie, critères : **érythème + desquamation** sur **plus de 90 %** de la surface corporelle, **depuis au moins 6 semaines** ; ≠ exanthème.","src":"p. 90, 93","q":"Quels sont les critères de définition d'une érythrodermie (érythème, étendue, durée) et la différence avec l'exanthème ?"},{"id":"d114-ess-23","rank":"A","text":"Signes cliniques d'une érythrodermie : **prurit constant**, **dysrégulation thermique**, pachydermie, œdème du visage, polyadénopathie ; urgence, **hospitalisation**.","src":"p. 90-91","q":"Quels sont les signes cliniques d'une érythrodermie et la conduite à tenir ?"},{"id":"d114-ess-24","rank":"A","text":"Quelles sont les causes principales d'érythrodermie ? **Psoriasis**, **dermatite atopique**, **toxidermie (DRESS)**, **syndrome de Sézary** ; aussi VIH, gale croûteuse.","src":"p. 91, 93","q":"Quelles sont les causes principales d'érythrodermie ?"},{"id":"d114-ess-25","rank":"A","text":"Érythrodermie, prise en charge : **hospitalisation en urgence**, **rééquilibration hydro-électrolytique**, **réchauffement**, recherche de la cause ; mortalité **jusqu'à 20 %**.","src":"p. 93","q":"Quelle est la prise en charge d'une érythrodermie (lieu, mesures, mortalité) ?"},{"id":"d114-ess-51","rank":"A","q":"Citez les 3 éléments de la démarche diagnostique devant un exanthème ?","text":"**Anamnèse** (contexte épidémique, contage, prise médicamenteuse), **analyse sémiologique** de l'éruption, **signes extracutanés et biologiques** orientant l'étiologie.","src":"p. 85","kind":"liste"},{"id":"d114-ess-52","rank":"B","q":"Citez les examens à faire chez l'adulte devant un exanthème sans cause évidente (6) ?","text":"**NFS, tests hépatiques**, sérodiagnostic de **MNI**, **test tréponémique**, **charge virale VIH** et sérologie VIH combinée (Ag-Ac **p24**).","src":"p. 85","kind":"liste"},{"id":"d114-ess-53","rank":"B","q":"Citez les 4 exanthèmes à risque chez la femme enceinte avec le risque pour l'enfant ?","text":"**Rubéole** (mort fœtale, malformations), **parvovirus B19** (anasarque fœtale), **toxoplasmose**, **syphilis** (forme congénitale).","src":"p. 83","kind":"liste"},{"id":"d114-ess-54","rank":"A","q":"Citez les signes de la phase pré-éruptive de la rougeole (4) ?","text":"**Fièvre élevée (39-40 °C)**, **catarrhe oculo-nasal**, **conjonctivite**, **signe de Köplick** (semis de papules sur la face interne des joues) ; l'exanthème débute en rétro-auriculaire.","src":"p. 86","kind":"liste"},{"id":"d114-ess-55","rank":"A","q":"Citez les complications possibles de la mononucléose infectieuse ?","text":"**Hépatite, méningo-encéphalite, rupture splénique, agranulocytose** (rares) ; exanthème surtout si pénicilline A.","src":"p. 86","kind":"liste"},{"id":"d114-ess-56","rank":"A","q":"Citez les complications rares de l'exanthème subit ?","text":"**Convulsions fébriles**, **méningite virale**, **hépatite aiguë**, **pneumopathie**, **syndrome mononucléosique**.","src":"p. 85","kind":"liste"},{"id":"d114-ess-57","rank":"A","q":"Chez qui le mégalérythème épidémique donne-t-il des complications, et lesquelles chez la femme enceinte ?","text":"Surtout **immunodéprimé**, patient avec **anémie chronique**, **femme enceinte** : pas de risque tératogène, mais au 2e trimestre **anasarque fœtale, myocardite, anémie fœtale**.","src":"p. 86","kind":"liste"},{"id":"d114-ess-58","rank":"A","q":"En dehors de la rougeole, du mégalérythème épidémique et de la mononucléose, citez 3 autres causes d'exanthème morbilliforme ?","text":"**Primo-infection VIH**, **toxidermie** (β-lactamines, sulfamides, anticomitiaux), **syndrome de Kawasaki**.","src":"p. 86","kind":"liste"},{"id":"d114-ess-59","rank":"A","q":"Citez les signes de la phase pré-éruptive de la scarlatine ?","text":"Début **brutal**, fièvre **39-40 °C**, douleurs pharyngées, céphalées, **angine rouge** et **adénopathies sous-maxillaires**.","src":"p. 88","kind":"liste"},{"id":"d114-ess-60","rank":"A","q":"Citez les complications cardiaques et le pronostic du syndrome de Kawasaki ?","text":"**Anévrismes coronariens**, troubles du rythme, décès par **myocardite** ou **infarctus** ; hospitalisation indispensable.","src":"p. 88","kind":"liste"},{"id":"d114-ess-61","rank":"A","q":"Citez les 5 points de l'interrogatoire devant une érythrodermie ?","text":"**Ancienneté** de l'éruption, **antécédents** dermatologiques et généraux, **prise médicamenteuse**, **traitements topiques** utilisés, **contexte infectieux** contemporain.","src":"p. 91","kind":"liste"},{"id":"d114-ess-62","rank":"A","q":"Citez les atteintes des phanères de l'érythrodermie après quelques semaines ?","text":"Chute des **cheveux, sourcils et cils** ; ongles **dystrophiques**, de croissance ralentie, avec **ligne de Beau** voire chute de l'ongle.","src":"p. 91","kind":"liste"},{"id":"d114-ess-63","rank":"A","q":"Citez les 4 types de complications d'une érythrodermie ?","text":"**Hydro-électrolytiques**, du **décubitus** (dénutrition, cachexie, escarres), **infectieuses** et **décès** (jusqu'à 20 %).","src":"p. 93","kind":"liste"},{"id":"d114-ess-64","rank":"A","q":"Citez les complications infectieuses d'une érythrodermie ?","text":"Infections cutanées **bactériennes** (staphylocoque) ou **virales** (herpès, varicelle-zona) ; infections générales (**pneumopathies, septicémies**).","src":"p. 93","kind":"liste"},{"id":"d114-ess-65","rank":"A","q":"Quelles sont les causes de la déperdition hydro-électrolytique de l'érythrodermie, et son risque ?","text":"**Vasodilatation cutanée, desquamation, suintement, œdème, fièvre** ; elle peut décompenser une insuffisance **cardiaque, respiratoire ou rénale**.","src":"p. 93","kind":"liste"},{"id":"d114-ess-66","rank":"A","q":"Quelles éruptions ne sont PAS une érythrodermie malgré leur étendue ?","text":"Une éruption érythémato-squameuse avec éléments **séparés par de la peau saine**, et un **exanthème ou une nécrolyse épidermique à évolution aiguë**.","src":"p. 91","kind":"piege"},{"id":"d114-ess-67","rank":"A","q":"L'aspect clinique d'une érythrodermie permet-il de préjuger de sa cause ?","text":"**Non** : l'aspect ne préjuge pas de la cause. Les causes principales : psoriasis, dermatite atopique, lymphome cutané (Sézary), toxidermie (DRESS).","src":"p. 93","kind":"piege"},{"id":"d114-ess-68","rank":"A","q":"Quelle température l'érythrodermie provoque-t-elle : fièvre ou hypothermie ?","text":"Les **deux** : dysrégulation thermique cutanée avec **épisodes de fièvre et d'hypothermie**, associée à un prurit constant.","src":"p. 90","kind":"piege"},{"id":"d114-ess-69","rank":"A","q":"Quel traitement local symptomatique dans les formes graves d'érythrodermie, et quel est le rôle du réchauffement ?","text":"**Corticothérapie locale de niveau 1 (très forte)** : amélioration symptomatique rapide. Le **réchauffement** limite pertes caloriques, hypercatabolisme et dénutrition.","src":"p. 93","kind":"piege"},{"id":"d114-ess-70","rank":"A","q":"Quelle conduite pour la biopsie cutanée d'une érythrodermie ?","text":"Elle peut montrer des signes spécifiques de la cause ; elle doit être **répétée** en cas de suspicion de **lymphome cutané**.","src":"p. 92","kind":"piege"},{"id":"d114-ess-71","rank":"B","q":"Mégalérythème épidémique : quand l'enfant est-il contagieux ?","text":"Contagiosité **limitée à la phase pré-éruptive** (incubation 14 jours) : à l'éruption, l'enfant n'est plus contagieux.","src":"p. 86","kind":"piege"},{"id":"d114-ess-72","rank":"B","q":"Comparez la desquamation de la scarlatine et celle du syndrome de Kawasaki ?","text":"Scarlatine : desquamation **fine ou en larges lambeaux**. Kawasaki : desquamation en **« doigt de gant »** (extrémités).","src":"p. 88","kind":"piege"},{"id":"d114-ess-73","rank":"B","q":"Biologie du Kawasaki : quelles anomalies attendre ?","text":"**Syndrome inflammatoire** : CRP élevée, **hyperleucocytose à PNN**, **thrombocytose** ; NFS, plaquettes et échographie cardiaque.","src":"p. 85, 88","kind":"piege"},{"id":"d114-ess-74","rank":"B","q":"Quelles sont les causes d'exanthème roséoliforme en dehors de l'exanthème subit ?","text":"**Rubéole**, **primo-infection VIH**, **syphilis secondaire** (1re floraison).","src":"p. 85, 83","kind":"B"},{"id":"d114-ess-75","rank":"B","q":"Quel est le tableau de la rubéole non compliquée ?","text":"Sujet de **15 à 25 ans**, exanthème **discret** de 2 à 4 jours, **arthralgies** et **conjonctivite** ; incubation 3 semaines ; contagieuse 7 jours avant et 14 jours après le début de l'éruption ; pas d'éviction de la collectivité.","src":"p. 85","kind":"B"},{"id":"d114-ess-76","rank":"B","q":"Quelle est la physiopathologie du syndrome de Kawasaki ?","text":"**Vasculite systémique aiguë** (adéno-cutanéo-muqueuse) de l'enfant < 5 ans ; diagnostic clinique, si au moins 5 des 6 critères.","src":"p. 88","kind":"B"},{"id":"d114-ess-77","rank":"B","q":"Sur quel terrain survient la scarlatine staphylococcique et quelle forme sévère redouter ?","text":"**Nouveau-né, nourrisson, jeune enfant** ou adulte immunodéprimé (*S. aureus* sécréteur de toxines) ; forme sévère : **choc toxique staphylococcique**.","src":"p. 88","kind":"B"},{"id":"d114-ess-78","rank":"B","q":"Devant quel contexte évoquer une épidermolyse staphylococcique ?","text":"**Nouveau-né** (infection du cordon), jeune enfant avec **impétigo** ; fièvre, altération de l'état général, lésions **péri-orificielles**, décollements bulleux.","src":"p. 82","kind":"B"},{"id":"d114-ess-79","rank":"B","q":"Que faire devant un exanthème scarlatiniforme fébrile brutal ?","text":"Rechercher un **syndrome du choc toxique staphylococcique** et dépister des signes de **retentissement hémodynamique**.","src":"p. 90","kind":"B"},{"id":"d114-ess-80","rank":"B","q":"Quel est le mécanisme du prurit et de la pachydermie de l'érythrodermie ?","text":"Le **prurit** est constant ; la **pachydermie**, mieux visible aux plis, traduit une **infiltration cellulaire spécifique** ; adénopathies généralisées souples et mobiles, parfois volumineuses.","src":"p. 90-91","kind":"B"},{"id":"d114-ess-81","rank":"B","q":"Quelles sont les étiologies de l'érythrodermie chez l'adulte (dermatoses, infections, hématologique) ?","text":"Psoriasis, eczéma/dermatite atopique, toxidermies (**DRESS**), **lichen plan** ; **Sézary** ; infections : **VIH**, **gale croûteuse** ; idiopathique (10-15 %).","src":"p. 91","kind":"B"},{"id":"d114-ess-82","rank":"B","q":"Quelle étiologie d'érythrodermie évoquer chez un nouveau-né ou un nourrisson de moins de 3 mois ?","text":"La **maladie de Leiner-Moussous** ; après 3 mois, surtout la **dermatite atopique** (puis causes de l'adulte).","src":"p. 91","kind":"B"}],"numbers":[{"id":"d114-num-01","rank":"A","label":"Érythrodermie : surface corporelle atteinte","value":"plus de 90 %","src":"p. 90"},{"id":"d114-num-02","rank":"A","label":"Érythrodermie : durée d'évolution","value":"depuis au moins 6 semaines","src":"p. 90, 93"},{"id":"d114-num-03","rank":"A","label":"Mortalité de l'érythrodermie","value":"jusqu'à 20 % (complications, surtout infectieuses)","src":"p. 93"},{"id":"d114-num-04","rank":"B","label":"Exanthème subit : âge de survenue","value":"nourrisson de 6 à 18 mois","src":"p. 85"},{"id":"d114-num-05","rank":"A","label":"Exanthème subit : durée de la fièvre isolée avant l'éruption","value":"48-72 heures (3 jours), 39-40 °C","src":"p. 85, 90"},{"id":"d114-num-06","rank":"B","label":"Rubéole : âge de survenue","value":"15 à 25 ans","src":"p. 85"},{"id":"d114-num-07","rank":"B","label":"Rubéole : incubation et contagiosité","value":"incubation 3 semaines ; contagieuse 7 jours avant et 14 jours après le début de l'éruption","src":"p. 85"},{"id":"d114-num-08","rank":"A","label":"Rougeole : incubation","value":"10-12 jours","src":"p. 86"},{"id":"d114-num-09","rank":"A","label":"Rougeole : contagiosité","value":"3-5 jours avant et 4 jours après l'éruption","src":"p. 86"},{"id":"d114-num-10","rank":"A","label":"Rougeole : éviction de la collectivité","value":"jusqu'à 5 jours après le début de l'éruption","src":"p. 86"},{"id":"d114-num-11","rank":"B","label":"Mégalérythème épidémique : âge de l'enfant","value":"5 à 10 ans","src":"p. 86"},{"id":"d114-num-12","rank":"A","label":"Mononucléose infectieuse : fréquence de l'exanthème (hors pénicilline A)","value":"inconstant : 5-10 %","src":"p. 86"},{"id":"d114-num-13","rank":"A","label":"Mononucléose infectieuse : incubation et contagiosité","value":"incubation 4 à 6 semaines ; contagiosité maximale en phase aiguë (jusqu'à 6 mois)","src":"p. 86"},{"id":"d114-num-14","rank":"A","label":"Scarlatine : âge, incubation et contagiosité","value":"enfant de 5 à 10 ans ; incubation 2 à 4 jours ; contagiosité 2 à 3 semaines","src":"p. 88"},{"id":"d114-num-15","rank":"A","label":"Scarlatine : éviction scolaire","value":"jusqu'à 48 heures après le début du traitement","src":"p. 88"},{"id":"d114-num-16","rank":"B","label":"Kawasaki : âge de l'enfant","value":"moins de 5 ans","src":"p. 88"},{"id":"d114-num-17","rank":"A","label":"Kawasaki : fièvre","value":"> 38,5 °C pendant plus de 5 jours (avec altération de l'état général)","src":"p. 88"},{"id":"d114-num-18","rank":"A","label":"Kawasaki : seuil diagnostique","value":"au moins 5 critères sur 6","src":"p. 88"},{"id":"d114-num-19","rank":"B","label":"Érythrodermie idiopathique : fréquence","value":"10 à 15 % des cas","src":"p. 91"}],"mnemonics":[{"id":"d114-mn-01","rank":"A","title":"Les 3 types d'exanthème : l'aspect à retenir","mnemonic":"ROSÉ séparé · MORBI intervalles · SCARLATI sans intervalle","expansion":"- **Roséoliforme** : petites macules **rosées**, pâles, **bien séparées**\n- **Morbilliforme** : maculo-papules rouges, plaques séparées par des **intervalles de peau saine**\n- **Scarlatiniforme** : plaques rouge vif, **sans intervalle de peau saine**, plus marquées dans les plis","src":"p. 85"},{"id":"d114-mn-02","rank":"B","title":"Causes principales de chaque type d'exanthème","mnemonic":"SRVS · RMM · SK","expansion":"- **S·R·V·S** (roséoliforme) : **S**ubit (exanthème subit), **R**ubéole, **V**IH (primo-infection), **S**yphilis secondaire\n- **R·M·M** (morbilliforme) : **R**ougeole, **M**égalérythème épidémique, **M**ononucléose infectieuse\n- **S·K** (scarlatiniforme) : **S**carlatine, syndrome de **K**awasaki","src":"p. 85-86, 88"},{"id":"d114-mn-03","rank":"A","title":"Les 6 critères du Kawasaki (5 sur 6)","mnemonic":"FÉE-CLE","expansion":"- **F**ièvre > 38,5 °C pendant plus de 5 jours\n- **É**nanthème : chéilite et langue framboisée\n- **E**xtrémités : érythème et œdème\n- **C**onjonctivite bilatérale (œdème des paupières)\n- **L**ymphadénite, souvent asymétrique\n- **E**xanthème polymorphe\n\nDiagnostic si **au moins 5 critères sur 6**.","src":"p. 88"},{"id":"d114-mn-04","rank":"A","title":"Les 4 causes principales d'érythrodermie","mnemonic":"PADS","expansion":"- **P**soriasis\n- **A**topie : dermatite atopique (eczéma)\n- **D**RESS : toxidermie\n- **S**ézary : lymphome cutané\n\nAussi : VIH, gale croûteuse.","src":"p. 91, 93"},{"id":"d114-mn-05","rank":"A","title":"Éviction de la collectivité","mnemonic":"Rougeole 5 j · Scarlatine 48 h · Rubéole 0","expansion":"- **Rougeole** : jusqu'à **5 jours** après le début de l'éruption\n- **Scarlatine** : jusqu'à **48 heures** après le début du traitement\n- **Rubéole** : **aucune** éviction recommandée (informer le personnel, les parents et la femme enceinte)","src":"p. 85-86, 88"},{"id":"d114-mn-06","rank":"B","title":"Sérologies de la femme enceinte devant un exanthème","mnemonic":"T-R-C-P-S","expansion":"- **T**oxoplasmose\n- **R**ubéole\n- **C**MV (cytomégalovirus)\n- **P**arvovirus B19\n- **S**yphilis","src":"p. 85"}]},"questions":[{"id":"d114-qroc-001","type":"QROC","rank":"A","objective":"d114-obj-01","tags":["définition"],"difficulty":1,"question":"Comment définit-on un exanthème ?","answer":"Un érythème d'apparition brutale et transitoire","accept":["érythème brutal et transitoire","érythème d'apparition brutale et transitoire"],"keywords":["érythème","brutal","transitoire"],"explanation":"Exanthème = érythème d'apparition brutale et transitoire. Il peut être intense ou non, diffus ou de topographie plus spécifique, isolé ou associé à d'autres symptômes, accompagné ou non d'une atteinte muqueuse (énanthème), bénin ou potentiellement grave (p. 84).","src":"p. 84","deep":"**Pourquoi** : « brutal » et « transitoire » l'opposent à l'érythrodermie, prolongée (au moins 6 semaines) et étendue à plus de 90 % de la peau avec desquamation (p. 90).\n**Piège** : la définition ne préjuge pas de la gravité : un exanthème peut être bénin ou potentiellement grave (p. 84).\n**À relier** : deux grandes causes : infectieuses (virales ou bactériennes) et médicamenteuses (p. 84)."},{"id":"d114-qroc-002","type":"QROC","rank":"A","objective":"d114-obj-10","tags":["étiologie"],"difficulty":1,"question":"Quelles infections sexuellement transmissibles faut-il évoquer devant un exanthème de l'adulte ?","answer":"La syphilis et le VIH","accept":["syphilis et vih","vih et syphilis","vih, syphilis"],"keywords":["syphilis","vih"],"explanation":"Chez l'adulte, les causes infectieuses d'exanthème à évoquer sont les IST, notamment la syphilis et le VIH ; il faut aussi penser aux médicaments (toxidermie) (p. 84, 90).","src":"p. 84, 90","deep":"**Pourquoi** : chez l'enfant, les exanthèmes fébriles sont le plus souvent viraux ; chez l'adulte, le Collège fait penser au VIH, à la syphilis et aux médicaments (p. 90).\n**À relier** : adulte sans cause évidente : test tréponémique, charge virale VIH, sérologie VIH combinée Ag-Ac p24, avec NFS, tests hépatiques et sérodiagnostic de MNI (rang B, p. 85).\n**Piège** : la primo-infection VIH figure à la fois parmi les exanthèmes roséoliformes et morbilliformes (p. 85-86)."},{"id":"d114-qroc-003","type":"QROC","rank":"A","objective":"d114-obj-03","tags":["clinique"],"difficulty":1,"question":"Quels sont les trois types séméiologiques d'exanthème ?","answer":"Roséoliforme, morbilliforme et scarlatiniforme","accept":["roséoliforme, morbilliforme, scarlatiniforme","rubéoliforme, morbilliforme, scarlatiniforme"],"keywords":["roséol","morbill","scarlat"],"explanation":"Trois types séméiologiques : roséoliforme (ou rubéoliforme), morbilliforme et scarlatiniforme. L'analyse de l'éruption s'intègre à la démarche avec l'anamnèse et les signes extracutanés et biologiques (p. 85).","src":"p. 85","deep":"**Pourquoi** : le type d'éruption oriente les causes : roséoliforme (exanthème subit, rubéole), morbilliforme (rougeole, mégalérythème, mononucléose), scarlatiniforme (scarlatine, Kawasaki) (tableaux 4.1-4.3, p. 85-88).\n**Piège** : « rubéoliforme » est un synonyme de roséoliforme, pas un 4e type (p. 85).\n**À relier** : repère commun, la peau saine : macules bien séparées (roséoliforme), plaques séparées par de la peau saine (morbilliforme), aucun intervalle (scarlatiniforme) (p. 85)."},{"id":"d114-qroc-004","type":"QROC","rank":"A","objective":"d114-obj-23","tags":["clinique"],"difficulty":1,"question":"Quel est l'aspect d'un exanthème roséoliforme ?","answer":"De petites macules rosées, pâles, bien séparées","accept":["petites macules rosées","macules rosées pâles bien séparées","petites macules rosées pâles"],"keywords":["macule","rosé"],"explanation":"Exanthème roséoliforme (ou rubéoliforme) : petites macules rosées, pâles, bien séparées les unes des autres (p. 85).","src":"p. 85","deep":"**Pourquoi** : petites, pâles et bien séparées, ces macules s'opposent au morbilliforme, maculo-papuleux et rouge, et au scarlatiniforme, rouge vif sans peau saine (p. 85).\n**À relier** : causes du tableau 4.1 : exanthème subit (HHV6, nourrisson), rubéole, primo-infection VIH et, en rang B, syphilis secondaire (p. 85).\n**Piège** : chez un nourrisson, une éruption roséoliforme après 3 jours de fièvre isolée évoque l'exanthème subit (p. 90)."},{"id":"d114-qroc-005","type":"QROC","rank":"A","objective":"d114-obj-19","tags":["clinique"],"difficulty":1,"question":"Comment se présente un exanthème morbilliforme ?","answer":"Maculo-papuleux rouge, confluant en plaques séparées de peau saine","accept":["maculo-papuleux rouges","maculo-papuleux","macules et papules rouges confluentes"],"keywords":["maculo","papul"],"explanation":"Exanthème morbilliforme : éléments maculo-papuleux rouges, pouvant confluer en plaques, mais séparées par des espaces de peau saine (p. 85).","src":"p. 85","deep":"**Pourquoi** : la persistance de peau saine entre les plaques le sépare du scarlatiniforme, qui n'en laisse aucune (p. 85).\n**À relier** : causes du tableau 4.2 : rougeole, mégalérythème épidémique, mononucléose infectieuse ; « autres » : primo-infection VIH, toxidermie (β-lactamines, sulfamides, anti-comitiaux…), syndrome de Kawasaki (p. 86).\n**Piège** : prurit, éruption polymorphe et hyperéosinophilie orientent vers un médicament (p. 85)."},{"id":"d114-qroc-006","type":"QROC","rank":"A","objective":"d114-obj-20","tags":["clinique","diagnostic"],"difficulty":2,"question":"Quel caractère distingue un exanthème scarlatiniforme d'un exanthème morbilliforme quant à la peau entre les plaques ?","answer":"Aucun intervalle de peau saine (plaques diffuses rouge vif)","accept":["sans intervalle de peau saine","pas de peau saine","absence de peau saine","pas d'intervalle de peau saine","aucun intervalle de peau saine"],"keywords":[],"explanation":"Exanthème scarlatiniforme : plaques diffuses rouge vif, légèrement granitées à la palpation, sans intervalle de peau saine, chaudes ou cuisantes, s'intensifiant dans les plis, pouvant évoluer vers une desquamation secondaire en larges lambeaux (p. 85).","src":"p. 85","deep":"**Pourquoi** : l'absence de peau saine le sépare du morbilliforme, dont les plaques restent séparées par des espaces de peau saine (p. 85).\n**À relier** : le tableau 4.3 des exanthèmes scarlatiniformes réunit scarlatine (streptocoque A), épidermolyse staphylococcique et syndrome de Kawasaki (p. 88).\n**Piège** : un exanthème scarlatiniforme diffus, fébrile et brutal doit faire rechercher un choc toxique staphylococcique (rang B, p. 90)."},{"id":"d114-qroc-007","type":"QROC","rank":"A","objective":"d114-obj-03","tags":["diagnostic","étiologie"],"difficulty":2,"question":"Citez les trois signes en faveur d'une origine médicamenteuse d'un exanthème.","answer":"Prurit, éruption polymorphe, hyperéosinophilie sanguine","accept":["prurit, polymorphisme, hyperéosinophilie","prurit, polymorphe, hyperéosinophilie"],"keywords":["prurit","polymorph","éosinophil"],"explanation":"Origine médicamenteuse : prurit, caractère polymorphe de l'éruption, hyperéosinophilie sanguine. À l'inverse, fièvre, syndrome grippal, énanthème et poly-adénopathie orientent vers une origine virale (p. 85).","src":"p. 85","deep":"**Pourquoi** : ces signes extracutanés et biologiques sont dits indispensables pour orienter le diagnostic, avec l'anamnèse (contexte épidémique, contage, prise médicamenteuse) (p. 85).\n**Piège** : chez l'adulte, penser aux médicaments (toxidermie) en plus du VIH et de la syphilis (p. 90).\n**À relier** : toxidermies citées parmi les exanthèmes morbilliformes : β-lactamines, sulfamides, anti-comitiaux… (p. 86)."},{"id":"d114-qroc-008","type":"QROC","rank":"A","objective":"d114-obj-16","tags":["diagnostic","clinique"],"difficulty":1,"question":"Quels trois éléments associés font évoquer une rougeole ?","answer":"Catarrhe oculo-nasal, conjonctivite et exanthème fébrile","accept":["catarrhe oculo-nasal, conjonctivite, exanthème fébrile","catarrhe oculo-nasal, conjonctivite et exanthème"],"keywords":["catarrhe","conjonctivite","exanthème"],"explanation":"Il faut savoir évoquer une rougeole, chez l'enfant comme chez l'adulte, devant l'association catarrhe oculo-nasal + conjonctivite + exanthème fébrile (p. 83, 90).","src":"p. 90","deep":"**Pourquoi** : ces signes appartiennent à la phase pré-éruptive (catarrhe, fièvre 39-40 °C, signe de Köplick, conjonctivite) ; l'exanthème débute ensuite en rétro-auriculaire et s'étend en une seule poussée (p. 86).\n**À relier** : maladie à déclaration obligatoire ; éviction de la collectivité jusqu'à 5 jours après le début de l'éruption ; informer le personnel et les parents (p. 86).\n**Piège** : la contagiosité commence 3 à 5 jours avant l'éruption (p. 86)."},{"id":"d114-qroc-009","type":"QROC","rank":"A","objective":"d114-obj-26","tags":["clinique"],"difficulty":1,"question":"Comment s'appelle le semis de papules de la face interne des joues observé dans la phase pré-éruptive de la rougeole ?","answer":"Le signe de Köplick","accept":["signe de köplick","köplick","koplick"],"keywords":["koplick"],"explanation":"Signe de Köplick : semis de papules à la face interne des joues, en phase pré-éruptive de la rougeole, avec catarrhe oculo-nasal, fièvre élevée (39-40 °C) et conjonctivite (p. 86).","src":"p. 86","deep":"**Pourquoi** : c'est une atteinte muqueuse (énanthème) présente dès la phase pré-éruptive, avant l'exanthème rétro-auriculaire (p. 84, 86).\n**Piège** : ne pas le confondre avec la langue framboisée, énanthème de la scarlatine et du Kawasaki (p. 88).\n**À relier** : un énanthème est un signe extracutané en faveur d'une origine virale de l'exanthème (p. 85)."},{"id":"d114-qroc-010","type":"QROC","rank":"A","objective":"d114-obj-26","tags":["complications"],"difficulty":2,"question":"Quelle complication neurologique grave peut compliquer la rougeole ?","answer":"Une encéphalite","accept":["encéphalite","une encéphalite"],"keywords":["encéphal"],"explanation":"Complications de la rougeole : pneumopathie, hépatite, pancréatite, encéphalite (grave), kératite et cécité (p. 86).","src":"p. 86","deep":"**Pourquoi** : le Collège qualifie l'encéphalite de grave ; les autres complications touchent poumon, foie, pancréas et œil (kératite, cécité) (p. 86).\n**Piège** : ne pas la confondre avec la méningo-encéphalite, complication rare de la mononucléose, ni avec la méningite virale de l'exanthème subit (p. 85-86).\n**À relier** : autour d'un cas : déclaration obligatoire, éviction jusqu'à 5 jours après le début de l'éruption, information du personnel et des parents (p. 86)."},{"id":"d114-qroc-011","type":"QROC","rank":"A","objective":"d114-obj-29","tags":["étiologie","pédiatrie"],"difficulty":1,"question":"Quel virus est responsable de l'exanthème subit (roséole infantile) ?","answer":"Le virus HHV6 (herpèsvirus humain 6)","accept":["hhv6","hhv 6","herpèsvirus humain 6","human herpesvirus 6"],"keywords":[],"explanation":"L'exanthème subit (roséole infantile) est la primo-infection par le virus HHV6 (human herpesvirus 6), chez le nourrisson de 6 à 18 mois (p. 85).","src":"p. 85","deep":"**Pourquoi** : fièvre à 39-40 °C isolée pendant 48-72 heures, puis exanthème prédominant sur le tronc, en une seule poussée (p. 85).\n**Piège** : dans le tableau 4.1, « souvent asymptomatique » concerne l'exanthème subit, alors que « pas de recommandation d'éviction » figure dans la colonne rubéole (p. 85).\n**À relier** : complications rares : convulsions fébriles, méningite virale, hépatite aiguë, pneumopathie, syndrome mononucléosique (p. 85)."},{"id":"d114-qroc-012","type":"QROC","rank":"A","objective":"d114-obj-25","tags":["diagnostic","pédiatrie"],"difficulty":2,"question":"Chez un nourrisson, quel diagnostic évoque une éruption roséoliforme apparue après 3 jours de fièvre isolée ?","answer":"L'exanthème subit (roséole infantile)","accept":["exanthème subit","roséole infantile","roséole"],"keywords":[],"explanation":"Éruption roséoliforme d'un nourrisson après 3 jours de fièvre isolée = exanthème subit (roséole infantile), primo-infection HHV6 (p. 85, 90).","src":"p. 85, 90","deep":"**Pourquoi** : séquence typique : fièvre 39-40 °C isolée 48-72 heures, puis exanthème prédominant sur le tronc, en une seule poussée, chez le nourrisson de 6 à 18 mois (p. 85).\n**Piège** : la rougeole a aussi une fièvre élevée avant l'éruption, mais avec catarrhe oculo-nasal, conjonctivite et un exanthème morbilliforme débutant en rétro-auriculaire (p. 86).\n**À relier** : complications rares, dont les convulsions fébriles (p. 85)."},{"id":"d114-qroc-013","type":"QROC","rank":"A","objective":"d114-obj-27","tags":["grossesse","complications"],"difficulty":1,"question":"Quel risque fait redouter la rubéole chez une femme enceinte non immunisée ?","answer":"Mort fœtale ou malformations fœtales graves","accept":["malformations fœtales","malformations","mort fœtale"],"keywords":["malformation"],"explanation":"Chez la femme enceinte non immunisée, la rubéole expose au risque de mort fœtale ou de malformations (neurologiques, sensorielles), qualifiées de graves dans les points clés (p. 85, 90).","src":"p. 85, 90","deep":"**Pourquoi** : l'exanthème de la rubéole est discret (2 à 4 jours), mais la complication retenue par le tableau 4.1 porte sur le fœtus (p. 85).\n**À relier** : pas de recommandation d'éviction de la collectivité, mais information du personnel, des parents et de la femme enceinte (p. 85).\n**Piège** : le parvovirus B19, lui, n'est pas tératogène : son risque est l'anasarque fœtale (infection au 2e trimestre) (p. 86)."},{"id":"d114-qroc-014","type":"QROC","rank":"A","objective":"d114-obj-28","tags":["étiologie","pédiatrie"],"difficulty":1,"question":"Quel virus est responsable du mégalérythème épidémique ?","answer":"Le parvovirus B19","accept":["parvovirus b19","parvovirus","b19"],"keywords":["parvovirus"],"explanation":"Mégalérythème épidémique = parvovirus B19 ; enfant de 5 à 10 ans, incubation 14 jours, contagiosité limitée à la phase pré-éruptive (p. 86).","src":"p. 86","deep":"**À relier** : fièvre modérée, érythème et œdème des joues, érythème du tronc à bords émiettés, érythème en gants et chaussettes, arthralgies (p. 86) ; en légende (rang B), visage « souffleté » (fig. 4.1, p. 87).\n**Piège** : contagiosité limitée à la phase pré-éruptive, à l'inverse de la rougeole (3-5 jours avant à 4 jours après l'éruption) (p. 86).\n**Pourquoi** : les complications surviennent surtout chez l'immunodéprimé, le patient avec anémie chronique et la femme enceinte (p. 86)."},{"id":"d114-qroc-015","type":"QROC","rank":"A","objective":"d114-obj-28","tags":["clinique"],"difficulty":2,"question":"Quel aspect prend l'éruption des extrémités dans le mégalérythème épidémique ?","answer":"Un érythème en « gants et chaussettes »","accept":["gants et chaussettes","gants chaussettes"],"keywords":["gant","chaussette"],"explanation":"Mégalérythème épidémique : atteinte érythémateuse et œdème des joues, puis érythème du tronc à bords émiettés ; érythème dit en « gants et chaussettes » ; arthralgies (p. 86-87).","src":"p. 86-87","deep":"**Pourquoi** : l'atteinte œdémateuse du visage et l'éruption en gants et chaussettes sont les deux éléments que le Collège demande de reconnaître (objectif de rang B, p. 82).\n**Piège** : l'érythème et l'œdème des extrémités existent aussi dans le Kawasaki, mais avec une fièvre > 38,5 °C plus de 5 jours et une conjonctivite bilatérale (p. 88).\n**À relier** : en légende (rang B), visage « souffleté » et exanthème figuré en guirlande (fig. 4.1-4.2, p. 87)."},{"id":"d114-qroc-016","type":"QROC","rank":"A","objective":"d114-obj-28","tags":["grossesse","complications"],"difficulty":1,"question":"Quel risque fœtal expose la primo-infection à parvovirus B19 pendant la grossesse ?","answer":"Une anasarque fœtale","accept":["anasarque fœtale","anasarque"],"keywords":["anasarque"],"explanation":"Primo-infection à parvovirus B19 pendant la grossesse : pas de risque tératogène, mais en cas d'infection au 2e trimestre, risque d'anasarque fœtale, de myocardite et d'anémie fœtale (p. 86, 90).","src":"p. 86, 90","deep":"**Pourquoi** : les complications du parvovirus B19 surviennent surtout chez l'immunodéprimé, le patient avec anémie chronique et la femme enceinte (p. 86).\n**Piège** : c'est la rubéole qui expose à la mort fœtale ou aux malformations, pas le parvovirus (p. 85).\n**À relier** : femme enceinte avec exanthème : sérologies toxoplasmose, rubéole, CMV, parvovirus B19 et syphilis selon le statut de début de grossesse (rang B, p. 85)."},{"id":"d114-qroc-017","type":"QROC","rank":"A","objective":"d114-obj-30","tags":["étiologie"],"difficulty":1,"question":"Quel virus est responsable de la mononucléose infectieuse ?","answer":"Le virus d'Epstein-Barr (EBV)","accept":["ebv","epstein-barr","virus d'epstein-barr"],"keywords":["epstein"],"explanation":"Mononucléose infectieuse = virus d'Epstein-Barr (EBV) ; adolescent ; incubation 4 à 6 semaines ; fièvre-asthénie importante, poly-adénopathie, splénomégalie, exanthème inconstant (p. 86).","src":"p. 86","deep":"**Piège** : l'exanthème est inconstant (5-10 %), sauf si une pénicilline A est prescrite : c'est le rash à l'ampicilline, à ne pas prendre pour une toxidermie (rang B, p. 82, 86).\n**À relier** : contagiosité maximale en phase aiguë, pouvant aller jusqu'à 6 mois ; NFS : lymphocytose élevée à lymphocytes hyperbasophiles (p. 86)."},{"id":"d114-qroc-018","type":"QROC","rank":"A","objective":"d114-obj-30","tags":["biologie","diagnostic"],"difficulty":2,"question":"Quelle anomalie de la NFS caractérise la mononucléose infectieuse ?","answer":"Une lymphocytose avec lymphocytes hyperbasophiles","accept":["lymphocytes hyperbasophiles","lymphocytose hyperbasophile","hyperbasophiles"],"keywords":["lymphocyt","hyperbasophil"],"explanation":"NFS de la mononucléose infectieuse : lymphocytose élevée avec lymphocytes hyperbasophiles (p. 86).","src":"p. 86","deep":"**Pourquoi** : elle s'inscrit dans un tableau d'adolescent avec fièvre-asthénie importante, poly-adénopathie et splénomégalie (p. 86).\n**Piège** : l'agranulocytose existe, mais comme complication rare, avec l'hépatite, la méningo-encéphalite et la rupture splénique (p. 86).\n**À relier** : chez l'adulte avec exanthème sans cause évidente, NFS et sérodiagnostic de MNI font partie du bilan (rang B, p. 85)."},{"id":"d114-qroc-019","type":"QROC","rank":"A","objective":"d114-obj-31","tags":["étiologie"],"difficulty":1,"question":"Quel germe est responsable de la scarlatine ?","answer":"Le streptocoque du groupe A","accept":["streptocoque du groupe a","streptocoque a"],"keywords":["streptocoque"],"explanation":"Scarlatine = streptocoque du groupe A sécréteur d'exotoxines ; enfant de 5 à 10 ans ; incubation 2 à 4 jours ; contamination par voie aérienne (p. 88).","src":"p. 88","deep":"**Pourquoi** : phase pré-éruptive brutale (fièvre 39-40 °C, douleurs pharyngées, céphalées, angine rouge, adénopathies sous-maxillaires), puis éruption prédominant aux grands plis et langue framboisée (p. 88).\n**Piège** : la scarlatine staphylococcique (Staphylococcus aureus) se distingue par l'absence d'angine (p. 88).\n**À relier** : contagiosité de 2 à 3 semaines, qui persiste 48 heures après la mise en route du traitement (p. 88)."},{"id":"d114-qroc-020","type":"QROC","rank":"A","objective":"d114-obj-31","tags":["traitement"],"difficulty":1,"question":"Quel antibiotique est prescrit dans la scarlatine ?","answer":"L'amoxicilline","accept":["amoxicilline","l'amoxicilline"],"keywords":["amoxicilline"],"explanation":"Scarlatine : prélèvement de gorge et antibiothérapie par amoxicilline ; éviction de la collectivité jusqu'à 48 heures après le début du traitement (p. 88).","src":"p. 88","deep":"**Pourquoi** : la scarlatine est due au streptocoque du groupe A (p. 88).\n**Piège** : la scarlatine staphylococcique (épidermolyse staphylococcique) se traite par oxacilline, pas par amoxicilline (p. 88).\n**À relier** : la contagiosité persiste 48 heures après la mise en route du traitement, et l'éviction dure jusqu'à 48 heures après son début ; complications post-streptococciques : glomérulonéphrites, RAA (p. 88)."},{"id":"d114-qroc-021","type":"QROC","rank":"A","objective":"d114-obj-31","tags":["complications"],"difficulty":2,"question":"Quelles complications post-streptococciques peuvent suivre une scarlatine ?","answer":"Glomérulonéphrites et rhumatisme articulaire aigu","accept":["glomérulonéphrite et rhumatisme articulaire aigu","glomérulonéphrites, rhumatisme articulaire aigu"],"keywords":["glomérulo","rhumatisme"],"explanation":"Complications post-streptococciques de la scarlatine : glomérulonéphrites et rhumatisme articulaire aigu (p. 88).","src":"p. 88","deep":"**Pourquoi** : la scarlatine est due au streptocoque du groupe A sécréteur d'exotoxines (p. 88).\n**Piège** : anévrismes coronariens et troubles du rythme sont les complications du Kawasaki, autre exanthème scarlatiniforme (p. 88).\n**À relier** : prise en charge : prélèvement de gorge, amoxicilline, éviction de la collectivité jusqu'à 48 heures après le début du traitement (p. 88)."},{"id":"d114-qroc-022","type":"QROC","rank":"A","objective":"d114-obj-07","tags":["traitement","pédiatrie"],"difficulty":2,"question":"Quel antibiotique traite la scarlatine staphylococcique (épidermolyse staphylococcique) ?","answer":"L'oxacilline","accept":["oxacilline","l'oxacilline"],"keywords":["oxacilline"],"explanation":"Épidermolyse staphylococcique (scarlatine staphylococcique) : Staphylococcus aureus sécréteur d'entérotoxines ou de TSST1 ; prélèvements bactériologiques ; antibiothérapie par oxacilline ; éviction scolaire jusqu'à 48 heures après le début du traitement (p. 88).","src":"p. 88","deep":"**Pourquoi** : terrain : nouveau-né (infection du cordon), nourrisson, jeune enfant (impétigo) ou adulte immunodéprimé ; pas d'angine ; exanthème des grands plis et péri-orificiel, puis décollement bulleux (p. 82, 88).\n**Piège** : sa forme sévère est le choc toxique staphylococcique (p. 88).\n**À relier** : la scarlatine streptococcique, elle, se traite par amoxicilline (p. 88)."},{"id":"d114-qroc-023","type":"QROC","rank":"A","objective":"d114-obj-32","tags":["définition","pédiatrie"],"difficulty":1,"question":"Quelle est la nature du syndrome de Kawasaki ?","answer":"Une vasculite systémique aiguë","accept":["vasculite systémique aiguë","vasculite systémique","vasculite"],"keywords":["vasculite"],"explanation":"Le syndrome de Kawasaki (syndrome adéno-cutanéo-muqueux) est une vasculite systémique aiguë de l'enfant de moins de 5 ans (p. 88).","src":"p. 88","deep":"**À relier** : complications cardiaques : anévrismes coronariens, troubles du rythme ; décès par myocardite ou infarctus ; hospitalisation indispensable (p. 88) ; le retard thérapeutique expose aux anévrismes coronariens (p. 90).\n**Piège** : il figure parmi les causes principales d'exanthème scarlatiniforme (tableau 4.3), mais aussi dans les « autres » causes d'exanthème morbilliforme (tableau 4.2) (p. 86, 88)."},{"id":"d114-qroc-024","type":"QROC","rank":"A","objective":"d114-obj-08","tags":["diagnostic","clinique"],"difficulty":2,"question":"Quelle fièvre est exigée parmi les critères du syndrome de Kawasaki ?","answer":"Fièvre > 38,5 °C pendant plus de 5 jours","accept":["> 38,5 °c plus de 5 jours","38,5 plus de 5 jours","supérieure à 38,5 pendant plus de 5 jours","plus de 38,5 pendant plus de 5 jours","38,5 °c pendant plus de 5 jours"],"keywords":["38,5","5 jours"],"explanation":"Kawasaki : fièvre élevée > 38,5 °C plus de 5 jours avec altération de l'état général ; s'y associent conjonctivite bilatérale avec œdème des paupières, chéilite et langue framboisée, érythème et œdème des extrémités, exanthème polymorphe, lymphadénite souvent asymétrique (p. 88).","src":"p. 88","deep":"**Piège** : la scarlatine a aussi fièvre et langue framboisée, mais chez l'enfant de 5 à 10 ans, avec angine rouge et éruption des grands plis (p. 88).\n**À relier** : diagnostic si au moins 5 des 6 critères sont présents ; biologie : CRP élevée, hyperleucocytose à PNN, thrombocytose (p. 88)."},{"id":"d114-qroc-025","type":"QROC","rank":"A","objective":"d114-obj-32","tags":["diagnostic"],"difficulty":2,"question":"Combien de critères diagnostiques sur six faut-il réunir pour poser le diagnostic de syndrome de Kawasaki ?","answer":"Au moins 5 sur 6","accept":["5 sur 6","au moins 5","cinq sur six","au moins cinq","5 critères sur 6"],"keywords":["5"],"explanation":"Le diagnostic de Kawasaki est retenu si au moins cinq des six critères diagnostiques sont présents (p. 88).","src":"p. 88","deep":"**Pourquoi** : éléments cliniques du tableau 4.3 : fièvre > 38,5 °C plus de 5 jours, conjonctivite bilatérale, énanthème (chéilite, langue framboisée), érythème et œdème des extrémités, exanthème polymorphe, lymphadénite (p. 88).\n**Piège** : ne pas mélanger les « 5 jours » de fièvre et les « 5 critères sur 6 » (p. 88).\n**À relier** : suspicion chez l'enfant : NFS, plaquettes et échographie cardiaque (rang B, p. 85)."},{"id":"d114-qroc-026","type":"QROC","rank":"A","objective":"d114-obj-32","tags":["complications"],"difficulty":1,"question":"Quelle complication cardiaque redoute-t-on dans la maladie de Kawasaki en cas de retard thérapeutique ?","answer":"Des anévrismes coronariens","accept":["anévrismes coronariens","anévrisme coronarien","anévrismes coronaires"],"keywords":["anévr"],"explanation":"Kawasaki : le retard thérapeutique expose aux anévrismes coronariens ; autres complications cardiaques : troubles du rythme, décès par myocardite ou infarctus (p. 88, 90).","src":"p. 88, 90","deep":"**À relier** : hospitalisation indispensable ; en cas de suspicion chez l'enfant, NFS, plaquettes et échographie cardiaque (rang B) (p. 85, 88).\n**Piège** : la scarlatine, autre exanthème scarlatiniforme, se complique de glomérulonéphrites et de RAA, pas d'anévrismes (p. 88)."},{"id":"d114-qroc-027","type":"QROC","rank":"A","objective":"d114-obj-24","tags":["urgence","pédiatrie"],"difficulty":1,"question":"Quelle orientation est indispensable pour un enfant atteint de syndrome de Kawasaki ?","answer":"Une hospitalisation","accept":["hospitalisation","une hospitalisation"],"keywords":["hospitalis"],"explanation":"Kawasaki : hospitalisation indispensable (p. 88). Le retard thérapeutique expose aux anévrismes coronariens (p. 90).","src":"p. 88","deep":"**Pourquoi** : en cas de retard thérapeutique, le Kawasaki expose aux anévrismes coronariens ; ses complications cardiaques vont jusqu'au décès par myocardite ou infarctus (p. 88, 90).\n**À relier** : biologie : syndrome inflammatoire avec CRP élevée, hyperleucocytose à PNN, thrombocytose (p. 88).\n**Piège** : dans le tableau d'objectifs, l'orientation (hospitalisation) est de rang A, la prise en charge de rang B (p. 84)."},{"id":"d114-qroc-028","type":"QROC","rank":"A","objective":"d114-obj-02","tags":["définition"],"difficulty":1,"question":"Quelle surface corporelle minimale est touchée dans une érythrodermie ?","answer":"Plus de 90 %","accept":["90 %","plus de 90 %","90"],"keywords":["90"],"explanation":"Érythrodermie : érythème confluant avec desquamation touchant l'ensemble des téguments, soit plus de 90 % de la surface corporelle (p. 90).","src":"p. 90","deep":"**Piège** : une éruption érythémato-squameuse faite d'éléments multiples séparés par de la peau saine n'est pas une érythrodermie (p. 91).\n**À relier** : durée : « au moins 6 semaines » dans le texte (p. 90, 93), alors que le tableau d'objectifs indique « < 6 semaines » (p. 82).\n**Pourquoi** : c'est un syndrome rare, de diagnostic clinique, aux multiples étiologies (p. 90)."},{"id":"d114-qroc-029","type":"QROC","rank":"A","objective":"d114-obj-02","tags":["définition"],"difficulty":1,"question":"Depuis combien de temps minimum l'érythème doit-il évoluer pour parler d'érythrodermie ?","answer":"Au moins 6 semaines","accept":["6 semaines","6 semaines minimum","au moins 6 semaines"],"keywords":["6"],"explanation":"L'érythrodermie évolue depuis au moins 6 semaines (évolution prolongée) selon le texte (p. 90, 93) ; le tableau d'objectifs écrit « < 6 semaines » (p. 82).","src":"p. 90-91, 93","deep":"**Pourquoi** : la durée l'oppose à l'exanthème et à la nécrolyse épidermique avec décollement, d'évolution aiguë, qui ne sont pas des érythrodermies (p. 91).\n**Piège** : érythrodermie n'est pas synonyme d'érythème ou d'exanthème (p. 93).\n**À relier** : contradiction du Collège : « au moins 6 semaines » (p. 90, 93) contre « < 6 semaines » dans le tableau d'objectifs (p. 82)."},{"id":"d114-qroc-030","type":"QROC","rank":"A","objective":"d114-obj-21","tags":["clinique"],"difficulty":2,"question":"Comment est l'érythème d'une érythrodermie aux zones déclives ?","answer":"Plus violacé","accept":["plus violacé","violacé"],"keywords":["violac"],"explanation":"Dans l'érythrodermie, l'érythème est plus violacé aux zones déclives ; il est généralisé et inflammatoire, son intensité change d'un jour à l'autre et son installation est plus ou moins rapide (p. 90).","src":"p. 90","deep":"**À relier** : autres signes : desquamation et prurit constants, dysrégulation thermique (fièvre, hypothermie), pachydermie des plis, œdème du visage (ectropion possible), poly-adénopathie (p. 90-91).\n**Piège** : l'aspect clinique de l'érythrodermie ne préjuge pas de sa cause (p. 93)."},{"id":"d114-qroc-031","type":"QROC","rank":"A","objective":"d114-obj-09","tags":["urgence","traitement"],"difficulty":1,"question":"Quelle prise en charge nécessite une érythrodermie ?","answer":"Une hospitalisation en urgence (service spécialisé)","accept":["hospitalisation en urgence","hospitalisation urgente","hospitalisation"],"keywords":["hospitalis"],"explanation":"L'érythrodermie est une urgence dermatologique : hospitalisation en urgence dans un service spécialisé (p. 90-91, 93).","src":"p. 90, 93","deep":"**À relier** : à l'hôpital : examens biologiques de gravité, rééquilibration hydro-électrolytique, traitement des défaillances viscérales, recherche étiologique, réchauffement (p. 93).\n**Piège** : la prise en charge est immédiate sur deux plans à la fois, thérapeutique et étiologique (p. 90)."},{"id":"d114-qroc-032","type":"QROC","rank":"A","objective":"d114-obj-09","tags":["diagnostic","traitement"],"difficulty":2,"question":"Quelles sont les trois étapes de la prise en charge d'une érythrodermie ?","answer":"Reconnaître, chercher l'étiologie, apprécier la gravité","accept":["reconnaître l'érythrodermie, rechercher l'étiologie, apprécier la gravité","reconnaître, rechercher l'étiologie, apprécier la gravité"],"keywords":["reconna","étiolog","gravité"],"explanation":"Trois étapes : 1) reconnaître l'érythrodermie ; 2) chercher sa cause, pour un éventuel traitement spécifique ; 3) évaluer la gravité immédiate et proposer un traitement symptomatique (p. 90).","src":"p. 90","deep":"**Pourquoi** : c'est un syndrome de diagnostic clinique aux multiples étiologies, d'où une recherche de cause en vue d'un éventuel traitement spécifique (p. 90).\n**Piège** : l'aspect clinique ne préjuge pas de la cause (p. 93).\n**À relier** : la gravité est corrélée au terrain et aux complications (hydro-électrolytiques, décubitus, infections) (p. 92-93)."},{"id":"d114-qroc-033","type":"QROC","rank":"A","objective":"d114-obj-17","tags":["étiologie"],"difficulty":1,"question":"Quel lymphome T cutané épidermotrope peut se présenter sous la forme d'une érythrodermie ?","answer":"Le syndrome de Sézary","accept":["syndrome de sézary","sézary"],"keywords":["sézary"],"explanation":"Le syndrome de Sézary, lymphome T cutané épidermotrope, est une cause majeure (+++) d'érythrodermie de l'adulte (p. 91-92).","src":"p. 91-92","deep":"**Pourquoi** : la biopsie cutanée peut montrer des signes histologiques spécifiques de la maladie responsable (p. 92).\n**Piège** : en cas de suspicion de lymphome cutané, la biopsie doit être répétée (p. 92).\n**À relier** : autres causes de l'adulte : psoriasis, eczéma/dermatite atopique, toxidermie (DRESS) (+++), gale croûteuse (++), VIH (+) (p. 91)."},{"id":"d114-qroc-034","type":"QROC","rank":"A","objective":"d114-obj-17","tags":["étiologie"],"difficulty":1,"question":"Quelle toxidermie est une cause d'érythrodermie ?","answer":"Le DRESS","accept":["dress","le dress"],"keywords":["dress"],"explanation":"DRESS = Drug Rash with hyper-Eosinophilia and Systemic Symptoms : toxidermie, cause principale (+++) d'érythrodermie (p. 91, 93).","src":"p. 91, 93","deep":"**À relier** : l'interrogatoire recherche une prise médicamenteuse et les traitements topiques utilisés (p. 91).\n**Piège** : la nécrolyse épidermique avec décollement, d'évolution aiguë, n'est pas une érythrodermie (p. 91).\n**Pourquoi** : l'hyperéosinophilie sanguine est aussi un argument pour l'origine médicamenteuse d'un exanthème (p. 85)."},{"id":"d114-qroc-035","type":"QROC","rank":"A","objective":"d114-obj-06","tags":["complications"],"difficulty":1,"question":"Quelle mortalité peut atteindre l'érythrodermie ?","answer":"Jusqu'à 20 %","accept":["20 %","20","jusqu'à 20 %"],"keywords":["20"],"explanation":"La mortalité de l'érythrodermie peut atteindre 20 %, liée aux complications, notamment infectieuses (p. 93).","src":"p. 93","deep":"**Pourquoi** : la gravité est corrélée au terrain et aux complications (p. 92).\n**À relier** : infections surtout cutanées bactériennes (staphylocoque) ou virales (herpès, varicelle-zona), ou générales (pneumopathies, septicémies) (p. 93).\n**Piège** : la déperdition hydro-électrolytique peut décompenser une insuffisance cardiaque, respiratoire ou rénale (p. 93)."},{"id":"d114-qroc-036","type":"QROC","rank":"B","objective":"d114-obj-05","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quelle éruption survient chez un patient atteint de mononucléose infectieuse traité par pénicilline A, et ne doit pas être confondue avec une toxidermie ?","answer":"Un exanthème : le rash à l'ampicilline","accept":["rash à l'ampicilline","rash ampicilline","rash aux pénicillines a","exanthème à l'ampicilline"],"keywords":[],"explanation":"L'exanthème de la mononucléose est inconstant (5-10 %), sauf en cas de prescription de pénicilline A : c'est le rash à l'ampicilline, complication classique à ne pas confondre avec une toxidermie aux pénicillines (p. 82, 86).","src":"p. 82, 86","deep":"**Pourquoi** : sans pénicilline A, l'exanthème de la mononucléose n'apparaît que dans 5-10 % des cas (p. 86).\n**À relier** : les β-lactamines figurent parmi les toxidermies morbilliformes (p. 86), et prurit, polymorphisme et hyperéosinophilie orientent vers un médicament (p. 85).\n**Piège** : tableau de MNI : adolescent, fièvre-asthénie importante, poly-adénopathie, splénomégalie (p. 86)."},{"id":"d114-qroc-037","type":"QROC","rank":"A","objective":"d114-obj-04","tags":["épidémiologie","pédiatrie"],"difficulty":1,"question":"Quel est le terrain classique du mégalérythème épidémique ?","answer":"L'enfant de 5 à 10 ans","accept":["enfant de 5 à 10 ans","5 à 10 ans","5-10 ans"],"keywords":["5","10"],"explanation":"Le mégalérythème épidémique (parvovirus B19) touche l'enfant de 5 à 10 ans ; incubation 14 jours (p. 86).","src":"p. 86","deep":"**Piège** : la scarlatine touche aussi l'enfant de 5 à 10 ans, alors que le Kawasaki concerne l'enfant de moins de 5 ans et l'exanthème subit le nourrisson de 6 à 18 mois (p. 85, 88).\n**À relier** : fièvre modérée, érythème et œdème des joues, érythème du tronc à bords émiettés, gants et chaussettes, arthralgies (p. 86)."},{"id":"d114-qroc-038","type":"QROC","rank":"A","objective":"d114-obj-29","tags":["épidémiologie","pédiatrie"],"difficulty":1,"question":"Quel est l'âge de survenue de l'exanthème subit ?","answer":"Nourrisson de 6 à 18 mois","accept":["6 à 18 mois","6-18 mois"],"keywords":["6","18"],"explanation":"L'exanthème subit survient chez le nourrisson de 6 à 18 mois, après une fièvre à 39-40 °C isolée pendant 48 à 72 heures (p. 85).","src":"p. 85","deep":"**Piège** : âges à ne pas mélanger : rubéole 15 à 25 ans, Kawasaki < 5 ans, scarlatine et mégalérythème 5 à 10 ans, mononucléose à l'adolescence (p. 85-88).\n**À relier** : chez un nourrisson, une éruption roséoliforme après 3 jours de fièvre isolée évoque l'exanthème subit (p. 90)."},{"id":"d114-qroc-039","type":"QROC","rank":"A","objective":"d114-obj-32","tags":["épidémiologie","pédiatrie"],"difficulty":1,"question":"Quel est le terrain habituel du syndrome de Kawasaki ?","answer":"L'enfant de moins de 5 ans","accept":["moins de 5 ans","enfant de moins de 5 ans"],"keywords":["5"],"explanation":"Le syndrome de Kawasaki est une vasculite systémique aiguë de l'enfant de moins de 5 ans (p. 88).","src":"p. 88","deep":"**Piège** : la scarlatine, autre exanthème scarlatiniforme avec langue framboisée, touche l'enfant de 5 à 10 ans (p. 88).\n**À relier** : fièvre > 38,5 °C plus de 5 jours, au moins 5 critères sur 6, hospitalisation indispensable ; risque d'anévrismes coronariens en cas de retard thérapeutique (p. 88, 90)."},{"id":"d114-qroc-040","type":"QROC","rank":"B","objective":"d114-obj-25","tags":["paraclinique","pédiatrie"],"difficulty":2,"question":"Chez l'enfant, quel examen complémentaire est indispensable devant un exanthème ?","answer":"Aucun (sauf suspicion de scarlatine ou de Kawasaki)","accept":["aucun","aucun examen","aucun examen n'est indispensable"],"keywords":["aucun"],"explanation":"Chez l'enfant, aucun examen n'est indispensable, sauf si l'on suspecte une scarlatine (NFS, prélèvement de gorge) ou un syndrome de Kawasaki (NFS, plaquettes, échographie cardiaque) (p. 85).","src":"p. 85","deep":"**Piège** : chez l'adulte sans cause évidente, un bilan est au contraire prévu : NFS, tests hépatiques, sérodiagnostic de MNI, test tréponémique, charge virale VIH, sérologie VIH combinée (p. 85).\n**À relier** : chez l'enfant, les exanthèmes fébriles sont le plus souvent d'origine virale (p. 90)."},{"id":"d114-qroc-041","type":"QROC","rank":"B","objective":"d114-obj-32","tags":["paraclinique","pédiatrie"],"difficulty":2,"question":"Quels examens demande-t-on devant un syndrome de Kawasaki suspecté chez l'enfant ?","answer":"NFS, plaquettes et échographie cardiaque","accept":["nfs, plaquettes, échographie cardiaque","nfs plaquettes échographie cardiaque","nfs, plaquettes, échocardiographie"],"keywords":["nfs","plaquette","cardiaque"],"explanation":"Suspicion de Kawasaki chez l'enfant : NFS, plaquettes et échographie cardiaque ; suspicion de scarlatine : NFS et prélèvement de gorge (p. 85).","src":"p. 85","deep":"**À relier** : la biologie du Kawasaki montre un syndrome inflammatoire (CRP élevée, hyperleucocytose à PNN, thrombocytose) ; complications : anévrismes coronariens, troubles du rythme (p. 88).\n**Piège** : hors scarlatine et Kawasaki, aucun examen n'est indispensable chez l'enfant (p. 85)."},{"id":"d114-qroc-042","type":"QROC","rank":"B","objective":"d114-obj-15","tags":["grossesse","étiologie"],"difficulty":2,"question":"Parmi les exanthèmes à risque chez la femme enceinte, quelle infection bactérienne expose à une forme congénitale ?","answer":"La syphilis","accept":["syphilis","la syphilis"],"keywords":["syphilis"],"explanation":"Quatre exanthèmes à risque chez la femme enceinte : rubéole (mort fœtale ou malformations), parvovirus B19 (anasarque fœtale), toxoplasmose et syphilis (forme congénitale) (p. 83).","src":"p. 83, 85","deep":"**À relier** : chez la femme enceinte avec exanthème, sérologies de toxoplasmose, rubéole, CMV, parvovirus B19 et syphilis, selon le statut sérologique de début de grossesse (p. 85).\n**Piège** : la syphilis secondaire (1re floraison) est aussi une cause d'exanthème roséoliforme (rang B), et chez l'adulte le bilan comprend un test tréponémique (p. 85)."},{"id":"d114-qroc-043","type":"QROC","rank":"B","objective":"d114-obj-11","tags":["paraclinique","biologie"],"difficulty":2,"question":"Quel antigène viral est détecté par la sérologie VIH combinée (Ag-Ac) ?","answer":"L'antigène p24","accept":["p24","antigène p24","ag p24"],"keywords":["p24"],"explanation":"Chez l'adulte sans cause évidente : NFS, tests hépatiques, sérodiagnostic de MNI, test tréponémique, charge virale VIH et sérologie VIH combinée (Ag-Ac) p24 (p. 85).","src":"p. 85","deep":"**Pourquoi** : la sérologie est dite combinée (Ag-Ac) : elle associe la recherche de l'antigène p24 et des anticorps (p. 85).\n**À relier** : la primo-infection VIH figure parmi les causes d'exanthème roséoliforme et morbilliforme (p. 85-86).\n**Piège** : ce bilan concerne l'adulte ; chez l'enfant, aucun examen n'est indispensable hors scarlatine ou Kawasaki (p. 85)."},{"id":"d114-qroc-044","type":"QROC","rank":"B","objective":"d114-obj-24","tags":["urgence","complications"],"difficulty":2,"question":"Que faut-il rechercher devant un exanthème diffus scarlatiniforme fébrile de survenue brutale ?","answer":"Un syndrome du choc toxique staphylococcique","accept":["choc toxique staphylococcique","choc toxique","syndrome du choc toxique staphylococcique"],"keywords":["choc toxique"],"explanation":"Un exanthème diffus scarlatiniforme fébrile de survenue brutale doit faire rechercher un syndrome du choc toxique staphylococcique et dépister des signes de retentissement hémodynamique (p. 90).","src":"p. 90","deep":"**À relier** : le choc toxique staphylococcique est la forme sévère de la scarlatine staphylococcique (Staphylococcus aureus sécréteur d'entérotoxines ou TSST1), traitée par oxacilline (p. 88).\n**Piège** : scarlatine et Kawasaki sont aussi scarlatiniformes ; devant un début brutal et fébrile, le Collège demande en plus de dépister le retentissement hémodynamique (p. 88, 90)."},{"id":"d114-qroc-045","type":"QROC","rank":"B","objective":"d114-obj-17","tags":["étiologie"],"difficulty":2,"question":"Dans quelle proportion des cas une érythrodermie reste-t-elle idiopathique ?","answer":"10 à 15 % des cas","accept":["10 à 15 %","10-15 %","10 à 15"],"keywords":["10","15"],"explanation":"L'érythrodermie reste idiopathique dans 10 à 15 % des cas (p. 91) ; les causes principales sont le psoriasis, la dermatite atopique, le lymphome cutané (Sézary) et la toxidermie (DRESS) (p. 93).","src":"p. 91","deep":"**À relier** : l'enquête étiologique repose sur l'interrogatoire (ancienneté, antécédents, médicaments, topiques, contexte infectieux), la biopsie cutanée (à répéter si suspicion de lymphome) et des prélèvements bactériologiques ou parasitologiques (p. 91-92).\n**Piège** : lichen plan et forme idiopathique sont de rang B ; psoriasis, dermatite atopique, DRESS, Sézary, VIH et gale croûteuse sont de rang A (p. 91)."},{"id":"d114-qcm-101","type":"QRM","rank":"A","objective":"d114-obj-01","tags":["définition","étiologie"],"difficulty":1,"stem":"Concernant les exanthèmes, quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'un érythème d'apparition brutale et transitoire","ok":true,"why":"Vrai : définition du Collège ; il peut être intense ou non, diffus ou de topographie plus spécifique, isolé ou associé à d'autres symptômes (p. 84)."},{"t":"Chez l'enfant, la cause est le plus souvent médicamenteuse","ok":false,"why":"Faux : les exanthèmes fébriles de l'enfant sont le plus souvent viraux, même s'ils peuvent aussi être bactériens, inflammatoires ou médicamenteux (p. 90)."},{"t":"Chez l'adulte, la cause est exclusivement infectieuse","ok":false,"why":"Faux : chez l'adulte, il faut penser au VIH et à la syphilis, mais aussi aux médicaments (toxidermie) (p. 90)."},{"t":"Il peut s'accompagner d'une atteinte muqueuse (énanthème)","ok":true,"why":"Vrai : l'atteinte muqueuse associée s'appelle énanthème ; l'exanthème peut être bénin ou potentiellement grave (p. 84)."},{"t":"Un exanthème évolue depuis au moins 6 semaines","ok":false,"why":"Faux : « au moins 6 semaines » caractérise l'érythrodermie (p. 90) ; l'exanthème est transitoire (p. 84)."}],"explanation":"Exanthème : érythème d'apparition brutale et transitoire, avec parfois une atteinte muqueuse (énanthème). Causes infectieuses (surtout virales chez l'enfant ; IST — syphilis, VIH — chez l'adulte) et médicamenteuses (p. 84, 90).","src":"p. 84, 90","deep":"**Piège** : exanthème et érythrodermie ne sont pas synonymes : l'érythrodermie touche plus de 90 % de la peau avec desquamation et évolue depuis au moins 6 semaines (p. 90, 93).\n**À relier** : la démarche associe anamnèse (contexte épidémique, contage, médicament), analyse séméiologique (roséoliforme, morbilliforme, scarlatiniforme) et signes extracutanés et biologiques (p. 85)."},{"id":"d114-qcm-102","type":"QRM","rank":"A","objective":"d114-obj-03","tags":["clinique"],"difficulty":1,"stem":"Concernant les types séméiologiques d'exanthème, quelles propositions sont exactes ?","options":[{"t":"Le scarlatiniforme laisse des intervalles de peau saine entre les plaques","ok":false,"why":"Faux : le scarlatiniforme ne laisse aucun intervalle de peau saine ; c'est le morbilliforme qui garde des espaces de peau saine entre ses plaques (p. 85)."},{"t":"Le morbilliforme est maculo-papuleux, confluant en plaques séparées par de la peau saine","ok":true,"why":"Vrai : éléments maculo-papuleux rouges, pouvant confluer en plaques séparées par des espaces de peau saine (p. 85)."},{"t":"Le roséoliforme comporte de larges plaques rouge vif confluentes","ok":false,"why":"Faux : ce sont de petites macules rosées, pâles et bien séparées ; les plaques diffuses rouge vif décrivent le scarlatiniforme (p. 85)."},{"t":"Le scarlatiniforme est fait de plaques diffuses rouge vif, granitées, plus intenses dans les plis","ok":true,"why":"Vrai : plaques légèrement granitées à la palpation, chaudes ou cuisantes, s'intensifiant dans les plis, pouvant desquamer secondairement en larges lambeaux (p. 85)."},{"t":"Le roséoliforme est fait de petites macules rosées, pâles, bien séparées","ok":true,"why":"Vrai : on dit aussi rubéoliforme ; causes : exanthème subit, rubéole, primo-infection VIH (p. 85)."}],"explanation":"Roséoliforme : petites macules rosées pâles, bien séparées. Morbilliforme : maculo-papuleux rouge, plaques séparées par de la peau saine. Scarlatiniforme : plaques diffuses rouge vif, légèrement granitées, sans peau saine, plus intenses dans les plis (p. 85).","src":"p. 85","deep":"**Pourquoi** : le repère commun est la peau saine : macules bien séparées (roséoliforme), plaques séparées par de la peau saine (morbilliforme), aucun intervalle (scarlatiniforme) (p. 85).\n**À relier** : scarlatiniforme → scarlatine, Kawasaki, épidermolyse staphylococcique ; morbilliforme → rougeole, mégalérythème épidémique, mononucléose (p. 86, 88)."},{"id":"d114-qcm-103","type":"QRM","rank":"A","objective":"d114-obj-03","tags":["diagnostic","étiologie"],"difficulty":2,"stem":"Concernant l'orientation étiologique d'un exanthème, quelles propositions sont exactes ?","options":[{"t":"La fièvre, le syndrome grippal et les adénopathies orientent vers une origine virale","ok":true,"why":"Vrai : fièvre, syndrome grippal et poly-adénopathie sont des signes d'origine virale, avec l'énanthème (p. 85)."},{"t":"Le caractère monomorphe de l'éruption oriente vers une toxidermie","ok":false,"why":"Faux : c'est le caractère polymorphe de l'éruption qui oriente vers un médicament, avec le prurit et l'hyperéosinophilie sanguine (p. 85)."},{"t":"Un prurit oriente vers une origine médicamenteuse","ok":true,"why":"Vrai : le prurit oriente vers un médicament, avec le polymorphisme de l'éruption et l'hyperéosinophilie sanguine (p. 85)."},{"t":"Un énanthème oriente vers une origine virale","ok":true,"why":"Vrai : l'énanthème (atteinte muqueuse) est un signe extracutané d'origine virale (p. 85) ; exemple : le signe de Köplick de la rougeole (p. 86)."},{"t":"Une hyperéosinophilie sanguine oriente vers une origine virale","ok":false,"why":"Faux : l'hyperéosinophilie sanguine oriente vers une origine médicamenteuse (p. 85) ; on la retrouve dans le nom du DRESS (Drug Rash with hyper-Eosinophilia and Systemic Symptoms) (p. 91)."}],"explanation":"Origine virale : fièvre, syndrome grippal, énanthème, poly-adénopathie. Origine médicamenteuse : prurit, caractère polymorphe de l'éruption, hyperéosinophilie sanguine (p. 85).","src":"p. 85","deep":"**Pourquoi** : ces signes extracutanés et biologiques sont dits indispensables pour orienter le diagnostic, avec l'anamnèse (contexte épidémique, contage, prise médicamenteuse) (p. 85).\n**Piège** : chez l'adulte, penser aux médicaments en plus du VIH et de la syphilis (p. 90).\n**À relier** : toxidermies citées parmi les exanthèmes morbilliformes : β-lactamines, sulfamides, anti-comitiaux… (p. 86)."},{"id":"d114-qcm-104","type":"QRM","rank":"A","objective":"d114-obj-16","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Concernant la rougeole, quelles propositions sont exactes ?","options":[{"t":"L'exanthème débute en rétro-auriculaire puis s'étend à tout le corps en une poussée","ok":true,"why":"Vrai : l'exanthème débute en rétro-auriculaire puis s'étend à l'ensemble du corps en une seule poussée ; il est morbilliforme (p. 86)."},{"t":"Elle est due au virus de la rubéole, comme l'exanthème roséoliforme","ok":false,"why":"Faux : la rougeole est due au morbillivirus (paramyxovirus) ; le virus de la rubéole donne la rubéole, exanthème roséoliforme discret (p. 85-86)."},{"t":"Elle n'est pas à déclaration obligatoire et n'impose aucune éviction","ok":false,"why":"Faux : maladie à déclaration obligatoire, avec éviction de la collectivité recommandée jusqu'à 5 jours après le début de l'éruption (p. 86)."},{"t":"Le signe de Köplick est un semis de papules de la face interne des joues","ok":true,"why":"Vrai : semis de papules de la face interne des joues, présent en phase pré-éruptive (p. 86)."},{"t":"L'association catarrhe oculo-nasal, conjonctivite et exanthème fébrile l'évoque","ok":true,"why":"Vrai : c'est l'association qui doit faire évoquer une rougeole, chez l'enfant comme chez l'adulte (p. 83, 90)."}],"explanation":"Rougeole : morbillivirus (paramyxovirus), incubation 10-12 jours ; phase pré-éruptive avec catarrhe oculo-nasal, fièvre 39-40 °C, signe de Köplick, conjonctivite ; exanthème rétro-auriculaire puis généralisé en une seule poussée ; maladie à déclaration obligatoire (p. 86, 90).","src":"p. 86, 90","deep":"**Piège** : la contagiosité commence 3 à 5 jours avant l'éruption et dure jusqu'à 4 jours après (p. 86).\n**À relier** : complications : pneumopathie, hépatite, pancréatite, encéphalite (grave), kératite et cécité ; informer le personnel et les parents (p. 86)."},{"id":"d114-qcm-105","type":"QRM","rank":"A","objective":"d114-obj-26","tags":["complications","prévention"],"difficulty":2,"stem":"Concernant les complications et la conduite à tenir devant une rougeole, quelles propositions sont exactes ?","options":[{"t":"Elle peut se compliquer d'une encéphalite","ok":true,"why":"Vrai : l'encéphalite est la complication que le Collège qualifie de grave (p. 86)."},{"t":"Elle peut se compliquer d'une pneumopathie","ok":true,"why":"Vrai : pneumopathie, avec hépatite, pancréatite, encéphalite, kératite et cécité (p. 86)."},{"t":"Elle ne se complique jamais de façon grave","ok":false,"why":"Faux : encéphalite (grave), kératite avec risque de cécité, pneumopathie sont possibles (p. 86)."},{"t":"Aucune éviction de la collectivité n'est recommandée","ok":false,"why":"Faux : l'éviction de la collectivité est recommandée jusqu'à 5 jours après le début de l'éruption ; c'est pour la rubéole qu'il n'y a pas de recommandation d'éviction (p. 85-86)."},{"t":"Elle est à déclaration obligatoire, avec éviction jusqu'à 5 jours après le début de l'éruption","ok":true,"why":"Vrai : déclaration obligatoire, éviction jusqu'à 5 jours après le début de l'éruption, et information du personnel et des parents (p. 86)."}],"explanation":"Rougeole : complications pulmonaires (pneumopathie), hépato-pancréatiques, neurologiques (encéphalite, grave) et oculaires (kératite, cécité) ; déclaration obligatoire, éviction de la collectivité jusqu'à 5 jours après le début de l'éruption, information du personnel et des parents (p. 86).","src":"p. 86","deep":"**Piège** : éviction jusqu'à 5 jours après le début de l'éruption pour la rougeole, mais jusqu'à 48 heures après le début du traitement pour la scarlatine ; pas de recommandation d'éviction pour la rubéole (p. 85-88).\n**À relier** : contagiosité de 3-5 jours avant à 4 jours après l'éruption (p. 86)."},{"id":"d114-qcm-106","type":"QRM","rank":"A","objective":"d114-obj-29","tags":["diagnostic","pédiatrie"],"difficulty":2,"stem":"Un nourrisson de 12 mois a une fièvre à 39,5 °C, isolée, depuis 3 jours. Une éruption de petites macules rosées pâles, bien séparées, prédominant sur le tronc apparaît ensuite. Quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'une primo-infection par HHV6","ok":true,"why":"Vrai : l'exanthème subit est la primo-infection par le virus HHV6 (human herpesvirus 6) (p. 85)."},{"t":"Il s'agit d'un exanthème subit (roséole infantile)","ok":true,"why":"Vrai : chez un nourrisson, une éruption roséoliforme après 3 jours de fièvre isolée évoque ce diagnostic (p. 90) ; âge de survenue 6 à 18 mois (p. 85)."},{"t":"Il s'agit d'une rougeole, la fièvre élevée précédant l'éruption","ok":false,"why":"Faux : la rougeole a bien une fièvre élevée pré-éruptive, mais avec catarrhe oculo-nasal, conjonctivite, signe de Köplick et un exanthème morbilliforme débutant en rétro-auriculaire (p. 86)."},{"t":"Une scarlatine est probable : fièvre élevée puis éruption","ok":false,"why":"Faux : la scarlatine (enfant de 5 à 10 ans) associe angine rouge, adénopathies sous-maxillaires et éruption scarlatiniforme des grands plis, pas de petites macules séparées (p. 85, 88)."},{"t":"Des convulsions fébriles font partie de ses complications rares","ok":true,"why":"Vrai : complications rares de l'exanthème subit : convulsions fébriles, méningite virale, hépatite aiguë, pneumopathie, syndrome mononucléosique (p. 85)."}],"explanation":"Nourrisson, fièvre isolée de 3 jours puis éruption roséoliforme du tronc : exanthème subit (roséole infantile), primo-infection HHV6 ; complications rares, dont les convulsions fébriles (p. 85, 90).","src":"p. 85, 90","deep":"**Piège** : « pas de recommandation d'éviction de la collectivité » figure dans la colonne rubéole du tableau 4.1, pas dans celle de l'exanthème subit (p. 85).\n**À relier** : l'éruption prédomine sur le tronc et évolue en une seule poussée, après une fièvre à 39-40 °C isolée pendant 48-72 heures (p. 85)."},{"id":"d114-qcm-107","type":"QRM","rank":"A","objective":"d114-obj-27","tags":["grossesse","clinique"],"difficulty":2,"stem":"Concernant la rubéole, quelles propositions sont exactes ?","options":[{"t":"L'exanthème est roséoliforme et discret","ok":true,"why":"Vrai : la rubéole est une cause d'exanthème roséoliforme ; l'exanthème est discret et dure 2 à 4 jours (p. 85)."},{"t":"Elle expose la femme enceinte non immunisée à un risque de malformations fœtales graves","ok":true,"why":"Vrai : risque de mort fœtale ou de malformations neurologiques, sensorielles (p. 85), qualifiées de graves dans les points clés (p. 90)."},{"t":"L'exanthème dure en règle plusieurs semaines","ok":false,"why":"Faux : l'exanthème est discret et ne dure que 2 à 4 jours (p. 85) ; « au moins 6 semaines » est la durée de l'érythrodermie (p. 90)."},{"t":"Des arthralgies et une conjonctivite peuvent s'y associer","ok":true,"why":"Vrai : le tableau 4.1 cite arthralgies et conjonctivite dans la colonne rubéole (p. 85)."},{"t":"Elle est due au parvovirus B19 (mégalérythème épidémique)","ok":false,"why":"Faux : la rubéole est due au virus de la rubéole ; le parvovirus B19 donne le mégalérythème épidémique, exanthème morbilliforme (p. 85-86)."}],"explanation":"Rubéole : virus de la rubéole, âge de survenue 15 à 25 ans, incubation 3 semaines, exanthème roséoliforme discret (2 à 4 jours), arthralgies et conjonctivite ; risque de mort fœtale ou de malformations chez la femme enceinte non immunisée (p. 85, 90).","src":"p. 85, 90","deep":"**Piège** : dans le tableau 4.1, « souvent asymptomatique » est écrit pour l'exanthème subit, pas pour la rubéole (p. 85).\n**À relier** : contagiosité de 7 jours avant à 14 jours après le début de l'éruption ; pas de recommandation d'éviction, mais information du personnel, des parents et de la femme enceinte (p. 85)."},{"id":"d114-qcm-108","type":"QRM","rank":"A","objective":"d114-obj-28","tags":["clinique","grossesse"],"difficulty":2,"stem":"Concernant le mégalérythème épidémique, quelles propositions sont exactes ?","options":[{"t":"Il est dû au parvovirus B19","ok":true,"why":"Vrai : parvovirus B19 ; terrain : enfant de 5 à 10 ans ; incubation 14 jours (p. 86)."},{"t":"Il expose à un risque tératogène majeur chez la femme enceinte","ok":false,"why":"Faux : le Collège précise « pas de risque tératogène » ; le risque est l'anasarque fœtale, la myocardite et l'anémie fœtale en cas d'infection au 2e trimestre (p. 86)."},{"t":"Érythème et œdème des joues, érythème du tronc à bords émiettés, érythème en gants et chaussettes","ok":true,"why":"Vrai : atteinte érythémateuse et œdème des joues, puis érythème du tronc à bords émiettés, et érythème dit en « gants et chaussettes » (p. 86-87)."},{"t":"L'enfant reste contagieux pendant toute la durée de l'éruption","ok":false,"why":"Faux : la contagiosité est limitée à la phase pré-éruptive (p. 86) ; c'est la rougeole qui reste contagieuse jusqu'à 4 jours après l'éruption."},{"t":"Une primo-infection pendant la grossesse expose au risque d'anasarque fœtale","ok":true,"why":"Vrai : point clé du Collège (p. 90) ; avec myocardite et anémie fœtale en cas d'infection au 2e trimestre (p. 86)."}],"explanation":"Mégalérythème épidémique : parvovirus B19, enfant de 5 à 10 ans ; érythème et œdème des joues, puis érythème du tronc à bords émiettés, érythème en gants et chaussettes ; contagiosité limitée à la phase pré-éruptive ; pas de risque tératogène, mais anasarque fœtale si infection au 2e trimestre (p. 86, 90).","src":"p. 86, 90","deep":"**Piège** : rubéole → mort fœtale ou malformations ; parvovirus B19 → pas tératogène, mais anasarque fœtale, myocardite, anémie fœtale (p. 85-86).\n**À relier** : complications surtout chez l'immunodéprimé, le patient avec anémie chronique et la femme enceinte ; fièvre modérée et arthralgies (p. 86)."},{"id":"d114-qcm-109","type":"QRM","rank":"B","objective":"d114-obj-05","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Un adolescent de 16 ans a une fièvre, une asthénie importante, une poly-adénopathie et une splénomégalie. Un traitement par pénicilline A est débuté, puis un exanthème apparaît. Quelles propositions sont exactes ?","options":[{"t":"La NFS montre une neutropénie profonde avec des polynucléaires altérés","ok":false,"why":"Faux : la NFS montre une lymphocytose élevée avec lymphocytes hyperbasophiles ; l'agranulocytose n'est qu'une complication rare (p. 86)."},{"t":"L'exanthème est un rash à l'ampicilline","ok":true,"why":"Vrai : complication classique de la mononucléose traitée par pénicilline A, que le Collège demande de reconnaître (p. 82, 86)."},{"t":"Il s'agit d'une toxidermie vraie, qui contre-indique définitivement toutes les pénicillines","ok":false,"why":"Faux : le Collège demande justement de ne pas confondre ce rash à l'ampicilline avec une toxidermie aux pénicillines (p. 82)."},{"t":"L'exanthème est constant au cours de la mononucléose infectieuse","ok":false,"why":"Faux : il est inconstant (5-10 %), sauf en cas de prescription de pénicilline A (p. 86)."},{"t":"Le diagnostic évoqué est une mononucléose infectieuse","ok":true,"why":"Vrai : terrain adolescent, fièvre-asthénie importante, poly-adénopathie et splénomégalie (p. 86)."}],"explanation":"Adolescent avec fièvre-asthénie importante, poly-adénopathie et splénomégalie : mononucléose infectieuse (EBV). Sous pénicilline A, l'exanthème est un rash à l'ampicilline, à ne pas confondre avec une toxidermie aux pénicillines (p. 82, 86).","src":"p. 82, 86","deep":"**Piège** : les β-lactamines figurent aussi parmi les causes de toxidermie morbilliforme (p. 86) : c'est le contexte de mononucléose qui fait parler de rash à l'ampicilline (p. 82).\n**À relier** : complications rares de la mononucléose : hépatite, méningo-encéphalite, rupture splénique, agranulocytose (p. 86)."},{"id":"d114-qcm-110","type":"QRM","rank":"A","objective":"d114-obj-31","tags":["clinique","pédiatrie"],"difficulty":2,"stem":"Concernant la scarlatine, quelles propositions sont exactes ?","options":[{"t":"L'éruption prédomine aux grands plis","ok":true,"why":"Vrai : éruption prédominant aux grands plis, évoluant vers une desquamation fine ou en lambeaux (p. 88-89)."},{"t":"Début brutal : fièvre, douleurs pharyngées, angine rouge, adénopathies sous-maxillaires","ok":true,"why":"Vrai : phase pré-éruptive brutale avec fièvre 39-40 °C, douleurs pharyngées, céphalées, angine rouge et adénopathies sous-maxillaires (p. 88)."},{"t":"Elle est due à Staphylococcus aureus sécréteur de TSST1","ok":false,"why":"Faux : Staphylococcus aureus sécréteur d'entérotoxines ou de TSST1 donne la scarlatine staphylococcique, qui se distingue par l'absence d'angine (p. 88)."},{"t":"Elle est due au streptocoque du groupe A","ok":true,"why":"Vrai : streptocoque du groupe A sécréteur d'exotoxines ; contamination par voie aérienne (p. 88)."},{"t":"Dépapillation progressive de la langue en « V » et langue framboisée font partie du tableau","ok":true,"why":"Vrai : le tableau 4.3 associe une dépapillation progressive de la langue en « V » et une langue framboisée (p. 88-89)."}],"explanation":"Scarlatine : streptocoque du groupe A sécréteur d'exotoxines, enfant de 5 à 10 ans ; début brutal (fièvre, douleurs pharyngées, angine rouge, adénopathies sous-maxillaires), éruption prédominant aux grands plis, dépapillation de la langue en « V » et langue framboisée, desquamation fine ou en lambeaux (p. 88).","src":"p. 88","deep":"**Piège** : la langue framboisée existe aussi dans le Kawasaki (enfant de moins de 5 ans, fièvre > 38,5 °C plus de 5 jours, conjonctivite bilatérale) (p. 88).\n**À relier** : incubation 2 à 4 jours ; contagiosité de 2 à 3 semaines, qui persiste 48 heures après le début du traitement (p. 88)."},{"id":"d114-qcm-111","type":"QRM","rank":"A","objective":"d114-obj-31","tags":["complications","traitement"],"difficulty":2,"stem":"Concernant le diagnostic et la prise en charge de la scarlatine, quelles propositions sont exactes ?","options":[{"t":"Un prélèvement de gorge est réalisé","ok":true,"why":"Vrai : le tableau 4.3 prévoit un prélèvement de gorge ; chez l'enfant, la suspicion de scarlatine est l'un des deux cas où des examens sont indiqués (NFS, prélèvement de gorge, rang B) (p. 85, 88)."},{"t":"Elle peut se compliquer de glomérulonéphrite ou de rhumatisme articulaire aigu","ok":true,"why":"Vrai : ce sont les complications post-streptococciques (p. 88)."},{"t":"Elle expose à des anévrismes coronariens et à des troubles du rythme cardiaque","ok":false,"why":"Faux : anévrismes coronariens et troubles du rythme sont les complications cardiaques du syndrome de Kawasaki (p. 88)."},{"t":"L'éviction scolaire dure 15 jours après le début du traitement","ok":false,"why":"Faux : l'éviction de la collectivité dure jusqu'à 48 heures après le début du traitement ; la contagiosité persiste 48 heures après sa mise en route (p. 88)."},{"t":"Le traitement repose sur l'amoxicilline","ok":true,"why":"Vrai : antibiothérapie par amoxicilline ; l'épidermolyse staphylococcique se traite, elle, par oxacilline (p. 88)."}],"explanation":"Scarlatine : prélèvement de gorge, amoxicilline, éviction de la collectivité jusqu'à 48 heures après le début du traitement ; complications post-streptococciques : glomérulonéphrites, rhumatisme articulaire aigu (p. 88).","src":"p. 88","deep":"**Piège** : éviction jusqu'à 48 heures après le début du traitement pour la scarlatine comme pour l'épidermolyse staphylococcique, mais jusqu'à 5 jours après le début de l'éruption pour la rougeole (p. 86, 88).\n**À relier** : contagiosité de 2 à 3 semaines, qui persiste 48 heures après la mise en route du traitement (p. 88)."},{"id":"d114-qcm-112","type":"QRM","rank":"A","objective":"d114-obj-32","tags":["diagnostic","pédiatrie"],"difficulty":2,"stem":"Concernant le syndrome de Kawasaki, quelles propositions sont exactes ?","options":[{"t":"Il touche surtout l'enfant de moins de 5 ans","ok":true,"why":"Vrai : terrain : enfant de moins de 5 ans (la scarlatine touche l'enfant de 5 à 10 ans) (p. 88)."},{"t":"C'est une vasculite systémique aiguë","ok":true,"why":"Vrai : vasculite systémique aiguë, aussi appelée syndrome adéno-cutanéo-muqueux (p. 88)."},{"t":"Il est traité en ambulatoire par un traitement symptomatique","ok":false,"why":"Faux : l'hospitalisation est indispensable ; le retard thérapeutique expose aux anévrismes coronariens (p. 88, 90)."},{"t":"La fièvre dépasse 38,5 °C depuis plus de 5 jours","ok":true,"why":"Vrai : fièvre élevée > 38,5 °C plus de 5 jours avec altération de l'état général (p. 88)."},{"t":"Il est retenu si au moins cinq des six critères sont présents","ok":true,"why":"Vrai : diagnostic si au moins cinq des six critères diagnostiques sont présents (p. 88)."}],"explanation":"Kawasaki : vasculite systémique aiguë (syndrome adéno-cutanéo-muqueux) de l'enfant de moins de 5 ans ; fièvre > 38,5 °C plus de 5 jours avec altération de l'état général ; diagnostic si au moins 5 critères sur 6 ; hospitalisation indispensable (p. 88).","src":"p. 88","deep":"**Piège** : ne pas mélanger les « 5 jours » de fièvre et les « 5 critères sur 6 » (p. 88).\n**À relier** : en cas de suspicion chez l'enfant : NFS, plaquettes et échographie cardiaque (rang B, p. 85) ; biologie : CRP élevée, hyperleucocytose à PNN, thrombocytose (p. 88)."},{"id":"d114-qcm-113","type":"QRM","rank":"A","objective":"d114-obj-32","tags":["clinique","complications"],"difficulty":2,"stem":"Concernant les signes cliniques et biologiques du syndrome de Kawasaki, quelles propositions sont exactes ?","options":[{"t":"Il n'y a jamais de complication cardiaque, le pronostic est toujours bon","ok":false,"why":"Faux : complications cardiaques (anévrismes coronariens, troubles du rythme) et décès par myocardite ou infarctus sont possibles (p. 88)."},{"t":"Érythème et œdème des extrémités ; évolution vers une desquamation en « doigt de gant »","ok":true,"why":"Vrai : le tableau 4.3 cite l'érythème et l'œdème des extrémités, et une évolution avec desquamation en « doigt de gant » (p. 88)."},{"t":"Syndrome inflammatoire : CRP élevée, hyperleucocytose à PNN, thrombocytose","ok":true,"why":"Vrai : syndrome inflammatoire avec élévation de la CRP, hyperleucocytose à PNN et thrombocytose (p. 88)."},{"t":"Une conjonctivite bilatérale avec œdème des paupières est présente","ok":true,"why":"Vrai : conjonctivite bilatérale avec œdème des paupières (p. 88)."},{"t":"L'énanthème comporte une chéilite et une langue framboisée","ok":true,"why":"Vrai : énanthème avec chéilite et langue framboisée (p. 88) ; la langue framboisée se voit aussi dans la scarlatine."}],"explanation":"Kawasaki : conjonctivite bilatérale avec œdème des paupières, chéilite et langue framboisée, érythème et œdème des extrémités, exanthème polymorphe, lymphadénite souvent asymétrique, desquamation en « doigt de gant » ; syndrome inflammatoire ; complications cardiaques (p. 88).","src":"p. 88","deep":"**Piège** : la desquamation de la scarlatine est fine ou en lambeaux ; celle du Kawasaki est dite en « doigt de gant » (p. 88).\n**À relier** : lymphadénite souvent asymétrique et exanthème polymorphe complètent le tableau ; hospitalisation indispensable (p. 88)."},{"id":"d114-qcm-114","type":"QRM","rank":"A","objective":"d114-obj-02","tags":["définition","clinique"],"difficulty":1,"stem":"Concernant la définition de l'érythrodermie, quelles propositions sont exactes ?","options":[{"t":"Elle touche plus de 50 % de la surface corporelle","ok":false,"why":"Faux : le seuil est de plus de 90 % de la surface corporelle (p. 90)."},{"t":"Elle associe un érythème confluant et une desquamation","ok":true,"why":"Vrai : érythème confluant associé à une desquamation de l'ensemble des téguments (p. 90)."},{"t":"Son aspect clinique permet de reconnaître sa cause","ok":false,"why":"Faux : l'aspect clinique ne préjuge pas de la cause (p. 93) ; interrogatoire, examens clinique et complémentaires (biopsie…) sont essentiels (p. 91-92)."},{"t":"Elle évolue depuis au moins 6 semaines","ok":true,"why":"Vrai : évolution prolongée, depuis au moins 6 semaines (p. 90, 93) ; le tableau d'objectifs écrit « < 6 semaines » (p. 82)."},{"t":"C'est un synonyme d'exanthème","ok":false,"why":"Faux : érythrodermie n'est pas synonyme d'érythème ou d'exanthème ; un exanthème, d'évolution aiguë, n'est pas une érythrodermie (p. 91, 93)."}],"explanation":"Érythrodermie : érythème confluant + desquamation de l'ensemble des téguments (plus de 90 % de la surface corporelle), évolution d'au moins 6 semaines selon le texte ; syndrome rare, de diagnostic clinique, aux multiples étiologies (p. 90, 93).","src":"p. 90, 93","deep":"**Piège** : une éruption érythémato-squameuse faite d'éléments multiples séparés par de la peau saine, ou une nécrolyse épidermique aiguë avec décollement, ne sont pas des érythrodermies (p. 91).\n**À relier** : trois étapes : reconnaître, rechercher l'étiologie, apprécier la gravité et proposer un traitement symptomatique (p. 90)."},{"id":"d114-qcm-115","type":"QRM","rank":"A","objective":"d114-obj-21","tags":["clinique"],"difficulty":2,"stem":"Concernant les signes cliniques de l'érythrodermie, quelles propositions sont exactes ?","options":[{"t":"Une poly-adénopathie généralisée est fréquente","ok":true,"why":"Vrai : poly-adénopathie fréquente et généralisée, ganglions parfois de grande taille, souples et mobiles (p. 91)."},{"t":"Le prurit est constant","ok":true,"why":"Vrai : le prurit est constant, comme la desquamation (p. 90)."},{"t":"Une dysrégulation thermique cutanée peut donner des épisodes de fièvre et d'hypothermie","ok":true,"why":"Vrai : la dysrégulation cutanée thermique importante se marque par des épisodes de fièvre et d'hypothermie (p. 90)."},{"t":"L'érythème est généralisé, inflammatoire, plus violacé aux zones déclives","ok":true,"why":"Vrai : érythème généralisé, inflammatoire, plus violacé aux zones déclives, d'intensité variable d'un jour à l'autre (p. 90)."},{"t":"Une atteinte des phanères (chute des cheveux, ongles dystrophiques) est précoce, dès les premiers jours","ok":false,"why":"Faux : l'atteinte des phanères apparaît après quelques semaines d'évolution : chute des cheveux, sourcils, cils ; ongles dystrophiques avec ligne de Beau, voire chute de l'ongle (p. 91)."}],"explanation":"Érythrodermie : érythème généralisé, inflammatoire, plus violacé aux zones déclives ; desquamation et prurit constants ; dysrégulation thermique ; pachydermie des plis ; œdème du visage ; énanthème possible ; phanères touchés après quelques semaines ; poly-adénopathie ; troubles hémodynamiques ; altération de l'état général (p. 90-91).","src":"p. 90-91","deep":"**Pourquoi** : la pachydermie, mieux visible aux plis, témoigne d'une infiltration cellulaire spécifique (p. 91).\n**Piège** : l'œdème du visage, souvent marqué, peut s'accompagner d'un ectropion (p. 91).\n**À relier** : la déperdition hydro-électrolytique vient de la vasodilatation cutanée, de la desquamation, du suintement, de l'œdème et de la fièvre (p. 93)."},{"id":"d114-qcm-116","type":"QRM","rank":"A","objective":"d114-obj-06","tags":["complications"],"difficulty":2,"stem":"Concernant les complications de l'érythrodermie, quelles propositions sont exactes ?","options":[{"t":"Infections cutanées bactériennes (staphylocoque) ou virales (herpès, varicelle-zona)","ok":true,"why":"Vrai : plus souvent infections cutanées bactériennes (staphylocoque) ou virales (herpès, varicelle-zona), ou infections générales (pneumopathies, septicémies) (p. 93)."},{"t":"La mortalité peut atteindre 20 %","ok":true,"why":"Vrai : mortalité jusqu'à 20 %, liée aux complications, notamment infectieuses (p. 93)."},{"t":"La déperdition hydro-électrolytique peut décompenser une insuffisance cardiaque, respiratoire ou rénale","ok":true,"why":"Vrai : déperdition due à la vasodilatation cutanée, la desquamation, le suintement, l'œdème et la fièvre ; elle peut décompenser une insuffisance cardiaque, respiratoire ou rénale (p. 93)."},{"t":"La gravité est indépendante du terrain et des complications","ok":false,"why":"Faux : la gravité est corrélée au terrain sur lequel l'érythrodermie survient et aux complications qu'elle entraîne (p. 92)."},{"t":"Le décubitus expose à la dénutrition, à la cachexie et aux escarres","ok":true,"why":"Vrai : complications du décubitus, à prendre en charge rapidement : éviter dénutrition, cachexie, escarres (p. 93)."}],"explanation":"Complications : hydro-électrolytiques (décompensation cardiaque, respiratoire, rénale), du décubitus (dénutrition, cachexie, escarres), infectieuses ; mortalité jusqu'à 20 % ; la gravité est corrélée au terrain et aux complications (p. 92-93).","src":"p. 92-93","deep":"**À relier** : à l'hôpital : rééquilibration hydro-électrolytique, traitement des défaillances viscérales, réchauffement pour limiter pertes caloriques, hypercatabolisme et dénutrition (p. 93).\n**Piège** : la déperdition hydro-électrolytique peut décompenser des tares sous-jacentes (insuffisance cardiaque, respiratoire, rénale) : le terrain compte (p. 82, 92-93)."},{"id":"d114-qcm-117","type":"QRM","rank":"A","objective":"d114-obj-09","tags":["urgence","traitement"],"difficulty":2,"stem":"Concernant la prise en charge d'une érythrodermie, quelles propositions sont exactes ?","options":[{"t":"Une hospitalisation en urgence est nécessaire","ok":true,"why":"Vrai : urgence dermatologique imposant une hospitalisation en urgence, dans un service spécialisé (p. 90-91, 93)."},{"t":"Le réchauffement du malade limite les pertes caloriques et la dénutrition","ok":true,"why":"Vrai : le réchauffement limite les pertes caloriques, l'hypercatabolisme et la dénutrition (p. 93)."},{"t":"Les troubles hydro-électrolytiques sont rééquilibrés","ok":true,"why":"Vrai : on rééquilibre les troubles hydro-électrolytiques et on traite d'éventuelles défaillances viscérales (p. 93)."},{"t":"Une prise en charge ambulatoire est possible avec surveillance à domicile","ok":false,"why":"Faux : une érythrodermie nécessite une hospitalisation urgente (p. 93) ; sa mortalité peut atteindre 20 % (p. 93)."},{"t":"Dans les formes graves, une corticothérapie locale très forte améliore les symptômes","ok":true,"why":"Vrai : dans les formes graves, une corticothérapie locale de niveau 1 (très forte) entraîne une amélioration symptomatique rapide (p. 93)."}],"explanation":"Érythrodermie : hospitalisation en urgence (examens de gravité, rééquilibration hydro-électrolytique, traitement des défaillances viscérales, recherche étiologique) ; traitement symptomatique : réchauffement, corticothérapie locale de niveau 1 (très forte) dans les formes graves (p. 93).","src":"p. 90, 93","deep":"**Piège** : le dermocorticoïde de niveau 1 est un traitement symptomatique (formes graves) ; la recherche et le traitement étiologiques font aussi partie de la prise en charge hospitalière (p. 93).\n**À relier** : trois étapes : reconnaître, chercher l'étiologie, apprécier la gravité et proposer un traitement symptomatique (p. 90)."},{"id":"d114-qcm-118","type":"QRM","rank":"A","objective":"d114-obj-17","tags":["étiologie"],"difficulty":2,"stem":"Quelles sont des causes d'érythrodermie de l'adulte ?","options":[{"t":"Le psoriasis","ok":true,"why":"Vrai : cause majeure (+++) d'érythrodermie de l'adulte (p. 91)."},{"t":"Une toxidermie de type DRESS","ok":true,"why":"Vrai : toxidermie (DRESS +++), cause principale ; l'interrogatoire recherche une prise médicamenteuse (p. 91)."},{"t":"Le syndrome de Sézary","ok":true,"why":"Vrai : lymphome T cutané épidermotrope (+++) ; biopsie à répéter si suspicion de lymphome cutané (p. 91-92)."},{"t":"Une nécrolyse épidermique aiguë avec décollement","ok":false,"why":"Faux : une nécrolyse épidermique avec décollement, d'évolution aiguë, n'est pas une érythrodermie, qui évolue depuis au moins 6 semaines (p. 90-91)."},{"t":"La dermatite atopique","ok":true,"why":"Vrai : eczéma/dermatite atopique (+++), cause principale chez l'adulte et chez l'enfant après 3 mois (p. 91)."}],"explanation":"Causes principales d'érythrodermie de l'adulte : psoriasis, eczéma/dermatite atopique, toxidermie (DRESS), syndrome de Sézary ; aussi gale croûteuse et VIH (p. 91, 93).","src":"p. 90-91, 93","deep":"**Piège** : l'aspect clinique ne préjuge pas de la cause : interrogatoire, examens clinique et complémentaires sont essentiels au diagnostic (p. 91, 93).\n**À relier** : chez le nouveau-né et le nourrisson de moins de 3 mois : maladie de Leiner-Moussous ; après 3 mois : dermatite atopique et mêmes causes que l'adulte (p. 91)."},{"id":"d114-qcm-119","type":"QRM","rank":"B","objective":"d114-obj-25","tags":["paraclinique","diagnostic"],"difficulty":2,"stem":"Concernant les examens complémentaires devant un exanthème, quelles propositions sont exactes ?","options":[{"t":"Chez l'enfant, une sérologie VIH est indispensable dans tous les cas d'exanthème","ok":false,"why":"Faux : chez l'enfant, aucun examen n'est indispensable, sauf suspicion de scarlatine ou de Kawasaki ; le bilan VIH concerne l'adulte sans cause évidente (p. 85)."},{"t":"Chez l'adulte sans cause évidente, on se limite à la NFS : ni test tréponémique ni sérologie VIH","ok":false,"why":"Faux : chez l'adulte sans cause évidente : NFS, tests hépatiques, sérodiagnostic de MNI, test tréponémique, charge virale VIH et sérologie VIH combinée (Ag-Ac) p24 (p. 85)."},{"t":"En cas de suspicion de Kawasaki : NFS, plaquettes et échographie cardiaque","ok":true,"why":"Vrai : NFS, plaquettes et échographie cardiaque (p. 85) ; la biologie du Kawasaki montre CRP élevée, hyperleucocytose à PNN, thrombocytose, et ses complications sont cardiaques (p. 88)."},{"t":"Chez la femme enceinte : sérologies de toxoplasmose, rubéole, CMV, parvovirus B19 et syphilis","ok":true,"why":"Vrai : en tenant compte de son statut sérologique de début de grossesse (p. 85)."},{"t":"Chez l'enfant, aucun examen indispensable sauf suspicion de scarlatine ou de Kawasaki","ok":true,"why":"Vrai : scarlatine → NFS et prélèvement de gorge ; Kawasaki → NFS, plaquettes, échographie cardiaque (p. 85)."}],"explanation":"Enfant : aucun examen indispensable sauf suspicion de scarlatine (NFS, prélèvement de gorge) ou de Kawasaki (NFS, plaquettes, échographie cardiaque). Adulte sans cause évidente : NFS, tests hépatiques, sérodiagnostic de MNI, test tréponémique, charge virale VIH, sérologie VIH combinée (Ag-Ac) p24. Femme enceinte : toxoplasmose, rubéole, CMV, parvovirus B19, syphilis (p. 85).","src":"p. 85","deep":"**À relier** : chez l'adulte, ce bilan couvre le VIH (charge virale, sérologie combinée) et la syphilis (test tréponémique), causes à évoquer avec les médicaments (p. 85, 90).\n**Piège** : chez la femme enceinte, les sérologies tiennent compte du statut sérologique de début de grossesse (p. 85)."},{"id":"d114-qcm-120","type":"QRM","rank":"B","objective":"d114-obj-13","tags":["étiologie","diagnostic"],"difficulty":2,"stem":"Concernant les causes principales d'exanthème selon leur type séméiologique, quelles propositions sont exactes ?","options":[{"t":"Exanthème scarlatiniforme : scarlatine, syndrome de Kawasaki","ok":true,"why":"Vrai : ce sont les deux causes principales ; le tableau 4.3 y ajoute l'épidermolyse staphylococcique (p. 83, 88)."},{"t":"Exanthème roséoliforme : exanthème subit, rubéole, primo-infection VIH, syphilis secondaire","ok":true,"why":"Vrai : les quatre causes principales, la syphilis secondaire correspondant à la 1re floraison (p. 83, 85)."},{"t":"La rougeole est une cause principale d'exanthème scarlatiniforme","ok":false,"why":"Faux : la rougeole donne un exanthème morbilliforme, débutant en rétro-auriculaire (p. 86)."},{"t":"Exanthème morbilliforme : rougeole, scarlatine, syndrome de Kawasaki","ok":false,"why":"Faux : causes principales du morbilliforme : rougeole, mégalérythème épidémique, mononucléose ; la scarlatine est scarlatiniforme, et le Kawasaki n'est qu'une « autre » cause de morbilliforme (p. 83, 86, 88)."},{"t":"La rubéole est une cause principale d'exanthème morbilliforme","ok":false,"why":"Faux : la rubéole donne un exanthème roséoliforme, discret (2 à 4 jours) (p. 85)."}],"explanation":"Roséoliforme : exanthème subit, rubéole, primo-infection VIH, syphilis secondaire. Morbilliforme : rougeole, mégalérythème épidémique, mononucléose infectieuse. Scarlatiniforme : scarlatine, syndrome de Kawasaki (p. 83, 85-88).","src":"p. 83, 85-86, 88","deep":"**Piège** : la primo-infection VIH apparaît dans les « autres » roséoliformes et morbilliformes, et le Kawasaki dans les scarlatiniformes et les « autres » morbilliformes (p. 85-88).\n**À relier** : roséoliforme = petites macules séparées ; morbilliforme = maculo-papules avec peau saine ; scarlatiniforme = nappes sans peau saine (p. 85)."},{"id":"d114-qru-101","type":"QRU","rank":"A","objective":"d114-obj-20","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Un enfant fébrile présente des plaques rouge vif diffuses, légèrement granitées, sans intervalle de peau saine, s'intensifiant dans les plis. Quel type d'exanthème est décrit ?","options":[{"t":"Roséoliforme","ok":false,"why":"Faux : petites macules rosées, pâles, bien séparées : rien de diffus ni de rouge vif (p. 85)."},{"t":"Rubéoliforme","ok":false,"why":"Faux : synonyme de roséoliforme (petites macules rosées séparées), pas un type distinct (p. 85)."},{"t":"Érythrodermique","ok":false,"why":"Faux : l'érythrodermie touche plus de 90 % de la surface corporelle avec desquamation et dure au moins 6 semaines ; ce n'est pas un exanthème (p. 90, 93)."},{"t":"Morbilliforme","ok":false,"why":"Faux : maculo-papules rouges qui confluent en plaques séparées par des espaces de peau saine (p. 85)."},{"t":"Scarlatiniforme","ok":true,"why":"Vrai : plaques diffuses rouge vif, légèrement granitées, sans intervalle de peau saine, chaudes ou cuisantes, plus marquées dans les plis (p. 85)."}],"explanation":"Plaques diffuses rouge vif, légèrement granitées, sans intervalle de peau saine, plus intenses dans les plis : exanthème scarlatiniforme (p. 85).","src":"p. 85","deep":"**Pourquoi** : la clé est l'absence d'intervalle de peau saine, avec l'accentuation dans les plis (p. 85).\n**À relier** : causes : scarlatine (angine, langue framboisée), Kawasaki (enfant de moins de 5 ans, fièvre plus de 5 jours), épidermolyse staphylococcique (pas d'angine) (p. 88).\n**Piège** : fébrile et brutal, il doit faire rechercher un choc toxique staphylococcique (rang B, p. 90)."},{"id":"d114-qru-102","type":"QRU","rank":"A","objective":"d114-obj-26","tags":["diagnostic","pédiatrie"],"difficulty":2,"stem":"Un enfant de 6 ans a une fièvre à 39,5 °C avec un catarrhe oculo-nasal et une conjonctivite. Un exanthème maculo-papuleux débute en région rétro-auriculaire et gagne tout le corps. Quel est le diagnostic ?","options":[{"t":"Une rubéole","ok":false,"why":"Faux : la rubéole donne un exanthème roséoliforme discret (2 à 4 jours), avec arthralgies et conjonctivite, et un âge de survenue de 15 à 25 ans (p. 85)."},{"t":"Un mégalérythème épidémique","ok":false,"why":"Faux : fièvre modérée, érythème et œdème des joues, érythème du tronc à bords émiettés, gants et chaussettes (p. 86)."},{"t":"Une scarlatine","ok":false,"why":"Faux : angine rouge, adénopathies sous-maxillaires, éruption scarlatiniforme des grands plis et langue framboisée (p. 88)."},{"t":"Une rougeole","ok":true,"why":"Vrai : catarrhe oculo-nasal, conjonctivite et exanthème fébrile ; l'exanthème débute en rétro-auriculaire et s'étend à tout le corps en une poussée (p. 86, 90)."},{"t":"Un exanthème subit","ok":false,"why":"Faux : nourrisson de 6 à 18 mois, fièvre isolée de 48-72 heures puis exanthème roséoliforme du tronc (p. 85, 90)."}],"explanation":"Catarrhe oculo-nasal, conjonctivite, fièvre élevée et exanthème partant de la région rétro-auriculaire pour gagner tout le corps : rougeole (p. 86, 90).","src":"p. 85-86, 90","deep":"**À relier** : maladie à déclaration obligatoire ; éviction de la collectivité jusqu'à 5 jours après le début de l'éruption ; informer le personnel et les parents (p. 86).\n**Piège** : le signe de Köplick (semis de papules à la face interne des joues) appartient à la phase pré-éruptive (p. 86)."},{"id":"d114-qru-103","type":"QRU","rank":"A","objective":"d114-obj-28","tags":["étiologie","pédiatrie"],"difficulty":2,"stem":"Un enfant de 7 ans, peu fébrile, présente un érythème et un œdème des joues, puis un érythème du tronc à bords émiettés et un érythème en gants et chaussettes. Quel est l'agent responsable ?","options":[{"t":"Le virus de la rubéole","ok":false,"why":"Faux : le virus de la rubéole donne un exanthème roséoliforme discret, âge de survenue 15 à 25 ans (p. 85)."},{"t":"Le parvovirus B19","ok":true,"why":"Vrai : agent du mégalérythème épidémique, qui touche l'enfant de 5 à 10 ans (p. 86)."},{"t":"Le morbillivirus","ok":false,"why":"Faux : agent de la rougeole : catarrhe oculo-nasal, conjonctivite, signe de Köplick, fièvre élevée et exanthème rétro-auriculaire (p. 86)."},{"t":"Le streptocoque du groupe A","ok":false,"why":"Faux : agent de la scarlatine : début brutal, angine rouge, éruption des grands plis, langue framboisée (p. 88)."},{"t":"Le virus d'Epstein-Barr","ok":false,"why":"Faux : agent de la mononucléose de l'adolescent : fièvre-asthénie importante, poly-adénopathie, splénomégalie, exanthème inconstant (p. 86)."}],"explanation":"Joues érythémateuses et œdémateuses, puis érythème du tronc à bords émiettés, et érythème en gants et chaussettes, avec fièvre modérée : mégalérythème épidémique, dû au parvovirus B19 (p. 86-87).","src":"p. 86","deep":"**Piège** : pas de risque tératogène, mais une infection au 2e trimestre de grossesse expose à l'anasarque fœtale, la myocardite et l'anémie fœtale (p. 86).\n**À relier** : contagiosité limitée à la phase pré-éruptive ; complications surtout chez l'immunodéprimé et le patient avec anémie chronique (p. 86)."},{"id":"d114-qru-104","type":"QRU","rank":"A","objective":"d114-obj-31","tags":["diagnostic","pédiatrie"],"difficulty":2,"stem":"Un enfant de 7 ans a un début brutal avec une fièvre à 39,5 °C, des douleurs pharyngées, une angine rouge et des adénopathies sous-maxillaires. Une éruption des grands plis et une langue framboisée apparaissent ensuite. Quel est le diagnostic ?","options":[{"t":"Une scarlatine","ok":true,"why":"Vrai : streptocoque A : début brutal, angine rouge, adénopathies sous-maxillaires, éruption des grands plis, langue framboisée ; enfant de 5 à 10 ans (p. 88)."},{"t":"Une rougeole","ok":false,"why":"Faux : la rougeole associe catarrhe oculo-nasal, conjonctivite, signe de Köplick et exanthème morbilliforme débutant en rétro-auriculaire (p. 86)."},{"t":"Une scarlatine staphylococcique","ok":false,"why":"Faux : la scarlatine staphylococcique se caractérise par l'absence d'angine ; elle touche nouveau-né, nourrisson, jeune enfant ou adulte immunodéprimé (p. 88)."},{"t":"Un syndrome de Kawasaki","ok":false,"why":"Faux : enfant de moins de 5 ans, fièvre > 38,5 °C plus de 5 jours, conjonctivite bilatérale, chéilite, atteinte des extrémités (p. 88)."},{"t":"Une rubéole","ok":false,"why":"Faux : exanthème roséoliforme discret (2 à 4 jours), âge de survenue 15 à 25 ans (p. 85)."}],"explanation":"Angine rouge, adénopathies sous-maxillaires, début brutal, éruption des grands plis et langue framboisée chez un enfant de 5 à 10 ans : scarlatine streptococcique (p. 88).","src":"p. 88","deep":"**À relier** : prélèvement de gorge, amoxicilline, éviction de la collectivité jusqu'à 48 heures après le début du traitement (p. 88).\n**Piège** : complications post-streptococciques (glomérulonéphrites, RAA), à ne pas confondre avec les complications coronariennes du Kawasaki (p. 88)."},{"id":"d114-qru-105","type":"QRU","rank":"A","objective":"d114-obj-32","tags":["complications","pédiatrie"],"difficulty":2,"stem":"Un enfant de 3 ans a une fièvre à 39 °C depuis 6 jours, avec une conjonctivite bilatérale et un œdème des paupières, une chéilite, une langue framboisée, un érythème et un œdème des extrémités, et un exanthème polymorphe. Quelle complication redoute-t-on ?","options":[{"t":"Une rupture splénique","ok":false,"why":"Faux : complication rare de la mononucléose infectieuse (adolescent, splénomégalie) (p. 86)."},{"t":"Une kératite avec cécité","ok":false,"why":"Faux : complication de la rougeole, avec encéphalite et pneumopathie (p. 86)."},{"t":"Une anasarque fœtale","ok":false,"why":"Faux : risque fœtal du parvovirus B19 pendant la grossesse (p. 86)."},{"t":"Une glomérulonéphrite","ok":false,"why":"Faux : complication post-streptococcique de la scarlatine (p. 88)."},{"t":"Des anévrismes coronariens","ok":true,"why":"Vrai : complication cardiaque du Kawasaki, redoutée en cas de retard thérapeutique ; l'hospitalisation est indispensable (p. 88, 90)."}],"explanation":"Enfant de 3 ans, fièvre de plus de 5 jours avec conjonctivite bilatérale, chéilite et langue framboisée, atteinte des extrémités, exanthème polymorphe : syndrome de Kawasaki ; le retard thérapeutique expose aux anévrismes coronariens (p. 88, 90).","src":"p. 88, 90","deep":"**Pourquoi** : chez un enfant de moins de 5 ans, la fièvre > 38,5 °C plus de 5 jours s'associe ici à conjonctivite, chéilite et langue framboisée, atteinte des extrémités et exanthème polymorphe ; le diagnostic exige au moins 5 critères sur 6 (p. 88).\n**À relier** : suspicion : NFS, plaquettes, échographie cardiaque (rang B, p. 85) ; autres complications : troubles du rythme, décès par myocardite ou infarctus (p. 88)."},{"id":"d114-qru-106","type":"QRU","rank":"A","objective":"d114-obj-28","tags":["grossesse","étiologie"],"difficulty":1,"stem":"Quelle primo-infection survenant pendant la grossesse expose au risque d'anasarque fœtale ?","options":[{"t":"La rubéole","ok":false,"why":"Faux : chez la femme enceinte non immunisée, la rubéole expose à la mort fœtale ou aux malformations (p. 85, 90)."},{"t":"L'exanthème subit (HHV6)","ok":false,"why":"Faux : complications rares de l'exanthème subit : convulsions fébriles, méningite virale, hépatite aiguë, pneumopathie, syndrome mononucléosique (p. 85)."},{"t":"La mononucléose infectieuse","ok":false,"why":"Faux : complications rares de la mononucléose : hépatite, méningo-encéphalite, rupture splénique, agranulocytose (p. 86)."},{"t":"La rougeole","ok":false,"why":"Faux : complications de la rougeole : pneumopathie, hépatite, pancréatite, encéphalite, kératite et cécité (p. 86)."},{"t":"Le parvovirus B19","ok":true,"why":"Vrai : pas de risque tératogène, mais en cas d'infection au 2e trimestre, risque d'anasarque fœtale, de myocardite et d'anémie fœtale (p. 86, 90)."}],"explanation":"La primo-infection à parvovirus B19 pendant la grossesse expose au risque d'anasarque fœtale (p. 90) ; pas de risque tératogène (p. 86).","src":"p. 86, 90","deep":"**À relier** : quatre exanthèmes à risque chez la femme enceinte : rubéole, parvovirus B19, toxoplasmose, syphilis (forme congénitale) (rang B, p. 83).\n**Piège** : « anasarque » = parvovirus B19 ; « mort fœtale ou malformations » = rubéole (p. 85-86)."},{"id":"d114-qru-107","type":"QRU","rank":"A","objective":"d114-obj-09","tags":["urgence","diagnostic"],"difficulty":2,"stem":"Un homme de 60 ans présente depuis 2 mois un érythème généralisé desquamatif et prurigineux, avec une poly-adénopathie et des épisodes de fièvre et d'hypothermie. Quelle est la prise en charge initiale ?","options":[{"t":"Un traitement ambulatoire par dermocorticoïde","ok":false,"why":"Faux : une érythrodermie nécessite une hospitalisation urgente ; le dermocorticoïde de niveau 1 n'est qu'un traitement symptomatique des formes graves (p. 93)."},{"t":"Une consultation de contrôle à 1 mois","ok":false,"why":"Faux : c'est une urgence dermatologique exigeant une prise en charge immédiate, thérapeutique et étiologique (p. 90)."},{"t":"Une antibiothérapie probabiliste à domicile","ok":false,"why":"Faux : l'hospitalisation s'impose ; les complications infectieuses (staphylocoque, herpès, pneumopathies, septicémies) peuvent nécessiter des prélèvements bactériologiques (p. 92-93)."},{"t":"Une hospitalisation en urgence","ok":true,"why":"Vrai : hospitalisation en urgence : examens de gravité, rééquilibration hydro-électrolytique, traitement des défaillances viscérales, recherche étiologique (p. 93)."},{"t":"Une simple surveillance sans bilan","ok":false,"why":"Faux : la prise en charge est immédiate, avec recherche étiologique (interrogatoire, biopsie, prélèvements) et évaluation de la gravité (p. 90-92)."}],"explanation":"Érythème généralisé desquamatif depuis 2 mois, prurit, poly-adénopathie et dysrégulation thermique : érythrodermie, urgence dermatologique imposant une hospitalisation en urgence (p. 90-91, 93).","src":"p. 90, 93","deep":"**À relier** : causes à chercher chez l'adulte : psoriasis, dermatite atopique, toxidermie (DRESS), syndrome de Sézary, gale croûteuse, VIH (p. 91).\n**Piège** : la poly-adénopathie est fréquente dans l'érythrodermie ; en cas de suspicion de lymphome cutané, la biopsie doit être répétée (p. 91-92)."},{"id":"d114-qru-108","type":"QRU","rank":"B","objective":"d114-obj-07","tags":["urgence","diagnostic"],"difficulty":3,"stem":"Un adolescent de 17 ans présente brutalement une fièvre élevée et un exanthème diffus scarlatiniforme. Il est tachycarde et hypotendu. Quel diagnostic grave faut-il rechercher ?","options":[{"t":"Une rougeole compliquée d'une pneumopathie","ok":false,"why":"Faux : la rougeole donne un exanthème morbilliforme avec catarrhe oculo-nasal, conjonctivite et signe de Köplick, pas un exanthème scarlatiniforme (p. 86)."},{"t":"Un exanthème subit (roséole infantile)","ok":false,"why":"Faux : nourrisson de 6 à 18 mois, exanthème roséoliforme après une fièvre isolée (p. 85)."},{"t":"Un syndrome du choc toxique staphylococcique","ok":true,"why":"Vrai : un exanthème diffus scarlatiniforme fébrile brutal doit le faire rechercher, avec dépistage d'un retentissement hémodynamique (p. 90)."},{"t":"Un mégalérythème épidémique à parvovirus B19","ok":false,"why":"Faux : enfant de 5 à 10 ans, fièvre modérée, érythème des joues, exanthème morbilliforme (p. 86)."},{"t":"Un syndrome de Kawasaki (vasculite systémique aiguë)","ok":false,"why":"Faux : enfant de moins de 5 ans, fièvre > 38,5 °C plus de 5 jours ; ici, l'installation est brutale chez un adolescent (p. 88)."}],"explanation":"Un exanthème diffus scarlatiniforme fébrile de survenue brutale doit faire rechercher un syndrome du choc toxique staphylococcique et dépister des signes de retentissement hémodynamique (p. 90).","src":"p. 88, 90","deep":"**À relier** : le choc toxique staphylococcique est la forme sévère de la scarlatine staphylococcique (Staphylococcus aureus sécréteur d'entérotoxines ou TSST1), traitée par oxacilline (p. 88).\n**Piège** : scarlatine et Kawasaki sont aussi scarlatiniformes ; le Collège associe au début brutal et fébrile la recherche de signes de retentissement hémodynamique (p. 88, 90)."},{"id":"d114-qroc-701","type":"QROC","rank":"A","objective":"d114-obj-01","tags":["rappel"],"difficulty":1,"question":"Comment appelle-t-on l'atteinte muqueuse qui peut accompagner un exanthème ?","answer":"Un énanthème","accept":["énanthème","enanthème","enanthem"],"keywords":["nanth"],"explanation":"L'atteinte muqueuse qui peut accompagner un exanthème s'appelle énanthème (p. 84).","src":"p. 84","deep":"**Pourquoi** : l'énanthème est un des signes extracutanés en faveur d'une origine virale, avec fièvre, syndrome grippal et poly-adénopathie (p. 85).\n**À relier** : exemples : signe de Köplick (rougeole), chéilite et langue framboisée (Kawasaki), langue framboisée (scarlatine) ; dans l'érythrodermie, énanthème possible : chéilite, conjonctivite, stomatite (p. 86, 88, 91)."},{"id":"d114-qroc-702","type":"QROC","rank":"A","objective":"d114-obj-10","tags":["rappel"],"difficulty":1,"question":"Quelles sont les deux grandes causes d'exanthème ?","answer":"Infectieuses (virales ou bactériennes) et médicamenteuses","accept":["infectieuses et médicamenteuses","médicamenteuses et infectieuses","infections et médicaments","infectieuse et médicamenteuse","infectieuses, médicamenteuses"],"keywords":["infecti","médicament"],"explanation":"Deux causes principales d'exanthème : infectieuses (virales ou bactériennes) et médicamenteuses (p. 84).","src":"p. 84","deep":"**À relier** : enfant : surtout virales ; adulte : IST (syphilis, VIH) et médicaments (p. 84, 90).\n**Piège** : les exanthèmes fébriles de l'enfant, le plus souvent viraux, peuvent aussi être bactériens, inflammatoires ou médicamenteux (p. 90) ; l'anamnèse cherche contexte épidémique, contage et prise médicamenteuse (p. 85)."},{"id":"d114-qroc-703","type":"QROC","rank":"A","objective":"d114-obj-10","tags":["rappel"],"difficulty":1,"question":"Chez l'enfant, quelle est la principale cause d'exanthème fébrile ?","answer":"Une infection virale","accept":["virale","infection virale","maladie virale","virus"],"keywords":[],"explanation":"Exanthèmes fébriles de l'enfant : le plus souvent d'origine virale, mais ils peuvent aussi être bactériens, inflammatoires ou médicamenteux (p. 90).","src":"p. 84, 90","deep":"**Piège** : « le plus souvent » n'exclut pas une scarlatine (streptocoque A) ou une épidermolyse staphylococcique, traitées par antibiotique (amoxicilline, oxacilline) (p. 88).\n**À relier** : chez l'enfant, aucun examen n'est indispensable, sauf suspicion de scarlatine ou de Kawasaki (rang B, p. 85)."},{"id":"d114-qroc-704","type":"QROC","rank":"A","objective":"d114-obj-11","tags":["rappel"],"difficulty":2,"question":"Chez l'adulte, à quelles trois causes faut-il penser devant un exanthème ?","answer":"VIH, syphilis et médicaments","accept":["vih, syphilis, médicaments","vih syphilis médicaments","syphilis, vih, médicaments","vih, syphilis et toxidermie","vih, syphilis, toxidermie","syphilis, vih et médicaments"],"keywords":["vih","syphilis","médicament"],"explanation":"Chez l'adulte : penser au VIH, à la syphilis et aux médicaments (toxidermie) (p. 84, 90).","src":"p. 84, 90","deep":"**À relier** : bilan de l'adulte sans cause évidente : test tréponémique, charge virale VIH, sérologie VIH combinée Ag-Ac p24, NFS, tests hépatiques, sérodiagnostic de MNI (rang B, p. 85).\n**Piège** : la primo-infection VIH figure parmi les causes d'exanthème roséoliforme et morbilliforme ; la syphilis secondaire (rang B) parmi les roséoliformes (p. 85-86)."},{"id":"d114-qroc-705","type":"QROC","rank":"A","objective":"d114-obj-03","tags":["rappel"],"difficulty":2,"question":"Quel aspect à la palpation a un exanthème scarlatiniforme ?","answer":"Plaques rouge vif légèrement granitées, chaudes ou cuisantes","accept":["granité","granités","légèrement granités","granitées","granité à la palpation"],"keywords":["granit"],"explanation":"Exanthème scarlatiniforme : plaques diffuses rouge vif, légèrement granitées à la palpation, chaudes ou cuisantes, sans intervalle de peau saine (p. 85).","src":"p. 85","deep":"**Piège** : le morbilliforme est maculo-papuleux, mais garde des espaces de peau saine entre ses plaques (p. 85).\n**À relier** : le scarlatiniforme s'intensifie dans les plis et peut évoluer vers une desquamation secondaire en larges lambeaux (p. 85)."},{"id":"d114-qroc-706","type":"QROC","rank":"A","objective":"d114-obj-03","tags":["rappel"],"difficulty":2,"question":"Dans quelles zones l'exanthème scarlatiniforme s'intensifie-t-il ?","answer":"Dans les plis","accept":["plis","dans les plis","grands plis"],"keywords":["pli"],"explanation":"L'exanthème scarlatiniforme s'intensifie dans les plis (p. 85) ; dans la scarlatine, l'éruption prédomine aux grands plis (p. 88).","src":"p. 85","deep":"**À relier** : dans l'épidermolyse staphylococcique, l'exanthème débute aux grands plis et aux régions péri-orificielles, puis évolue vers un décollement bulleux (p. 88).\n**Piège** : l'érythème de l'érythrodermie, lui, est plus violacé aux zones déclives (p. 90)."},{"id":"d114-qroc-707","type":"QROC","rank":"A","objective":"d114-obj-03","tags":["rappel"],"difficulty":2,"question":"Quelle desquamation peut suivre un exanthème scarlatiniforme ?","answer":"Une desquamation secondaire en larges lambeaux","accept":["larges lambeaux","lambeaux","en lambeaux"],"keywords":["lambeau"],"explanation":"L'exanthème scarlatiniforme peut évoluer vers une desquamation secondaire en larges lambeaux (p. 85) ; dans la scarlatine, desquamation fine ou en lambeaux (p. 88).","src":"p. 85","deep":"**Piège** : dans le Kawasaki, l'évolution se fait vers une desquamation en « doigt de gant » (p. 88).\n**À relier** : dans l'érythrodermie, la desquamation est constante, fine ou en larges lambeaux (p. 90) ; l'érythrodermie n'est pas un exanthème : elle touche plus de 90 % de la peau depuis au moins 6 semaines (p. 90, 93)."},{"id":"d114-qroc-708","type":"QROC","rank":"A","objective":"d114-obj-03","tags":["rappel"],"difficulty":1,"question":"Quels signes extracutanés orientent vers une origine virale d'un exanthème ?","answer":"Fièvre, syndrome grippal, énanthème, poly-adénopathie","accept":["fièvre, syndrome grippal, énanthème, poly-adénopathie","fièvre, syndrome grippal, énanthème, polyadénopathie","fièvre, syndrome grippal, énanthème, adénopathies"],"keywords":["fièvre","grippal","énanthème","adénopathie"],"explanation":"Origine virale : fièvre, syndrome grippal, énanthème, poly-adénopathie (p. 85).","src":"p. 85","deep":"**Piège** : l'origine médicamenteuse s'appuie sur d'autres signes : prurit, éruption polymorphe, hyperéosinophilie sanguine (p. 85).\n**À relier** : chez l'enfant, les exanthèmes fébriles sont le plus souvent d'origine virale (p. 90) ; exemple d'énanthème viral : le signe de Köplick de la rougeole (p. 86)."},{"id":"d114-qroc-709","type":"QROC","rank":"A","objective":"d114-obj-03","tags":["rappel"],"difficulty":1,"question":"Que faut-il rechercher à l'anamnèse devant un exanthème ?","answer":"Contexte épidémique, contage, prise médicamenteuse","accept":["contexte épidémique, contage, prise médicamenteuse","contexte épidémique, contage, médicaments","contage, contexte épidémique, prise médicamenteuse","contexte épidémique, contage et prise médicamenteuse"],"keywords":["épidémi","contage","médicament"],"explanation":"Anamnèse : contexte épidémique, possible contage ou prise médicamenteuse (p. 85).","src":"p. 85","deep":"**À relier** : ces éléments recoupent les deux grandes causes d'exanthème : infectieuses et médicamenteuses (p. 84).\n**Piège** : l'anamnèse n'est qu'un des trois temps de la démarche, avec l'analyse séméiologique de l'éruption et les signes extracutanés et biologiques (p. 85)."},{"id":"d114-qroc-710","type":"QROC","rank":"B","objective":"d114-obj-13","tags":["rappel"],"difficulty":2,"question":"Chez l'adulte, en dehors d'une cause évidente, quels examens biologiques réalise-t-on devant un exanthème ?","answer":"NFS, tests hépatiques, sérodiagnostic de MNI, test tréponémique, charge virale VIH, sérologie VIH combinée (Ag-Ac) p24","accept":["nfs, tests hépatiques, sérodiagnostic de mni, test tréponémique, charge virale vih, sérologie vih","nfs, bilan hépatique, sérologie mni, test tréponémique, charge virale vih, sérologie vih"],"keywords":["nfs","hépat","mni","trépon","charge virale","sérologie vih"],"explanation":"Adulte sans cause évidente : NFS, tests hépatiques, sérodiagnostic de MNI, test tréponémique, charge virale VIH et sérologie VIH combinée (Ag-Ac) p24 (p. 85).","src":"p. 85","deep":"**À relier** : ce bilan couvre le VIH et la syphilis, causes à évoquer chez l'adulte avec les médicaments (p. 85, 90) ; chez la femme enceinte : toxoplasmose, rubéole, CMV, parvovirus B19, syphilis (p. 85).\n**Piège** : chez l'enfant, aucun examen n'est indispensable sauf suspicion de scarlatine ou de Kawasaki (p. 85)."},{"id":"d114-qroc-711","type":"QROC","rank":"B","objective":"d114-obj-15","tags":["rappel"],"difficulty":2,"question":"Chez la femme enceinte avec exanthème, quelles sérologies demande-t-on ?","answer":"Toxoplasmose, rubéole, CMV, parvovirus B19, syphilis","accept":["toxoplasmose, rubéole, cmv, parvovirus b19, syphilis","toxoplasmose, rubéole, cmv, parvovirus, syphilis","toxoplasmose rubéole cmv parvovirus syphilis"],"keywords":["toxo","rubéole","cmv","parvovirus","syphilis"],"explanation":"Femme enceinte : sérologies de toxoplasmose, rubéole, CMV, parvovirus B19 et syphilis, en tenant compte de son statut sérologique de début de grossesse (p. 85).","src":"p. 85","deep":"**À relier** : risques : rubéole → mort fœtale ou malformations ; parvovirus B19 → anasarque fœtale (2e trimestre) ; syphilis → forme congénitale (p. 83, 85-86).\n**Piège** : le parvovirus B19 n'est pas tératogène : son risque fœtal est l'anasarque, la myocardite et l'anémie (p. 86)."},{"id":"d114-qroc-712","type":"QROC","rank":"B","objective":"d114-obj-15","tags":["rappel"],"difficulty":1,"question":"Citez les quatre principaux exanthèmes à risque chez la femme enceinte.","answer":"Rubéole, parvovirus B19, toxoplasmose, syphilis","accept":["rubéole","parvovirus","toxoplasmose","syphilis"],"keywords":[],"explanation":"Les quatre exanthèmes à risque chez la femme enceinte : rubéole (mort fœtale ou malformations), parvovirus B19 (anasarque fœtale), toxoplasmose et syphilis (forme congénitale) (p. 83).","src":"p. 83","deep":"**Pourquoi** : chez la femme enceinte, le bilan d'un exanthème tient compte de son statut sérologique de début de grossesse : sérologies de toxoplasmose, rubéole, CMV, parvovirus B19 et syphilis (p. 85).\n**Piège** : le parvovirus B19 n'est pas tératogène ; le risque est l'anasarque fœtale lors d'une infection au 2e trimestre (p. 86).\n**À relier** : la rubéole n'expose la grossesse qu'en l'absence d'immunité (femme enceinte non immunisée) (p. 85, 90)."},{"id":"d114-qroc-713","type":"QROC","rank":"B","objective":"d114-obj-15","tags":["rappel"],"difficulty":2,"question":"Quelle malformation ou atteinte fœtale redoute-t-on avec la rubéole pendant la grossesse ?","answer":"Mort fœtale ou malformations neurologiques et sensorielles","accept":["mort fœtale","malformations","malformations neurologiques","malformations neurologiques sensorielles"],"keywords":[],"explanation":"La rubéole de la femme enceinte non immunisée expose à une mort fœtale ou à des malformations neurologiques sensorielles (tableau 4.1, p. 85) ; le Collège parle aussi de malformations fœtales graves (p. 90).","src":"p. 85","deep":"**Pourquoi** : le risque n'existe que si la femme enceinte n'est pas immunisée : le bilan s'interprète selon son statut sérologique de début de grossesse (p. 85).\n**Piège** : ne pas confondre avec le parvovirus B19, sans risque tératogène, dont le risque au 2e trimestre est l'anasarque fœtale (p. 86).\n**À relier** : rubéole = exanthème roséoliforme discret (2 à 4 jours) ; pas d'éviction recommandée, mais information du personnel, des parents et de la femme enceinte (p. 85)."},{"id":"d114-qroc-714","type":"QROC","rank":"B","objective":"d114-obj-12","tags":["rappel"],"difficulty":2,"question":"Citez les quatre causes principales d'exanthème roséoliforme.","answer":"Exanthème subit, rubéole, primo-infection VIH, syphilis secondaire","accept":["exanthème subit","rubéole","primo-infection vih","syphilis secondaire","roséole"],"keywords":[],"explanation":"Roséoliforme (petites macules rosées, pâles, bien séparées) : exanthème subit (HHV6), rubéole, primo-infection VIH et syphilis secondaire (1re floraison) (p. 83, 85).","src":"p. 83, 85","deep":"**Pourquoi** : deux causes du nourrisson ou de l'adulte jeune (exanthème subit de 6 à 18 mois, rubéole de 15 à 25 ans) et deux causes rejoignant celles à évoquer devant tout exanthème de l'adulte : VIH, syphilis, médicaments (p. 83, 85, 90).\n**Piège** : la rougeole est morbilliforme, pas roséoliforme (p. 86).\n**À relier** : exanthème de l'adulte sans cause évidente : test tréponémique, charge virale VIH et sérologie VIH combinée (Ag p24) (p. 85)."},{"id":"d114-qroc-715","type":"QROC","rank":"B","objective":"d114-obj-13","tags":["rappel"],"difficulty":2,"question":"Citez les trois causes principales d'exanthème morbilliforme.","answer":"Rougeole, mégalérythème épidémique, mononucléose infectieuse","accept":["rougeole","mégalérythème","mononucléose"],"keywords":[],"explanation":"Morbilliforme (maculo-papules rouges pouvant confluer en plaques séparées par des espaces de peau saine) : rougeole, mégalérythème épidémique (parvovirus B19), mononucléose infectieuse (EBV) ; autres : primo-infection VIH, toxidermie, syndrome de Kawasaki (p. 83, 85-86).","src":"p. 83, 86","deep":"**Pourquoi** : trois virus : rougeole (morbillivirus), mégalérythème de l'enfant de 5 à 10 ans (parvovirus B19), mononucléose de l'adolescent (EBV) (p. 86).\n**Piège** : dans la mononucléose, l'exanthème est inconstant (5-10 %) sauf prescription de pénicilline A : c'est le rash à l'ampicilline, à ne pas confondre avec une toxidermie aux pénicillines (p. 82, 86).\n**À relier** : les espaces de peau saine distinguent le morbilliforme du scarlatiniforme, sans intervalle de peau saine (p. 85)."},{"id":"d114-qroc-716","type":"QROC","rank":"B","objective":"d114-obj-14","tags":["rappel"],"difficulty":2,"question":"Citez les deux causes principales d'exanthème scarlatiniforme.","answer":"Scarlatine et syndrome de Kawasaki","accept":["scarlatine","kawasaki"],"keywords":[],"explanation":"Scarlatiniforme (plaques diffuses rouge vif, sans intervalle de peau saine, s'intensifiant dans les plis) : scarlatine et syndrome de Kawasaki (p. 83, 85) ; le tableau 4.3 y range aussi la scarlatine staphylococcique (épidermolyse staphylococcique) (p. 88).","src":"p. 83, 88","deep":"**Pourquoi** : la scarlatine est due au streptocoque du groupe A sécréteur d'exotoxines ; le Kawasaki est une vasculite systémique aiguë (p. 88).\n**Piège** : un exanthème diffus scarlatiniforme fébrile de survenue brutale doit faire rechercher un choc toxique staphylococcique et ses signes hémodynamiques (p. 90).\n**À relier** : l'âge aide : Kawasaki avant 5 ans, scarlatine de 5 à 10 ans (p. 88)."},{"id":"d114-qroc-717","type":"QROC","rank":"B","objective":"d114-obj-12","tags":["rappel"],"difficulty":2,"question":"Quelle est la cause virale de l'exanthème roséoliforme apparaissant après 3 jours de fièvre à 39-40 °C chez un nourrisson ?","answer":"HHV6","accept":["hhv6","herpès virus 6","herpèsvirus 6","herpes virus 6"],"keywords":[],"explanation":"Exanthème subit (roséole infantile) = primo-infection par HHV6 (human herpesvirus 6) ; une éruption roséoliforme après 3 jours de fièvre isolée chez un nourrisson l'évoque (p. 85, 90).","src":"p. 85, 90","deep":"**Pourquoi** : la séquence est typique : fièvre à 39-40 °C isolée pendant 48-72 heures, puis exanthème prédominant sur le tronc, en une seule poussée (p. 85).\n**Piège** : dans la rougeole, l'éruption suit une phase pré-éruptive avec catarrhe oculo-nasal, conjonctivite et signe de Köplick, pas une fièvre isolée (p. 86).\n**À relier** : terrain = nourrisson de 6 à 18 mois ; complications rares dont les convulsions fébriles (p. 85)."},{"id":"d114-qroc-718","type":"QROC","rank":"B","objective":"d114-obj-12","tags":["rappel"],"difficulty":2,"question":"Où prédomine l'exanthème de l'exanthème subit ?","answer":"Sur le tronc","accept":["tronc"],"keywords":["tronc"],"explanation":"Dans l'exanthème subit, après 48-72 heures de fièvre isolée (39-40 °C), l'exanthème prédomine sur le tronc et évolue en une seule poussée (p. 85).","src":"p. 85","deep":"**Pourquoi** : cette topographie, après une fièvre isolée chez un nourrisson de 6 à 18 mois, fait évoquer la roséole infantile (HHV6) (p. 85, 90).\n**Piège** : la rougeole débute en rétro-auriculaire puis s'étend à tout le corps ; le mégalérythème commence par une atteinte érythémateuse et un œdème des joues (p. 86).\n**À relier** : dans le tableau 4.1, c'est l'exanthème subit qui est « souvent asymptomatique » (p. 85)."},{"id":"d114-qroc-719","type":"QROC","rank":"B","objective":"d114-obj-12","tags":["rappel"],"difficulty":2,"question":"Quelle complication rare fébrile peut survenir au cours de l'exanthème subit ?","answer":"Les convulsions fébriles","accept":["convulsions","convulsion fébrile","convulsions fébriles"],"keywords":["convuls"],"explanation":"Complications rares de l'exanthème subit : convulsions fébriles, méningite virale, hépatite aiguë, pneumopathie, syndrome mononucléosique (p. 85).","src":"p. 85","deep":"**Pourquoi** : la fièvre de l'exanthème subit est élevée (39-40 °C) et isolée pendant 48-72 heures avant l'éruption, chez un nourrisson de 6 à 18 mois (p. 85).\n**Piège** : ces complications sont rares : l'exanthème subit est souvent asymptomatique (p. 85).\n**À relier** : le syndrome mononucléosique figure parmi ses complications rares : ne pas conclure d'emblée à une mononucléose à EBV, maladie de l'adolescent (p. 85-86)."},{"id":"d114-qroc-720","type":"QROC","rank":"B","objective":"d114-obj-12","tags":["rappel"],"difficulty":1,"question":"Quelle éviction de la collectivité est recommandée pour la rubéole ?","answer":"Aucune","accept":["aucune","pas d'éviction","pas de recommandation"],"keywords":[],"explanation":"Rubéole : pas de recommandation d'éviction de la collectivité ; on informe le personnel, les parents et la femme enceinte (p. 85).","src":"p. 85","deep":"**Pourquoi** : la mesure prévue n'est pas l'éviction mais l'information du personnel, des parents et de la femme enceinte ; chez une femme enceinte non immunisée, la rubéole expose à une mort fœtale ou à des malformations (p. 85).\n**Piège** : dans le tableau 4.1, cette ligne appartient à la colonne rubéole, pas à l'exanthème subit (p. 85).\n**À relier** : la rougeole impose une éviction jusqu'à 5 jours après le début de l'éruption, la scarlatine jusqu'à 48 heures après le début du traitement (p. 86, 88)."},{"id":"d114-qroc-721","type":"QROC","rank":"B","objective":"d114-obj-27","tags":["rappel"],"difficulty":2,"question":"Quel est l'âge de survenue de la rubéole ?","answer":"15 à 25 ans","accept":["15 à 25 ans","15-25 ans","15 à 25"],"keywords":["15"],"explanation":"Rubéole : âge de survenue 15 à 25 ans ; incubation 3 semaines (p. 85).","src":"p. 85","deep":"**Pourquoi** : la rubéole touche l'adulte jeune, alors que l'exanthème subit, autre cause roséoliforme, touche le nourrisson de 6 à 18 mois (p. 85).\n**Piège** : « souvent asymptomatique » se rapporte, dans le tableau 4.1, à l'exanthème subit et non à la rubéole (p. 85).\n**À relier** : contagiosité de 7 jours avant à 14 jours après le début de l'éruption ; femme enceinte non immunisée : risque de mort fœtale ou de malformations (p. 85)."},{"id":"d114-qroc-722","type":"QROC","rank":"A","objective":"d114-obj-27","tags":["rappel"],"difficulty":2,"question":"Quel est le caractère de l'exanthème de la rubéole ?","answer":"Discret, 2 à 4 jours","accept":["discret","exanthème discret"],"keywords":["discret"],"explanation":"Rubéole : exanthème roséoliforme discret, de 2 à 4 jours, avec arthralgies et conjonctivite (p. 85).","src":"p. 85","deep":"**Pourquoi** : la rubéole, due au virus de la rubéole, donne un exanthème roséoliforme (petites macules rosées pâles, bien séparées), ici discret et bref (p. 85).\n**Piège** : les arthralgies ne sont pas propres à la rubéole : on les retrouve dans le mégalérythème épidémique (p. 86).\n**À relier** : chez la femme enceinte non immunisée, la rubéole expose à une mort fœtale ou à des malformations fœtales graves (p. 85, 90)."},{"id":"d114-qroc-723","type":"QROC","rank":"A","objective":"d114-obj-26","tags":["rappel"],"difficulty":2,"question":"Quel est l'agent de la rougeole ?","answer":"Le morbillivirus (paramyxovirus)","accept":["morbillivirus","paramyxovirus"],"keywords":[],"explanation":"Rougeole : due au morbillivirus (paramyxovirus) ; incubation 10-12 jours (p. 86).","src":"p. 86","deep":"**Pourquoi** : on doit savoir l'évoquer devant l'association catarrhe oculo-nasal, conjonctivite et exanthème fébrile (p. 90).\n**Piège** : ne pas confondre avec le parvovirus B19, agent du mégalérythème, autre cause d'exanthème morbilliforme (p. 86).\n**À relier** : maladie à déclaration obligatoire ; éviction de la collectivité jusqu'à 5 jours après le début de l'éruption (p. 86)."},{"id":"d114-qroc-724","type":"QROC","rank":"A","objective":"d114-obj-26","tags":["rappel"],"difficulty":2,"question":"Quelle est la durée d'incubation de la rougeole ?","answer":"10 à 12 jours","accept":["10-12 jours","10 à 12 jours","10 à 12"],"keywords":["10"],"explanation":"Incubation de la rougeole : 10 à 12 jours ; contagiosité de 3-5 jours avant à 4 jours après l'éruption (p. 86).","src":"p. 86","deep":"**Pourquoi** : le malade est contagieux dès 3-5 jours avant l'éruption ; l'anamnèse recherche un contexte épidémique et un possible contage (p. 85-86).\n**Piège** : la mononucléose a une incubation bien plus longue, de 4 à 6 semaines (p. 86).\n**À relier** : éviction de la collectivité jusqu'à 5 jours après le début de l'éruption, information du personnel et des parents (p. 86)."},{"id":"d114-qroc-725","type":"QROC","rank":"A","objective":"d114-obj-26","tags":["rappel"],"difficulty":2,"question":"Citez 2 signes de la phase pré-éruptive de la rougeole.","answer":"Catarrhe oculo-nasal, fièvre élevée (39-40 °C), signe de Köplick, conjonctivite","accept":["catarrhe","fièvre","köplick","koplick","conjonctivite","fièvre élevée","catarrhe oculo-nasal"],"keywords":[],"explanation":"Phase pré-éruptive de la rougeole : catarrhe oculo-nasal, fièvre élevée (39-40 °C), signe de Köplick (semis de papules à la face interne des joues), conjonctivite (p. 86).","src":"p. 86","deep":"**Pourquoi** : catarrhe oculo-nasal + conjonctivite + exanthème fébrile : c'est l'association qui doit faire évoquer une rougeole (p. 90).\n**Piège** : le signe de Köplick est un semis de papules de la face interne des joues, à ne pas confondre avec la langue framboisée (scarlatine, Kawasaki) (p. 86, 88).\n**À relier** : l'exanthème débute ensuite en rétro-auriculaire puis s'étend à l'ensemble du corps en une seule poussée (p. 86)."},{"id":"d114-qroc-726","type":"QROC","rank":"A","objective":"d114-obj-26","tags":["rappel"],"difficulty":2,"question":"Par où débute l'exanthème de la rougeole ?","answer":"Par la région rétro-auriculaire","accept":["rétro-auriculaire","retro-auriculaire","derrière les oreilles"],"keywords":["auricul"],"explanation":"L'exanthème de la rougeole débute en rétro-auriculaire puis s'étend à l'ensemble du corps en une seule poussée (p. 86).","src":"p. 86","deep":"**Pourquoi** : il fait suite à la phase pré-éruptive : catarrhe oculo-nasal, fièvre 39-40 °C, signe de Köplick, conjonctivite (p. 86).\n**Piège** : d'autres topographies orientent ailleurs : tronc pour l'exanthème subit, grands plis pour la scarlatine, joues pour le mégalérythème (p. 85-86, 88).\n**À relier** : morbilliforme = maculo-papules rouges pouvant confluer en plaques séparées par des espaces de peau saine (p. 85)."},{"id":"d114-qroc-727","type":"QROC","rank":"A","objective":"d114-obj-26","tags":["rappel"],"difficulty":2,"question":"Quelle complication oculaire grave peut survenir lors d'une rougeole ?","answer":"Une kératite avec risque de cécité","accept":["kératite","cécité"],"keywords":[],"explanation":"Complications de la rougeole : pneumopathie, hépatite et pancréatite, encéphalite (grave), kératite et cécité (p. 86).","src":"p. 86","deep":"**Pourquoi** : la kératite, avec risque de cécité, est la complication oculaire citée par le Collège, à côté de l'encéphalite qualifiée de grave (p. 86).\n**Piège** : la conjonctivite de la phase pré-éruptive est un signe d'orientation, pas la complication (p. 86, 90).\n**À relier** : la rougeole est une maladie à déclaration obligatoire ; éviction jusqu'à 5 jours après le début de l'éruption (p. 86)."},{"id":"d114-qroc-728","type":"QROC","rank":"A","objective":"d114-obj-26","tags":["rappel"],"difficulty":1,"question":"Quel statut administratif concerne la rougeole ?","answer":"Maladie à déclaration obligatoire","accept":["déclaration obligatoire","maladie à déclaration obligatoire"],"keywords":["déclaration"],"explanation":"Rougeole = maladie à déclaration obligatoire ; éviction de la collectivité jusqu'à 5 jours après le début de l'éruption ; informer le personnel et les parents (p. 86).","src":"p. 86","deep":"**Pourquoi** : dans les tableaux 4.1 à 4.3, la déclaration obligatoire n'est indiquée que pour la rougeole (p. 85-88).\n**Piège** : la rubéole ne fait l'objet d'aucune recommandation d'éviction, seulement d'une information (p. 85).\n**À relier** : conduite à tenir autour d'un cas de rougeole : déclaration, éviction jusqu'à 5 jours après le début de l'éruption, information du personnel et des parents (p. 86)."},{"id":"d114-qroc-729","type":"QROC","rank":"A","objective":"d114-obj-26","tags":["rappel"],"difficulty":2,"question":"Jusqu'à quand l'éviction de la collectivité est-elle recommandée dans la rougeole ?","answer":"Jusqu'à 5 jours après le début de l'éruption","accept":["5 jours","5 jours après le début de l'éruption"],"keywords":["5"],"explanation":"Rougeole : éviction de la collectivité recommandée jusqu'à 5 jours après le début de l'éruption, avec information du personnel et des parents (p. 86).","src":"p. 86","deep":"**Pourquoi** : la contagiosité de la rougeole va de 3-5 jours avant à 4 jours après l'éruption (p. 86).\n**Piège** : le point de départ est le début de l'éruption, pas le début d'un traitement (règle de la scarlatine : 48 heures après le début du traitement) (p. 86, 88).\n**À relier** : la rougeole est une maladie à déclaration obligatoire (p. 86)."},{"id":"d114-qroc-730","type":"QROC","rank":"B","objective":"d114-obj-28","tags":["rappel"],"difficulty":2,"question":"Quel est l'aspect du visage dans le mégalérythème épidémique ?","answer":"Aspect « souffleté » (érythème et œdème des joues)","accept":["souffleté","soufflet","joues"],"keywords":[],"explanation":"Mégalérythème (parvovirus B19) : atteinte érythémateuse et œdème des joues, aspect « souffleté » du visage (fig. 4.1), puis érythème du tronc à bords émiettés (en guirlande), puis érythème en « gants et chaussettes » (p. 86-87).","src":"p. 86-87","deep":"**Pourquoi** : la succession visage, tronc, extrémités permet de reconnaître l'éruption du mégalérythème (p. 86-87).\n**Piège** : le Kawasaki touche aussi les extrémités (érythème et œdème, puis desquamation en « doigt de gant »), mais avec une fièvre > 38,5 °C plus de 5 jours, alors que la fièvre du mégalérythème est modérée (p. 86, 88).\n**À relier** : terrain = enfant de 5 à 10 ans ; fièvre modérée, arthralgies (p. 86)."},{"id":"d114-qroc-731","type":"QROC","rank":"B","objective":"d114-obj-28","tags":["rappel"],"difficulty":2,"question":"Quel est l'aspect de l'exanthème du tronc dans le mégalérythème ?","answer":"Un érythème à bords émiettés (en guirlande)","accept":["bords émiettés","guirlande","émiettés"],"keywords":[],"explanation":"Après l'atteinte des joues, érythème du tronc à bords émiettés (fig. 4.2 : exanthème figuré en guirlande), puis « gants et chaussettes » (p. 86-87).","src":"p. 86-87","deep":"**Pourquoi** : c'est le 2e temps de l'éruption du mégalérythème, entre l'aspect souffleté des joues et l'érythème en gants et chaussettes (p. 86-87).\n**Piège** : le mégalérythème est morbilliforme comme la rougeole, mais sa fièvre est modérée (p. 86).\n**À relier** : chez la femme enceinte, pas de risque tératogène, mais au 2e trimestre risque d'anasarque fœtale, de myocardite et d'anémie fœtale (p. 86)."},{"id":"d114-qroc-732","type":"QROC","rank":"B","objective":"d114-obj-28","tags":["rappel"],"difficulty":2,"question":"Quelle est la durée d'incubation du mégalérythème épidémique ?","answer":"14 jours","accept":["14 jours","14"],"keywords":["14"],"explanation":"Mégalérythème épidémique (parvovirus B19) : incubation 14 jours ; contagiosité limitée à la phase pré-éruptive (p. 86).","src":"p. 86","deep":"**Pourquoi** : chaque fièvre éruptive a son incubation : rougeole 10-12 jours, mégalérythème 14 jours, rubéole 3 semaines, mononucléose 4 à 6 semaines (p. 85-86).\n**Piège** : le mégalérythème touche l'enfant de 5 à 10 ans, comme la scarlatine (p. 86, 88).\n**À relier** : complications surtout chez l'immunodéprimé, le patient avec anémie chronique et la femme enceinte (p. 86)."},{"id":"d114-qroc-733","type":"QROC","rank":"B","objective":"d114-obj-28","tags":["rappel"],"difficulty":2,"question":"Quand le mégalérythème épidémique est-il contagieux ?","answer":"Pendant la phase pré-éruptive seulement","accept":["phase pré-éruptive","pré-éruptive"],"keywords":[],"explanation":"La contagiosité du mégalérythème épidémique est limitée à la phase pré-éruptive (p. 86).","src":"p. 86","deep":"**Piège** : ne pas transposer la règle de la rougeole, contagieuse de 3-5 jours avant à 4 jours après l'éruption (p. 86).\n**À relier** : la mononucléose est contagieuse au maximum pendant la phase aiguë, parfois jusqu'à 6 mois ; la rubéole de 7 jours avant à 14 jours après le début de l'éruption (p. 85-86)."},{"id":"d114-qroc-734","type":"QROC","rank":"B","objective":"d114-obj-28","tags":["rappel"],"difficulty":3,"question":"Chez qui les complications du mégalérythème sont-elles surtout à craindre ?","answer":"Immunodéprimé, anémie chronique, femme enceinte","accept":["immunodéprimé","anémie chronique","femme enceinte"],"keywords":[],"explanation":"Complications du mégalérythème : surtout chez l'immunodéprimé, le patient avec anémie chronique et la femme enceinte (p. 86).","src":"p. 86","deep":"**Pourquoi** : chez la femme enceinte, le risque n'est pas tératogène : une infection au 2e trimestre expose à l'anasarque fœtale, à la myocardite et à l'anémie fœtale (p. 86).\n**Piège** : « pas tératogène » ne veut pas dire « sans risque » : la primo-infection à parvovirus pendant la grossesse expose à l'anasarque fœtale (p. 90).\n**À relier** : le parvovirus B19 fait partie des sérologies demandées devant un exanthème chez la femme enceinte (p. 85)."},{"id":"d114-qroc-735","type":"QROC","rank":"B","objective":"d114-obj-28","tags":["rappel"],"difficulty":2,"question":"Quels risques fœtaux, hors tératogénicité, d'une infection à parvovirus B19 au 2e trimestre ? Citez-en 2.","answer":"Anasarque fœtale, myocardite, anémie fœtale","accept":["anasarque","myocardite","anémie fœtale"],"keywords":[],"explanation":"Parvovirus B19 : pas de risque tératogène ; une infection au 2e trimestre expose à l'anasarque fœtale, à une myocardite et à une anémie fœtale (p. 86).","src":"p. 86","deep":"**Pourquoi** : le Collège précise l'absence de risque tératogène : on redoute une atteinte du fœtus (anasarque, myocardite, anémie), pas une malformation (p. 86).\n**Piège** : c'est la rubéole qui expose à une mort fœtale ou à des malformations neurologiques sensorielles chez la femme non immunisée (p. 85).\n**À relier** : la primo-infection à parvovirus pendant la grossesse expose au risque d'anasarque fœtale (p. 90)."},{"id":"d114-qroc-736","type":"QROC","rank":"A","objective":"d114-obj-30","tags":["rappel"],"difficulty":2,"question":"Quelle est la durée d'incubation de la mononucléose infectieuse ?","answer":"4 à 6 semaines","accept":["4 à 6 semaines","4-6 semaines"],"keywords":["4"],"explanation":"Mononucléose infectieuse (EBV) : incubation 4 à 6 semaines, terrain adolescent (p. 86).","src":"p. 86","deep":"**Pourquoi** : c'est une incubation bien plus longue que celle de la rougeole (10-12 jours), autre cause morbilliforme (p. 86).\n**Piège** : sa contagiosité est maximale pendant la phase aiguë et peut aller jusqu'à 6 mois (p. 86).\n**À relier** : clinique : fièvre et asthénie importante, poly-adénopathie, splénomégalie (p. 86)."},{"id":"d114-qroc-737","type":"QROC","rank":"A","objective":"d114-obj-30","tags":["rappel"],"difficulty":2,"question":"Sur quel terrain survient classiquement la mononucléose infectieuse ?","answer":"L'adolescent","accept":["adolescent","adolescents","ado"],"keywords":["adolescent"],"explanation":"Mononucléose infectieuse (EBV) : terrain adolescent ; fièvre et asthénie importante, poly-adénopathie, splénomégalie (p. 86).","src":"p. 86","deep":"**Pourquoi** : l'âge oriente parmi les exanthèmes morbilliformes : mégalérythème de l'enfant de 5 à 10 ans (rang B), mononucléose de l'adolescent (p. 86).\n**Piège** : la « fièvre modérée » du tableau 4.2 appartient au mégalérythème, pas à la mononucléose (p. 86).\n**À relier** : NFS : lymphocytose élevée avec lymphocytes hyperbasophiles ; exanthème inconstant (5-10 %) sauf prescription de pénicilline A (p. 86)."},{"id":"d114-qroc-738","type":"QROC","rank":"A","objective":"d114-obj-30","tags":["rappel"],"difficulty":2,"question":"Quelle complication splénique redoute-t-on dans la mononucléose infectieuse ?","answer":"La rupture splénique","accept":["rupture splénique","rupture de rate"],"keywords":["rupture"],"explanation":"Complications rares de la mononucléose : hépatite, méningo-encéphalite, rupture splénique, agranulocytose (p. 86).","src":"p. 86","deep":"**Pourquoi** : la splénomégalie fait partie du tableau clinique de la mononucléose (p. 86).\n**Piège** : parmi ses complications rares figure l'agranulocytose ; une thrombocytose avec hyperleucocytose à PNN oriente plutôt vers le Kawasaki (p. 86, 88).\n**À relier** : NFS : lymphocytose élevée avec lymphocytes hyperbasophiles (p. 86)."},{"id":"d114-qroc-739","type":"QROC","rank":"A","objective":"d114-obj-30","tags":["rappel"],"difficulty":2,"question":"Quelle proportion de mononucléoses s'accompagne d'un exanthème en l'absence de pénicilline A ?","answer":"5 à 10 % (inconstant)","accept":["5-10 %","5 à 10 %","5 à 10"],"keywords":["5","10"],"explanation":"Exanthème inconstant (5-10 %) au cours de la mononucléose, sauf en cas de prescription de pénicilline A (p. 86).","src":"p. 86","deep":"**Pourquoi** : hors pénicilline A, l'exanthème est donc rare ; le tableau du Collège associe fièvre-asthénie importante, poly-adénopathie, splénomégalie et lymphocytose à lymphocytes hyperbasophiles (p. 86).\n**Piège** : l'exanthème sous pénicilline A au cours d'une infection à EBV est une complication classique, à ne pas confondre avec une toxidermie aux pénicillines (p. 82).\n**À relier** : terrain = adolescent ; incubation 4 à 6 semaines (p. 86)."},{"id":"d114-qroc-740","type":"QROC","rank":"A","objective":"d114-obj-30","tags":["rappel"],"difficulty":2,"question":"Quels signes cliniques accompagnent la fièvre dans la mononucléose infectieuse ?","answer":"Asthénie, poly-adénopathie, splénomégalie","accept":["asthénie","adénopathie","splénomégalie"],"keywords":[],"explanation":"Mononucléose : fièvre avec asthénie importante, poly-adénopathie, splénomégalie (p. 86).","src":"p. 86","deep":"**Pourquoi** : chez un adolescent, cette association, avec une lymphocytose à lymphocytes hyperbasophiles, oriente vers l'EBV (p. 86).\n**Piège** : la fièvre modérée appartient au mégalérythème dans le tableau 4.2 ; la mononucléose associe fièvre et asthénie importante (p. 86).\n**À relier** : complication rare à connaître devant une splénomégalie : la rupture splénique (p. 86)."},{"id":"d114-qroc-741","type":"QROC","rank":"B","objective":"d114-obj-30","tags":["rappel"],"difficulty":2,"question":"Citez 2 classes médicamenteuses responsables d'une toxidermie morbilliforme.","answer":"β-lactamines, sulfamides, anti-comitiaux","accept":["lactamines","sulfamides","anti-comitiaux","anticomitiaux","antiépileptiques"],"keywords":[],"explanation":"Toxidermies morbilliformes : β-lactamines, sulfamides, anti-comitiaux… (tableau 4.2, colonne « Autres », p. 86).","src":"p. 86","deep":"**Pourquoi** : une origine médicamenteuse est orientée par le prurit, le caractère polymorphe de l'éruption et une hyperéosinophilie sanguine (p. 85).\n**Piège** : chez l'adulte, penser aux médicaments, mais aussi au VIH et à la syphilis (p. 90).\n**À relier** : la toxidermie (DRESS) est aussi une cause majeure d'érythrodermie (p. 91, 93)."},{"id":"d114-qroc-742","type":"QROC","rank":"A","objective":"d114-obj-31","tags":["rappel"],"difficulty":2,"question":"Quel est le terrain de la scarlatine ?","answer":"Enfant de 5 à 10 ans","accept":["5 à 10 ans","5-10 ans"],"keywords":["5"],"explanation":"Scarlatine : streptocoque du groupe A sécréteur d'exotoxines ; enfant de 5 à 10 ans ; incubation 2 à 4 jours (p. 88).","src":"p. 88","deep":"**Pourquoi** : l'âge aide à trier les scarlatiniformes : Kawasaki avant 5 ans (rang B) ; épidermolyse staphylococcique du nouveau-né, du nourrisson, du jeune enfant ou de l'adulte immunodéprimé (p. 88).\n**Piège** : l'angine rouge oriente vers la scarlatine ; la forme staphylococcique se caractérise par l'absence d'angine (p. 88).\n**À relier** : amoxicilline ; complications post-streptococciques : glomérulonéphrites, rhumatisme articulaire aigu (p. 88)."},{"id":"d114-qroc-743","type":"QROC","rank":"A","objective":"d114-obj-31","tags":["rappel"],"difficulty":2,"question":"Quel est l'aspect de la langue dans la scarlatine ?","answer":"Dépapillation progressive en « V », langue framboisée","accept":["framboisée","framboisee","dépapillation"],"keywords":["framboi"],"explanation":"Scarlatine : dépapillation progressive de la langue en « V », langue framboisée (fig. 4.5) (p. 88-89).","src":"p. 88","deep":"**Pourquoi** : la langue de la scarlatine s'intègre à un tableau d'angine rouge avec adénopathies sous-maxillaires et d'éruption prédominant aux grands plis (p. 88).\n**Piège** : la langue framboisée existe aussi dans le Kawasaki (énanthème avec chéilite) : elle ne permet pas à elle seule de trancher (p. 88).\n**À relier** : prélèvement de gorge, amoxicilline, éviction jusqu'à 48 heures après le début du traitement (p. 88)."},{"id":"d114-qroc-744","type":"QROC","rank":"B","objective":"d114-obj-31","tags":["rappel"],"difficulty":2,"question":"Quels examens demande-t-on devant une scarlatine suspectée chez l'enfant ?","answer":"NFS et prélèvement de gorge","accept":["nfs","prélèvement de gorge"],"keywords":[],"explanation":"Chez l'enfant, aucun examen n'est indispensable sauf suspicion de scarlatine (NFS, prélèvement de gorge) ou de syndrome de Kawasaki (NFS, plaquettes, échographie cardiaque) (p. 85).","src":"p. 85","deep":"**Pourquoi** : le prélèvement de gorge figure aussi dans la colonne scarlatine (streptocoque du groupe A) du tableau 4.3 (p. 85, 88).\n**Piège** : dans la scarlatine staphylococcique (sans angine), on fait des prélèvements bactériologiques, pas un prélèvement de gorge (p. 88).\n**À relier** : chez l'adulte sans cause évidente : NFS, tests hépatiques, sérodiagnostic de MNI, test tréponémique, charge virale VIH, sérologie VIH combinée (p. 85)."},{"id":"d114-qroc-745","type":"QROC","rank":"A","objective":"d114-obj-31","tags":["rappel"],"difficulty":2,"question":"Jusqu'à quand dure l'éviction de la collectivité dans la scarlatine ?","answer":"Jusqu'à 48 heures après le début du traitement","accept":["48 heures","48h","48 h"],"keywords":["48"],"explanation":"Scarlatine : éviction de la collectivité jusqu'à 48 heures après le début du traitement antibiotique (amoxicilline) (p. 88).","src":"p. 88","deep":"**Pourquoi** : la contagiosité de la scarlatine (2 à 3 semaines) persiste 48 heures après la mise en route du traitement (p. 88).\n**Piège** : le point de départ est le début du traitement ; pour la rougeole, c'est 5 jours après le début de l'éruption (p. 86).\n**À relier** : même délai (48 heures après le début du traitement) pour l'éviction scolaire de la scarlatine staphylococcique, traitée par oxacilline (p. 88)."},{"id":"d114-qroc-746","type":"QROC","rank":"A","objective":"d114-obj-31","tags":["rappel"],"difficulty":2,"question":"Citez 2 signes de la phase pré-éruptive de la scarlatine.","answer":"Début brutal, fièvre 39-40 °C, douleurs pharyngées, céphalées","accept":["début brutal","douleurs pharyngées","céphalées","angine rouge","fièvre élevée","adénopathies sous-maxillaires"],"keywords":[],"explanation":"Phase pré-éruptive de la scarlatine : début brutal, fièvre élevée (39-40 °C), douleurs pharyngées, céphalées, angine rouge et adénopathies sous-maxillaires (p. 88).","src":"p. 88","deep":"**Pourquoi** : la scarlatine est due au streptocoque du groupe A, à contamination aérienne ; l'éruption suit, prédominant aux grands plis (p. 88).\n**Piège** : l'absence d'angine figure dans la colonne de la scarlatine staphylococcique (p. 88).\n**À relier** : complications post-streptococciques : glomérulonéphrites, rhumatisme articulaire aigu (p. 88)."},{"id":"d114-qroc-747","type":"QROC","rank":"A","objective":"d114-obj-32","tags":["rappel"],"difficulty":2,"question":"Citez 2 signes cutanéo-muqueux du syndrome de Kawasaki.","answer":"Conjonctivite bilatérale, chéilite, langue framboisée, œdème des extrémités","accept":["conjonctivite","chéilite","langue framboisée","érythème des extrémités","oedème des extrémités","exanthème polymorphe","œdème des paupières"],"keywords":[],"explanation":"Kawasaki : conjonctivite bilatérale avec œdème des paupières, énanthème (chéilite, langue framboisée), érythème et œdème des extrémités, exanthème polymorphe, lymphadénite souvent asymétrique, avec fièvre > 38,5 °C plus de 5 jours (p. 88).","src":"p. 88","deep":"**Pourquoi** : le diagnostic est retenu si au moins cinq des six critères diagnostiques sont présents (p. 88).\n**Piège** : la langue framboisée n'est pas propre à la scarlatine : elle fait partie de l'énanthème du Kawasaki (p. 88).\n**À relier** : vasculite systémique aiguë ; un retard thérapeutique expose aux anévrismes coronariens (p. 88, 90)."},{"id":"d114-qroc-748","type":"QROC","rank":"A","objective":"d114-obj-32","tags":["rappel"],"difficulty":2,"question":"Quelle est la particularité de l'adénopathie du syndrome de Kawasaki ?","answer":"Lymphadénite souvent asymétrique","accept":["asymétrique","lymphadénite asymétrique"],"keywords":["asym"],"explanation":"Kawasaki : lymphadénite souvent asymétrique (p. 88).","src":"p. 88","deep":"**Pourquoi** : c'est l'atteinte ganglionnaire du syndrome adéno-cutanéo-muqueux de Kawasaki, avec la fièvre prolongée et l'atteinte cutanéo-muqueuse (p. 88).\n**Piège** : dans l'érythrodermie, la poly-adénopathie est généralisée, à ganglions souples et mobiles (p. 91) ; la mononucléose donne aussi une poly-adénopathie (p. 86).\n**À relier** : terrain = enfant de moins de 5 ans (rang B) ; hospitalisation indispensable (p. 88)."},{"id":"d114-qroc-749","type":"QROC","rank":"A","objective":"d114-obj-32","tags":["rappel"],"difficulty":2,"question":"Comment évolue l'érythème des extrémités dans le Kawasaki ?","answer":"Desquamation en doigt de gant","accept":["doigt de gant","en doigt de gant"],"keywords":["doigt"],"explanation":"Kawasaki : érythème et œdème des extrémités, puis desquamation en « doigt de gant » (p. 88).","src":"p. 88","deep":"**Pourquoi** : l'atteinte des extrémités (érythème, œdème) est un des signes du Kawasaki ; son évolution se fait vers cette desquamation (p. 88).\n**Piège** : la scarlatine desquame aussi, mais finement ou en lambeaux (p. 88-89).\n**À relier** : fièvre > 38,5 °C plus de 5 jours avec altération de l'état général ; biologie : CRP élevée, hyperleucocytose à PNN, thrombocytose (p. 88)."},{"id":"d114-qroc-750","type":"QROC","rank":"A","objective":"d114-obj-32","tags":["rappel"],"difficulty":2,"question":"Quelle anomalie plaquettaire biologique accompagne le syndrome de Kawasaki ?","answer":"Une thrombocytose","accept":["thrombocytose","hyperplaquettose"],"keywords":[],"explanation":"Kawasaki : syndrome inflammatoire avec CRP élevée, hyperleucocytose à PNN et thrombocytose (p. 88).","src":"p. 88","deep":"**Pourquoi** : le Kawasaki est une vasculite systémique aiguë ; le Collège décrit un syndrome inflammatoire biologique (p. 88).\n**Piège** : dans la mononucléose, la NFS montre une lymphocytose avec lymphocytes hyperbasophiles, pas une hyperleucocytose à PNN (p. 86).\n**À relier** : complications cardiaques (anévrismes coronariens, troubles du rythme) ; hospitalisation indispensable (p. 88)."},{"id":"d114-qroc-751","type":"QROC","rank":"A","objective":"d114-obj-32","tags":["rappel"],"difficulty":3,"question":"Citez 2 complications cardiaques possibles du syndrome de Kawasaki.","answer":"Anévrismes coronariens, troubles du rythme, infarctus, myocardite","accept":["anévrismes coronariens","trouble du rythme","infarctus","myocardite"],"keywords":[],"explanation":"Complications du Kawasaki : cardiaques avec anévrismes coronariens et troubles du rythme ; décès par myocardite ou infarctus (p. 88).","src":"p. 88","deep":"**Pourquoi** : le Kawasaki est une vasculite systémique aiguë (p. 88) ; un retard thérapeutique expose aux anévrismes coronariens (p. 90).\n**Piège** : myocardite et infarctus sont cités comme causes de décès, les anévrismes coronariens comme complication liée au retard thérapeutique (p. 88, 90).\n**À relier** : terrain = enfant de moins de 5 ans (rang B), fièvre > 38,5 °C plus de 5 jours ; hospitalisation indispensable (p. 88)."},{"id":"d114-qroc-752","type":"QROC","rank":"A","objective":"d114-obj-07","tags":["rappel"],"difficulty":2,"question":"Quelle est la porte d'entrée de l'épidermolyse staphylococcique chez le nouveau-né ?","answer":"Une infection du cordon","accept":["cordon","infection du cordon"],"keywords":["cordon"],"explanation":"Épidermolyse staphylococcique : nouveau-né avec infection du cordon, jeune enfant avec impétigo (p. 82).","src":"p. 82","deep":"**Pourquoi** : Staphylococcus aureus sécréteur d'entérotoxines ou de TSST1 ; terrain : nouveau-né, nourrisson, jeune enfant ou adulte immunodéprimé (p. 88).\n**Piège** : pas d'angine, contrairement à la scarlatine streptococcique (p. 88).\n**À relier** : traitement par oxacilline ; éviction scolaire jusqu'à 48 heures après le début du traitement (p. 88)."},{"id":"d114-qroc-753","type":"QROC","rank":"A","objective":"d114-obj-07","tags":["rappel"],"difficulty":1,"question":"Quel est le germe de l'épidermolyse staphylococcique (scarlatine staphylococcique) ?","answer":"Staphylococcus aureus","accept":["staphylococcus aureus","staphylocoque doré","staphylocoque","s. aureus"],"keywords":["staphylo"],"explanation":"Épidermolyse staphylococcique (scarlatine staphylococcique) : Staphylococcus aureus sécréteur d'entérotoxines ou de TSST1 (p. 88).","src":"p. 82, 88","deep":"**Pourquoi** : porte d'entrée : infection du cordon chez le nouveau-né, impétigo chez le jeune enfant (p. 82).\n**Piège** : « sécréteur d'exotoxines » qualifie le streptocoque du groupe A de la scarlatine ; le staphylocoque sécrète des entérotoxines ou la TSST1 (p. 88).\n**À relier** : forme sévère = choc toxique staphylococcique ; prélèvements bactériologiques, oxacilline (p. 88)."},{"id":"d114-qroc-754","type":"QROC","rank":"A","objective":"d114-obj-07","tags":["rappel"],"difficulty":2,"question":"Citez 2 éléments cliniques de l'épidermolyse staphylococcique.","answer":"Lésions péri-orificielles, décollements bulleux, fièvre","accept":["péri-orificielles","décollement bulleux","décollements bulleux","grands plis","fièvre","altération de l'état général"],"keywords":[],"explanation":"Épidermolyse staphylococcique : fièvre et altération de l'état général, exanthème débutant aux grands plis et aux régions péri-orificielles, puis décollements bulleux (p. 82, 88).","src":"p. 82, 88","deep":"**Pourquoi** : l'exanthème scarlatiniforme des plis et des orifices évolue vers un décollement bulleux (p. 88).\n**Piège** : ne pas l'appeler érythrodermie : un exanthème ou une nécrolyse avec décollement d'évolution aiguë n'en est pas une (p. 91).\n**À relier** : forme sévère : choc toxique staphylococcique ; traitement par oxacilline (p. 88)."},{"id":"d114-qroc-755","type":"QROC","rank":"A","objective":"d114-obj-21","tags":["rappel"],"difficulty":2,"question":"Comment est la desquamation au cours d'une érythrodermie ?","answer":"Constante, fine ou en larges lambeaux","accept":["constante","fine","lambeaux"],"keywords":[],"explanation":"Érythrodermie : desquamation constante, d'aspects variés, fine ou en larges lambeaux (p. 90).","src":"p. 90","deep":"**Pourquoi** : la desquamation fait partie de la définition : érythème confluant et desquamation sur plus de 90 % de la surface corporelle, depuis au moins 6 semaines (p. 90).\n**Piège** : la scarlatine peut aussi desquamer en lambeaux, mais un exanthème, d'évolution aiguë, n'est pas une érythrodermie (p. 88, 91).\n**À relier** : le prurit est lui aussi constant (p. 90)."},{"id":"d114-qroc-756","type":"QROC","rank":"A","objective":"d114-obj-21","tags":["rappel"],"difficulty":2,"question":"Quels signes thermiques accompagnent le prurit dans l'érythrodermie ?","answer":"Épisodes de fièvre et d'hypothermie (dysrégulation thermique)","accept":["fièvre et hypothermie","dysrégulation","hypothermie"],"keywords":["hypothermie"],"explanation":"Érythrodermie : prurit constant et dysrégulation cutanée thermique importante, avec épisodes de fièvre et d'hypothermie (p. 90).","src":"p. 90","deep":"**Pourquoi** : la dysrégulation thermique fait partie des signes cliniques de l'érythrodermie, avec l'érythème, la desquamation et le prurit constants (p. 90).\n**Piège** : des prélèvements bactériologiques peuvent être nécessaires en cas d'hyperthermie ou de complication infectieuse (p. 92).\n**À relier** : le réchauffement du malade limite les pertes caloriques, l'hypercatabolisme et la dénutrition (p. 93)."},{"id":"d114-qroc-757","type":"QROC","rank":"A","objective":"d114-obj-21","tags":["rappel"],"difficulty":2,"question":"Comment appelle-t-on l'épaississement cutané visible dans les plis lors d'une érythrodermie ?","answer":"Une pachydermie","accept":["pachydermie"],"keywords":["pachyderm"],"explanation":"Pachydermie mieux visible au niveau des plis, témoignant d'une infiltration cellulaire spécifique (p. 91).","src":"p. 91","deep":"**Pourquoi** : c'est un des signes de l'érythrodermie installée, avec la desquamation et le prurit constants (p. 90-91).\n**Piège** : la pachydermie se voit aux plis ; l'œdème, lui, est souvent marqué au visage (p. 91).\n**À relier** : la biopsie cutanée peut montrer des signes histologiques spécifiques de la maladie en cause ; à répéter si suspicion de lymphome cutané (p. 92)."},{"id":"d114-qroc-758","type":"QROC","rank":"A","objective":"d114-obj-21","tags":["rappel"],"difficulty":2,"question":"Quelle anomalie palpébrale peut s'observer dans l'œdème du visage de l'érythrodermie ?","answer":"Un ectropion","accept":["ectropion"],"keywords":["ectropion"],"explanation":"Érythrodermie : œdème souvent marqué du visage, où il peut exister un ectropion (p. 91).","src":"p. 91","deep":"**Pourquoi** : l'œdème du visage fait partie des signes de l'érythrodermie ; l'ectropion y est possible, non constant (p. 91).\n**Piège** : l'atteinte muqueuse oculaire de l'érythrodermie est une conjonctivite (énanthème possible), à distinguer de l'ectropion (p. 91).\n**À relier** : des troubles hémodynamiques avec déperditions hydro-électrolytiques et/ou protéiques complètent le tableau (p. 91)."},{"id":"d114-qroc-759","type":"QROC","rank":"A","objective":"d114-obj-21","tags":["rappel"],"difficulty":2,"question":"Quelle atteinte des phanères survient après quelques semaines d'érythrodermie ?","answer":"Chute des cheveux, sourcils et cils ; ongles dystrophiques (ligne de Beau)","accept":["ligne de beau","chute des cheveux","ongles dystrophiques","chute des cils"],"keywords":[],"explanation":"Après quelques semaines : chute des cheveux, des sourcils et des cils ; ongles dystrophiques, de croissance ralentie, d'où une ligne de Beau, voire une chute de l'ongle (p. 91).","src":"p. 91","deep":"**Pourquoi** : la ligne de Beau est rattachée par le Collège au ralentissement de la croissance des ongles (p. 91).\n**Piège** : cette atteinte des phanères n'apparaît qu'après quelques semaines d'évolution, ce qui cadre avec une érythrodermie évoluant depuis au moins 6 semaines (p. 90-91).\n**À relier** : autres signes d'une érythrodermie installée : pachydermie des plis, œdème du visage, poly-adénopathie (p. 91)."},{"id":"d114-qroc-760","type":"QROC","rank":"A","objective":"d114-obj-21","tags":["rappel"],"difficulty":2,"question":"Quels ganglions observe-t-on dans l'érythrodermie ?","answer":"Poly-adénopathie généralisée, souples et mobiles","accept":["polyadénopathie","poly-adénopathie","souples","mobiles"],"keywords":[],"explanation":"Érythrodermie : poly-adénopathie fréquemment associée et généralisée, ganglions parfois de grande taille, souples et mobiles (p. 91).","src":"p. 91","deep":"**Pourquoi** : elle fait partie du tableau clinique, avec l'érythème, la desquamation, le prurit et l'altération de l'état général (p. 90-91).\n**Piège** : l'aspect clinique ne préjuge pas de la cause de l'érythrodermie (p. 93).\n**À relier** : le syndrome de Sézary (lymphome T cutané épidermotrope) est une cause majeure ; biopsie à répéter si suspicion de lymphome cutané (p. 91-92)."},{"id":"d114-qroc-761","type":"QROC","rank":"A","objective":"d114-obj-21","tags":["rappel"],"difficulty":2,"question":"Quelles atteintes muqueuses peuvent accompagner une érythrodermie ?","answer":"Chéilite, conjonctivite, stomatite","accept":["chéilite","conjonctivite","stomatite"],"keywords":[],"explanation":"Énanthème possible au cours d'une érythrodermie : chéilite, conjonctivite ou stomatite (p. 91).","src":"p. 91","deep":"**Pourquoi** : l'atteinte muqueuse est possible, non constante, à la différence de la desquamation et du prurit, constants (p. 90-91).\n**Piège** : chéilite et conjonctivite existent aussi dans le Kawasaki (fièvre > 38,5 °C plus de 5 jours) : ce sont la durée (au moins 6 semaines) et la desquamation de plus de 90 % de la peau qui définissent l'érythrodermie (p. 88, 90)."},{"id":"d114-qroc-762","type":"QROC","rank":"A","objective":"d114-obj-21","tags":["rappel"],"difficulty":2,"question":"Quelle éruption ne peut pas être considérée comme une érythrodermie ?","answer":"Éléments multiples séparés par des intervalles de peau saine","accept":["intervalles de peau saine","peau saine"],"keywords":["peau saine"],"explanation":"Ne sont pas des érythrodermies : une éruption érythémato-squameuse à éléments multiples et diffus séparés par des intervalles de peau saine ; un exanthème ou une nécrolyse épidermique avec décollement d'évolution aiguë (p. 91).","src":"p. 91","deep":"**Pourquoi** : la définition exige un érythème confluant touchant l'ensemble des téguments, plus de 90 % de la surface corporelle (p. 90).\n**Piège** : érythrodermie n'est pas synonyme d'érythème ou d'exanthème (p. 93).\n**À relier** : le critère de durée (au moins 6 semaines) écarte aussi les éruptions d'évolution aiguë (p. 90-91)."},{"id":"d114-qroc-763","type":"QROC","rank":"A","objective":"d114-obj-17","tags":["rappel"],"difficulty":2,"question":"Quelle maladie du nouveau-né est citée parmi les causes d'érythrodermie avant 3 mois ?","answer":"La maladie de Leiner-Moussous","accept":["leiner-moussous","leiner moussous","leiner"],"keywords":["leiner"],"explanation":"Avant 3 mois : maladie de Leiner-Moussous ; après 3 mois : dermatite atopique, ou causes de l'adulte (p. 91).","src":"p. 91","deep":"**Pourquoi** : le tableau 4.4 sépare le nouveau-né et le nourrisson de moins de 3 mois de l'enfant de plus de 3 mois (p. 91).\n**Piège** : après 3 mois, la cause cotée +++ est la dermatite atopique ; au-delà, on raisonne comme chez l'adulte (p. 91).\n**À relier** : la maladie de Leiner-Moussous est traitée au chapitre 1 (item 111) (p. 91)."},{"id":"d114-qroc-764","type":"QROC","rank":"A","objective":"d114-obj-17","tags":["rappel"],"difficulty":2,"question":"Citez 3 causes d'érythrodermie chez l'adulte.","answer":"Psoriasis, dermatite atopique/eczéma, Sézary, DRESS, VIH, gale croûteuse","accept":["psoriasis","eczéma","dermatite atopique","sézary","dress","vih","gale","toxidermie","lymphome cutané"],"keywords":[],"explanation":"Adulte : psoriasis (+++), eczéma/dermatite atopique (+++), toxidermie (DRESS +++), syndrome de Sézary (+++), VIH (+), gale croûteuse (++) (p. 91).","src":"p. 91","deep":"**Pourquoi** : les causes principales retenues par le Collège sont le psoriasis, la dermatite atopique, le lymphome cutané et la toxidermie (DRESS) (p. 93).\n**Piège** : l'aspect clinique ne préjuge pas de la cause : l'enquête passe par l'interrogatoire (médicaments, topiques, antécédents…) et la biopsie (p. 91-93).\n**À relier** : DRESS = Drug Rash with hyper-Eosinophilia and Systemic Symptoms (p. 91)."},{"id":"d114-qroc-765","type":"QROC","rank":"A","objective":"d114-obj-17","tags":["rappel"],"difficulty":2,"question":"Quelle infection parasitaire peut donner une érythrodermie chez l'adulte ?","answer":"La gale croûteuse (hyperkératosique)","accept":["gale","gale croûteuse","gale hyperkératosique"],"keywords":["gale"],"explanation":"Gale croûteuse (++) parmi les causes infectieuses d'érythrodermie de l'adulte (p. 91) ; le tableau d'objectifs la nomme gale hyperkératosique (p. 83).","src":"p. 91","deep":"**Pourquoi** : les infections du tableau 4.4 sont le VIH (+) et la gale croûteuse (++) (p. 91).\n**Piège** : l'interrogatoire doit rechercher un contexte infectieux contemporain de l'éruption (p. 91).\n**À relier** : causes principales d'érythrodermie : psoriasis, dermatite atopique, lymphome cutané, toxidermie (DRESS) (p. 93)."},{"id":"d114-qroc-766","type":"QROC","rank":"A","objective":"d114-obj-17","tags":["rappel"],"difficulty":2,"question":"Quelle infection virale peut donner une érythrodermie chez l'adulte ?","answer":"Le VIH","accept":["vih"],"keywords":["vih"],"explanation":"VIH (+) parmi les causes infectieuses d'érythrodermie de l'adulte (p. 91).","src":"p. 91","deep":"**Pourquoi** : infections du tableau 4.4 : VIH (+) et gale croûteuse (++) (p. 91).\n**Piège** : le VIH est aussi à évoquer devant un exanthème de l'adulte (primo-infection VIH, roséoliforme ou morbilliforme) (p. 85-86, 90).\n**À relier** : une érythrodermie nécessite une hospitalisation urgente (p. 93)."},{"id":"d114-qroc-767","type":"QROC","rank":"B","objective":"d114-obj-17","tags":["rappel"],"difficulty":2,"question":"Outre le psoriasis, l'eczéma et les toxidermies, quelle dermatose inflammatoire peut donner une érythrodermie chez l'adulte ?","answer":"Le lichen plan","accept":["lichen plan","lichen"],"keywords":["lichen"],"explanation":"Le lichen plan figure parmi les dermatoses inflammatoires causes d'érythrodermie de l'adulte (tableau 4.4, p. 91).","src":"p. 91","deep":"**Pourquoi** : le tableau 4.4 classe les causes de l'adulte en dermatoses inflammatoires (psoriasis, eczéma/dermatite atopique, toxidermies, lichen plan), lymphome T cutané (Sézary) et infections (VIH, gale croûteuse) (p. 91).\n**Piège** : il reste des érythrodermies idiopathiques, dans 10 à 15 % des cas (p. 91).\n**À relier** : la biopsie cutanée peut montrer des signes spécifiques de la maladie responsable (p. 92)."},{"id":"d114-qroc-768","type":"QROC","rank":"A","objective":"d114-obj-06","tags":["rappel"],"difficulty":2,"question":"Quels points de l'interrogatoire guident l'étiologie d'une érythrodermie ?","answer":"Ancienneté, antécédents, médicaments, topiques, contexte infectieux","accept":["ancienneté","médicament","topiques","infectieux","antécédents"],"keywords":[],"explanation":"Interrogatoire : ancienneté de l'éruption, antécédents dermatologiques et généraux, prise médicamenteuse, traitements topiques, contexte infectieux contemporain (p. 91).","src":"p. 91","deep":"**Pourquoi** : l'aspect clinique ne préjuge pas de la cause (p. 93) ; interrogatoire, examen clinique et examens complémentaires sont essentiels au diagnostic (p. 91).\n**Piège** : la prise médicamenteuse vise une toxidermie (DRESS), cause majeure (p. 91, 93).\n**À relier** : antécédents dermatologiques : psoriasis et dermatite atopique sont cotés +++ parmi les causes (p. 91)."},{"id":"d114-qroc-769","type":"QROC","rank":"A","objective":"d114-obj-06","tags":["rappel"],"difficulty":2,"question":"Dans quelle situation faut-il répéter une biopsie cutanée devant une érythrodermie ?","answer":"Suspicion de lymphome cutané","accept":["lymphome","lymphome cutané"],"keywords":["lymphome"],"explanation":"La biopsie cutanée peut montrer des signes histologiques spécifiques de la maladie responsable ; elle doit être répétée en cas de suspicion de lymphome cutané (p. 92).","src":"p. 92","deep":"**Pourquoi** : le lymphome T cutané épidermotrope (syndrome de Sézary) est une cause majeure (+++) d'érythrodermie de l'adulte (p. 91).\n**Piège** : en cas de suspicion de lymphome, le Collège demande de répéter la biopsie (p. 92).\n**À relier** : prélèvements bactériologiques (hyperthermie, complications infectieuses) ou parasitologiques si besoin (p. 92)."},{"id":"d114-qroc-770","type":"QROC","rank":"A","objective":"d114-obj-06","tags":["rappel"],"difficulty":2,"question":"Quels mécanismes expliquent la déperdition hydro-électrolytique de l'érythrodermie ?","answer":"Vasodilatation cutanée, desquamation, suintement, œdème, fièvre","accept":["vasodilatation","desquamation","suintement","œdème","fièvre"],"keywords":[],"explanation":"Déperdition hydro-électrolytique provoquée par la vasodilatation cutanée, la desquamation, le suintement, l'œdème et la fièvre ; elle peut décompenser une insuffisance cardiaque, respiratoire ou rénale (p. 93).","src":"p. 93","deep":"**Pourquoi** : d'où la rééquilibration des troubles hydro-électrolytiques, l'une des mesures de l'hospitalisation en urgence (p. 93).\n**Piège** : la gravité est corrélée au terrain : les tares sous-jacentes peuvent décompenser (p. 82, 92-93).\n**À relier** : le réchauffement limite les pertes caloriques, l'hypercatabolisme et la dénutrition (p. 93)."},{"id":"d114-qroc-771","type":"QROC","rank":"A","objective":"d114-obj-06","tags":["rappel"],"difficulty":2,"question":"Citez 2 complications du décubitus à éviter dans l'érythrodermie.","answer":"Dénutrition, cachexie, escarres","accept":["dénutrition","cachexie","escarres","escarre"],"keywords":[],"explanation":"Complications du décubitus, à prendre en charge rapidement : dénutrition, cachexie, escarres (p. 93).","src":"p. 93","deep":"**Pourquoi** : elles figurent parmi les complications systémiques de l'érythrodermie, avec les troubles hydro-électrolytiques, les infections et le décès (p. 82, 93).\n**Piège** : la dénutrition est aussi limitée par le réchauffement du malade, qui réduit pertes caloriques et hypercatabolisme (p. 93).\n**À relier** : la mortalité peut atteindre 20 % (p. 93)."},{"id":"d114-qroc-772","type":"QROC","rank":"A","objective":"d114-obj-06","tags":["rappel"],"difficulty":2,"question":"Citez 2 types d'infections compliquant l'érythrodermie.","answer":"Infections cutanées (staphylocoque, herpès, zona), pneumopathies, septicémies","accept":["staphylocoque","herpès","zona","pneumopathie","septicémie","varicelle","pneumopathies","septicémies","infections cutanées"],"keywords":[],"explanation":"Infections : surtout cutanées bactériennes (staphylocoque), virales (herpès, varicelle-zona), ou générales (pneumopathies, septicémies) (p. 93).","src":"p. 93","deep":"**Pourquoi** : la mortalité, jusqu'à 20 %, est liée aux complications, notamment infectieuses (p. 93).\n**Piège** : la fièvre peut relever de la dysrégulation thermique ; des prélèvements bactériologiques peuvent être nécessaires (hyperthermie, complications infectieuses) (p. 90, 92).\n**À relier** : détecter l'infection fait partie de la mise en condition du malade hospitalisé (p. 83)."},{"id":"d114-qroc-773","type":"QROC","rank":"A","objective":"d114-obj-09","tags":["rappel"],"difficulty":2,"question":"Quel est le niveau du dermocorticoïde utilisé dans les formes graves d'érythrodermie ?","answer":"Niveau 1 (très forte)","accept":["niveau 1","très fort","très forte","classe 1"],"keywords":[],"explanation":"Formes graves : corticothérapie locale de niveau 1 (très forte), qui entraîne une amélioration symptomatique rapide (p. 93).","src":"p. 93","deep":"**Pourquoi** : c'est un traitement symptomatique, prévu dans les formes graves, à côté du réchauffement du malade (p. 93).\n**Piège** : il ne dispense pas de la recherche et du traitement étiologiques, qui font partie de l'hospitalisation en urgence (p. 93).\n**À relier** : hospitalisation en urgence : biologie de gravité, rééquilibration hydro-électrolytique, traitement des défaillances viscérales (p. 93)."},{"id":"d114-qroc-774","type":"QROC","rank":"A","objective":"d114-obj-09","tags":["rappel"],"difficulty":2,"question":"Quel geste symptomatique limite les pertes caloriques et la dénutrition dans l'érythrodermie ?","answer":"Le réchauffement du malade","accept":["réchauffement","réchauffer"],"keywords":["réchauff"],"explanation":"Le réchauffement du malade limite ses pertes caloriques, l'hypercatabolisme et la dénutrition (p. 93).","src":"p. 93","deep":"**Pourquoi** : l'érythrodermie s'accompagne d'une dysrégulation cutanée thermique importante, avec épisodes de fièvre et d'hypothermie (p. 90).\n**Piège** : on réchauffe le malade, malgré les épisodes fébriles (p. 90, 93).\n**À relier** : dans les formes graves, corticothérapie locale de niveau 1 (très forte) (p. 93)."},{"id":"d114-qroc-775","type":"QROC","rank":"A","objective":"d114-obj-21","tags":["rappel"],"difficulty":2,"question":"Le tableau clinique d'une érythrodermie préjuge-t-il de sa cause ?","answer":"Non","accept":["non"],"keywords":[],"explanation":"L'aspect clinique de l'érythrodermie ne préjuge pas de sa cause (p. 93).","src":"p. 93","deep":"**Pourquoi** : c'est un syndrome de diagnostic clinique aux multiples étiologies (p. 90), dominées par le psoriasis, la dermatite atopique, le lymphome cutané et la toxidermie (DRESS) (p. 93).\n**Piège** : la cause se cherche par l'interrogatoire (dont médicaments et topiques) et la biopsie, à répéter si suspicion de lymphome (p. 91-92).\n**À relier** : rechercher l'étiologie est l'une des trois étapes de la prise en charge, avec la reconnaissance et l'évaluation de la gravité (p. 90)."},{"id":"d114-qru-701","type":"QRU","rank":"A","objective":"d114-obj-26","tags":["rappel"],"difficulty":2,"stem":"Une enfant de 8 ans non vaccinée a une fièvre à 39,5 °C depuis 3 jours, un catarrhe oculo-nasal et une conjonctivite. Quelle constatation à l'examen de la bouche oriente le plus vers le diagnostic évoqué ?","options":[{"t":"Une angine rouge avec fausses membranes","ok":false,"why":"Faux : le Collège ne décrit pas d'angine dans la rougeole ; l'angine rouge avec adénopathies sous-maxillaires appartient à la phase pré-éruptive de la scarlatine (p. 86, 88)."},{"t":"Un semis de papules sur la face interne des joues","ok":true,"why":"Vrai : c'est le signe de Köplick, de la phase pré-éruptive de la rougeole, avec catarrhe oculo-nasal, fièvre 39-40 °C et conjonctivite (p. 86)."},{"t":"Une langue framboisée","ok":false,"why":"Faux : la langue framboisée (avec dépapillation en « V ») est celle de la scarlatine ; elle fait aussi partie de l'énanthème du Kawasaki (p. 88)."},{"t":"Une chéilite avec fissures","ok":false,"why":"Faux : la chéilite fait partie de l'énanthème du Kawasaki (fièvre > 38,5 °C plus de 5 jours, conjonctivite bilatérale) (p. 88)."},{"t":"Des aphtes de la face interne des lèvres","ok":false,"why":"Faux : le Collège ne décrit pas d'aphtes dans la rougeole ; son signe buccal est le semis de papules de Köplick à la face interne des joues (p. 86)."}],"explanation":"Catarrhe oculo-nasal + conjonctivite + fièvre élevée chez un enfant non vacciné : rougeole ; le signe de Köplick (semis de papules à la face interne des joues) appartient à sa phase pré-éruptive (p. 86, 90).","src":"p. 86","deep":"**Pourquoi** : catarrhe oculo-nasal, conjonctivite et exanthème fébrile doivent faire évoquer une rougeole (p. 90).\n**Piège** : la langue framboisée oriente vers la scarlatine ou le Kawasaki, pas vers la rougeole (p. 88).\n**À relier** : maladie à déclaration obligatoire ; éviction de la collectivité jusqu'à 5 jours après le début de l'éruption (p. 86)."},{"id":"d114-qru-702","type":"QRU","rank":"B","objective":"d114-obj-32","tags":["rappel"],"difficulty":2,"stem":"Un enfant de 2 ans a une fièvre à 39 °C depuis 6 jours, une conjonctivite bilatérale avec œdème des paupières, une chéilite, une langue framboisée, un œdème des mains et un exanthème polymorphe. Quel examen complémentaire cardiaque faut-il demander ?","options":[{"t":"Une coronarographie systématique","ok":false,"why":"Faux : le bilan de suspicion de Kawasaki cité par le Collège est NFS, plaquettes et échographie cardiaque ; la coronarographie n'y figure pas (p. 85)."},{"t":"Une échographie cardiaque","ok":true,"why":"Vrai : en cas de suspicion de syndrome de Kawasaki, on demande NFS, plaquettes et échographie cardiaque ; le Kawasaki expose aux anévrismes coronariens (p. 85, 88)."},{"t":"Un Holter-ECG seul à distance","ok":false,"why":"Faux : le Holter ne figure pas dans le bilan cité (NFS, plaquettes, échographie cardiaque) (p. 85)."},{"t":"Une épreuve d'effort","ok":false,"why":"Faux : non citée ; le bilan d'un Kawasaki suspecté comprend NFS, plaquettes et échographie cardiaque (p. 85)."},{"t":"Aucun examen cardiaque","ok":false,"why":"Faux : un retard thérapeutique expose aux anévrismes coronariens, et l'échographie cardiaque fait partie du bilan (p. 85, 90)."}],"explanation":"Fièvre > 38,5 °C plus de 5 jours chez un enfant de moins de 5 ans, avec conjonctivite, énanthème, atteinte des extrémités et exanthème polymorphe : syndrome de Kawasaki ; bilan : NFS, plaquettes, échographie cardiaque (p. 85, 88).","src":"p. 85, 88","deep":"**Pourquoi** : le Kawasaki est une vasculite systémique aiguë ; ses complications cardiaques comprennent anévrismes coronariens et troubles du rythme, avec décès possible par myocardite ou infarctus (p. 88).\n**Piège** : la langue framboisée ne signe pas une scarlatine : elle fait partie de l'énanthème du Kawasaki (p. 88).\n**À relier** : hospitalisation indispensable ; biologie : CRP élevée, hyperleucocytose à PNN, thrombocytose (p. 88)."},{"id":"d114-qru-703","type":"QRU","rank":"B","objective":"d114-obj-15","tags":["rappel"],"difficulty":2,"stem":"Une femme enceinte de 20 semaines, au contact d'un enfant avec un érythème des joues et une éruption en gants et chaussettes, s'inquiète. Quel risque fœtal est à redouter ?","options":[{"t":"Une anasarque fœtale","ok":true,"why":"Vrai : joues souffletées puis gants et chaussettes = mégalérythème (parvovirus B19) ; une infection au 2e trimestre expose à l'anasarque fœtale, à la myocardite et à l'anémie fœtale (p. 86)."},{"t":"Une hydrocéphalie par toxoplasmose","ok":false,"why":"Faux : l'éruption décrite chez l'enfant contact (joues, gants et chaussettes) est celle du parvovirus B19, dont le risque fœtal est l'anasarque (p. 86)."},{"t":"Une syphilis congénitale","ok":false,"why":"Faux : la syphilis (forme congénitale) fait partie des exanthèmes à risque chez la femme enceinte, mais l'éruption de l'enfant contact est un mégalérythème à parvovirus B19 (p. 83, 86)."},{"t":"Aucun risque","ok":false,"why":"Faux : la primo-infection à parvovirus pendant la grossesse expose au risque d'anasarque fœtale (p. 90)."},{"t":"Des malformations cardiaques tératogènes","ok":false,"why":"Faux : le Collège précise l'absence de risque tératogène du parvovirus B19 ; le risque est une atteinte fœtale (anasarque, myocardite, anémie) (p. 86)."}],"explanation":"Enfant contact avec joues souffletées et érythème en gants et chaussettes : mégalérythème épidémique (parvovirus B19). Chez la femme enceinte, pas de risque tératogène, mais une infection au 2e trimestre expose à l'anasarque fœtale (p. 86, 90).","src":"p. 86, 90","deep":"**Pourquoi** : le parvovirus B19 fait partie des quatre exanthèmes à risque chez la femme enceinte, avec la rubéole, la toxoplasmose et la syphilis (p. 83).\n**Piège** : à 20 semaines (2e trimestre), on ne redoute pas une malformation mais l'anasarque fœtale (avec myocardite et anémie fœtale) (p. 86).\n**À relier** : bilan d'un exanthème de la femme enceinte : sérologies toxoplasmose, rubéole, CMV, parvovirus B19 et syphilis, selon le statut de début de grossesse (p. 85)."},{"id":"d114-qru-704","type":"QRU","rank":"A","objective":"d114-obj-21","tags":["rappel"],"difficulty":2,"stem":"Quel élément exclut le diagnostic d'érythrodermie devant une éruption érythémato-squameuse diffuse ?","options":[{"t":"Une desquamation en lambeaux","ok":false,"why":"Faux : la desquamation de l'érythrodermie est constante, fine ou en larges lambeaux : elle ne l'exclut pas (p. 90)."},{"t":"Des éléments séparés par des intervalles de peau saine","ok":true,"why":"Vrai : des éléments multiples séparés par des intervalles de peau saine ne sont pas une érythrodermie, qui exige un érythème confluant sur plus de 90 % de la surface corporelle (p. 90-91)."},{"t":"Un prurit","ok":false,"why":"Faux : le prurit est constant dans l'érythrodermie (p. 90)."},{"t":"Une adénopathie","ok":false,"why":"Faux : une poly-adénopathie généralisée, à ganglions souples et mobiles, est fréquemment associée à l'érythrodermie (p. 91)."},{"t":"Une fièvre associée","ok":false,"why":"Faux : la dysrégulation thermique de l'érythrodermie donne des épisodes de fièvre et d'hypothermie (p. 90)."}],"explanation":"Ne sont pas des érythrodermies : une éruption érythémato-squameuse à éléments multiples séparés par des intervalles de peau saine, un exanthème ou une nécrolyse épidermique avec décollement d'évolution aiguë (p. 91).","src":"p. 91","deep":"**Pourquoi** : la définition repose sur un érythème confluant avec desquamation sur plus de 90 % de la surface corporelle, depuis au moins 6 semaines (p. 90).\n**Piège** : desquamation, prurit, fièvre et adénopathies font partie du tableau d'érythrodermie : ils ne l'excluent pas (p. 90-91).\n**À relier** : érythrodermie n'est pas synonyme d'érythème ou d'exanthème (p. 93)."},{"id":"d114-qru-705","type":"QRU","rank":"A","objective":"d114-obj-09","tags":["rappel"],"difficulty":2,"stem":"Un homme de 70 ans a un érythème généralisé desquamant et prurigineux depuis 8 semaines, avec poly-adénopathies. Quelle est la mesure symptomatique associée au réchauffement dans les formes graves ?","options":[{"t":"Un dermocorticoïde de niveau 4 (faible)","ok":false,"why":"Faux : dans les formes graves, le Collège cite une corticothérapie locale de niveau 1 (très forte), pas un dermocorticoïde faible (p. 93)."},{"t":"Des antibiotiques systématiques","ok":false,"why":"Faux : aucune antibiothérapie systématique n'est citée ; on détecte l'infection, avec prélèvements bactériologiques si hyperthermie ou complication infectieuse (p. 83, 92)."},{"t":"Une photothérapie immédiate","ok":false,"why":"Faux : la photothérapie ne figure pas dans la prise en charge citée (réchauffement, dermocorticoïde de niveau 1 dans les formes graves) (p. 93)."},{"t":"Un dermocorticoïde de niveau 1 (très fort)","ok":true,"why":"Vrai : dans les formes graves, la corticothérapie locale de niveau 1 (très forte) entraîne une amélioration symptomatique rapide (p. 93)."},{"t":"Une chirurgie de débridement","ok":false,"why":"Faux : non citée ; le traitement symptomatique associe réchauffement et dermocorticoïde de niveau 1 dans les formes graves (p. 93)."}],"explanation":"Érythème généralisé desquamant depuis plus de 6 semaines = érythrodermie : hospitalisation en urgence ; traitement symptomatique = réchauffement et, dans les formes graves, corticothérapie locale de niveau 1 (très forte) (p. 93).","src":"p. 93","deep":"**Pourquoi** : le réchauffement limite les pertes caloriques, l'hypercatabolisme et la dénutrition ; le dermocorticoïde très fort donne une amélioration symptomatique rapide (p. 93).\n**Piège** : chez ce sujet âgé avec poly-adénopathies, ne pas oublier le syndrome de Sézary, cause majeure ; biopsie à répéter si suspicion de lymphome cutané (p. 91-92).\n**À relier** : recherche et traitement étiologiques font partie de l'hospitalisation en urgence (p. 93)."},{"id":"d114-qru-706","type":"QRU","rank":"B","objective":"d114-obj-30","tags":["rappel"],"difficulty":2,"stem":"Un adolescent présente une fièvre avec asthénie importante, une poly-adénopathie et une splénomégalie. Quelle anomalie de la NFS est attendue ?","options":[{"t":"Une anémie macrocytaire","ok":false,"why":"Faux : la NFS de la mononucléose décrite par le Collège montre une lymphocytose élevée avec lymphocytes hyperbasophiles, pas d'anémie (p. 86)."},{"t":"Une lymphocytose avec lymphocytes hyperbasophiles","ok":true,"why":"Vrai : lymphocytose élevée avec lymphocytes hyperbasophiles dans la mononucléose infectieuse (EBV) de l'adolescent (p. 86)."},{"t":"Une thrombocytose avec hyperleucocytose à PNN","ok":false,"why":"Faux : hyperleucocytose à PNN et thrombocytose, avec CRP élevée, sont la biologie du syndrome de Kawasaki (p. 88)."},{"t":"Une leucopénie avec neutropénie","ok":false,"why":"Faux : la mononucléose donne une lymphocytose ; l'agranulocytose n'est qu'une de ses complications rares (p. 86)."},{"t":"Une thrombopénie majeure isolée","ok":false,"why":"Faux : non décrite par le Collège dans la mononucléose, dont les complications rares sont hépatite, méningo-encéphalite, rupture splénique et agranulocytose (p. 86)."}],"explanation":"Adolescent avec fièvre et asthénie importante, poly-adénopathie, splénomégalie : mononucléose infectieuse (EBV) ; NFS : lymphocytose élevée avec lymphocytes hyperbasophiles (p. 86).","src":"p. 86","deep":"**Pourquoi** : terrain (adolescent) et clinique (asthénie importante, poly-adénopathie, splénomégalie) orientent vers l'EBV ; chez l'adulte, le sérodiagnostic de MNI fait partie du bilan d'un exanthème sans cause évidente (p. 85-86).\n**Piège** : l'exanthème est inconstant (5-10 %) sauf prescription de pénicilline A : c'est le rash à l'ampicilline, à ne pas prendre pour une toxidermie (p. 82, 86).\n**À relier** : complication rare à redouter devant la splénomégalie : la rupture splénique (p. 86)."},{"id":"d114-qcm-701","type":"QRM","rank":"A","objective":"d114-obj-03","tags":["rappel"],"difficulty":2,"stem":"Une éruption est faite de petites macules rosées, pâles, bien séparées. Quel type d'exanthème est-ce ?","options":[{"t":"Érythrodermique","ok":false,"why":"Faux : l'érythrodermie n'est pas un type d'exanthème : érythème confluant desquamant sur plus de 90 % de la peau depuis au moins 6 semaines (p. 90, 93)."},{"t":"Roséoliforme (ou rubéoliforme)","ok":true,"why":"Vrai : roséoliforme ou rubéoliforme = petites macules rosées, pâles, bien séparées les unes des autres (p. 85)."},{"t":"Scarlatiniforme","ok":false,"why":"Faux : scarlatiniforme = plaques diffuses rouge vif, légèrement granitées, sans intervalle de peau saine, s'intensifiant dans les plis (p. 85)."},{"t":"Pétéchial","ok":false,"why":"Faux : le Collège distingue trois types séméiologiques d'exanthème : roséoliforme, morbilliforme et scarlatiniforme (p. 82, 85)."},{"t":"Morbilliforme","ok":false,"why":"Faux : morbilliforme = maculo-papules rouges pouvant confluer en plaques séparées par des espaces de peau saine (p. 85)."}],"explanation":"Petites macules rosées, pâles, bien séparées : exanthème roséoliforme (ou rubéoliforme) ; les deux autres types séméiologiques sont morbilliforme et scarlatiniforme (p. 85).","src":"p. 85","deep":"**Pourquoi** : l'analyse séméiologique de l'éruption fait partie de la démarche diagnostique, avec l'anamnèse et les signes extracutanés et biologiques (p. 85).\n**Piège** : morbilliforme = maculo-papules qui peuvent confluer mais gardent des espaces de peau saine ; scarlatiniforme = aucun intervalle de peau saine (p. 85).\n**À relier** : origine virale : fièvre, syndrome grippal, énanthème, poly-adénopathie ; origine médicamenteuse : prurit, éruption polymorphe, hyperéosinophilie (p. 85)."},{"id":"d114-qcm-702","type":"QRM","rank":"B","objective":"d114-obj-24","tags":["rappel"],"difficulty":2,"stem":"Quelles propositions sont exactes à propos des examens complémentaires devant un exanthème fébrile de l'enfant ?","options":[{"t":"Une biopsie cutanée est systématique","ok":false,"why":"Faux : la biopsie ne figure pas parmi les examens de l'enfant : aucun examen n'est indispensable sauf suspicion de scarlatine ou de Kawasaki (p. 85)."},{"t":"Chez l'enfant, aucun examen n'est indispensable sauf suspicion de scarlatine ou de Kawasaki","ok":true,"why":"Vrai : examens ciblés : NFS et prélèvement de gorge si scarlatine ; NFS, plaquettes et échographie cardiaque si Kawasaki (p. 85)."},{"t":"Un prélèvement de gorge est demandé dans tous les cas","ok":false,"why":"Faux : le prélèvement de gorge n'est demandé qu'en cas de suspicion de scarlatine (p. 85)."},{"t":"Une NFS avec échographie cardiaque est demandée dans tous les cas","ok":false,"why":"Faux : NFS, plaquettes et échographie cardiaque correspondent à la suspicion de Kawasaki (p. 85)."},{"t":"Un scanner cérébral est systématique","ok":false,"why":"Faux : non cité ; les seuls examens prévus chez l'enfant concernent la suspicion de scarlatine ou de Kawasaki (p. 85)."}],"explanation":"Chez l'enfant, aucun examen n'est indispensable, sauf suspicion de scarlatine (NFS, prélèvement de gorge) ou de syndrome de Kawasaki (NFS, plaquettes, échographie cardiaque) (p. 85).","src":"p. 85","deep":"**Piège** : chez l'adulte, en dehors d'une cause évidente, un bilan est fait : NFS, tests hépatiques, sérodiagnostic de MNI, test tréponémique, charge virale VIH, sérologie VIH combinée (p. 85).\n**À relier** : chez la femme enceinte, sérologies de toxoplasmose, rubéole, CMV, parvovirus B19 et syphilis selon le statut sérologique de début de grossesse (p. 85) ; chez l'enfant, l'exanthème fébrile est le plus souvent viral (p. 90)."},{"id":"d114-qcm-703","type":"QRM","rank":"B","objective":"d114-obj-14","tags":["rappel"],"difficulty":3,"stem":"Un adulte de 25 ans a une fièvre brutale et un exanthème scarlatiniforme avec hypotension et tachycardie. Quelle(s) proposition(s) est(sont) exacte(s) ?","options":[{"t":"Le diagnostic est une rubéole","ok":false,"why":"Faux : la rubéole donne un exanthème roséoliforme discret (2 à 4 jours), pas un exanthème scarlatiniforme avec retentissement hémodynamique (p. 85)."},{"t":"Une surveillance à domicile est suffisante","ok":false,"why":"Faux : un exanthème scarlatiniforme fébrile brutal impose de rechercher un choc toxique staphylococcique et ses signes hémodynamiques, présents ici (p. 90)."},{"t":"On recherche un syndrome du choc toxique staphylococcique","ok":true,"why":"Vrai : la survenue brutale d'un exanthème diffus scarlatiniforme fébrile doit faire rechercher un choc toxique staphylococcique (p. 90)."},{"t":"Un traitement antibiotique par amoxicilline suffit toujours","ok":false,"why":"Faux : l'amoxicilline est le traitement de la scarlatine streptococcique ; la forme staphylococcique, dont le choc toxique est la forme sévère, est traitée par oxacilline (p. 88)."},{"t":"Une éviction scolaire de 48 heures suffit","ok":false,"why":"Faux : l'éviction de 48 heures après le début du traitement est une mesure de collectivité ; ici, la priorité est de dépister le retentissement hémodynamique (p. 88, 90)."}],"explanation":"Exanthème scarlatiniforme fébrile brutal avec hypotension et tachycardie : rechercher un syndrome du choc toxique staphylococcique et dépister ses signes de retentissement hémodynamique (p. 90).","src":"p. 90","deep":"**Pourquoi** : le choc toxique est la forme sévère de la scarlatine staphylococcique, due à S. aureus sécréteur d'entérotoxines ou de TSST1 (p. 88).\n**Piège** : la forme staphylococcique n'a pas d'angine et se traite par oxacilline, pas par amoxicilline (p. 88).\n**À relier** : le terrain de la forme staphylococcique comprend l'adulte immunodéprimé (p. 88)."},{"id":"d114-qcm-704","type":"QRM","rank":"A","objective":"d114-obj-21","tags":["rappel"],"difficulty":2,"stem":"Quelles propositions sont exactes à propos de l'érythrodermie ?","options":[{"t":"Elle est synonyme d'exanthème","ok":false,"why":"Faux : érythrodermie n'est pas synonyme d'érythème ou d'exanthème ; un exanthème, d'évolution aiguë, n'est pas une érythrodermie (p. 91, 93)."},{"t":"C'est une urgence dermatologique","ok":true,"why":"Vrai : urgence dermatologique exigeant une prise en charge immédiate, thérapeutique et étiologique (p. 90)."},{"t":"Elle est rare et son étiologie est toujours évidente","ok":false,"why":"Faux : elle est rare, mais c'est un syndrome aux multiples étiologies, dont l'aspect clinique ne préjuge pas de la cause (p. 90, 93)."},{"t":"Elle nécessite une hospitalisation dans un service spécialisé","ok":true,"why":"Vrai : hospitalisation dans un service spécialisé, en urgence (p. 91, 93)."},{"t":"L'aspect clinique permet d'identifier la cause","ok":false,"why":"Faux : l'aspect clinique de l'érythrodermie ne préjuge pas de sa cause (p. 93)."}],"explanation":"Érythrodermie : syndrome rare de diagnostic clinique aux multiples étiologies ; urgence dermatologique imposant une hospitalisation dans un service spécialisé (p. 90-91, 93).","src":"p. 90, 93","deep":"**Pourquoi** : trois étapes : reconnaître l'érythrodermie, rechercher l'étiologie, apprécier la gravité immédiate et proposer un traitement symptomatique (p. 90).\n**Piège** : le diagnostic de l'érythrodermie est clinique, pas celui de sa cause : elle se cherche par l'interrogatoire, l'examen et les examens complémentaires (p. 91, 93).\n**À relier** : la mortalité peut atteindre 20 % (p. 93)."},{"id":"d114-qcm-705","type":"QRM","rank":"A","objective":"d114-obj-06","tags":["rappel"],"difficulty":2,"stem":"Un homme de 70 ans hospitalisé pour érythrodermie depuis 3 jours : quels risques évolutifs faut-il anticiper ?","options":[{"t":"Le décubitus n'a aucune conséquence","ok":false,"why":"Faux : complications du décubitus à prendre en charge rapidement : dénutrition, cachexie, escarres (p. 93)."},{"t":"La mortalité peut atteindre 20 %","ok":true,"why":"Vrai : la mortalité peut atteindre 20 %, liée aux différentes complications, notamment infectieuses (p. 93)."},{"t":"La gravité est indépendante du terrain","ok":false,"why":"Faux : la gravité est corrélée au terrain et aux complications (p. 92)."},{"t":"La déperdition hydro-électrolytique peut décompenser une insuffisance cardiaque","ok":true,"why":"Vrai : elle peut décompenser une insuffisance cardiaque, respiratoire ou rénale (p. 93)."},{"t":"Les complications infectieuses sont exceptionnelles","ok":false,"why":"Faux : les infections font partie des complications (cutanées à staphylocoque, herpès ou varicelle-zona, pneumopathies, septicémies) et pèsent sur la mortalité (p. 93)."}],"explanation":"Complications de l'érythrodermie : hydro-électrolytiques (décompensation cardiaque, respiratoire ou rénale), du décubitus, infectieuses ; mortalité jusqu'à 20 % (p. 92-93).","src":"p. 92-93","deep":"**Pourquoi** : la déperdition hydro-électrolytique vient de la vasodilatation cutanée, de la desquamation, du suintement, de l'œdème et de la fièvre (p. 93).\n**Piège** : la gravité est corrélée au terrain : chez un patient de 70 ans, les tares sous-jacentes peuvent décompenser (p. 92-93).\n**À relier** : prise en charge : rééquilibration hydro-électrolytique, traitement des défaillances viscérales, réchauffement (p. 93)."},{"id":"d114-qcm-706","type":"QRM","rank":"B","objective":"d114-obj-12","tags":["rappel"],"difficulty":2,"stem":"Quelles propositions sont exactes à propos des exanthèmes roséoliformes ?","options":[{"t":"La rubéole survient avant 5 ans","ok":false,"why":"Faux : la rubéole survient entre 15 et 25 ans ; c'est l'exanthème subit qui touche le nourrisson de 6 à 18 mois (p. 85)."},{"t":"Le Kawasaki en est la cause principale","ok":false,"why":"Faux : le Kawasaki est une cause d'exanthème scarlatiniforme, avec la scarlatine (p. 83)."},{"t":"La rougeole en est la cause principale","ok":false,"why":"Faux : la rougeole est une des trois causes principales d'exanthème morbilliforme, avec le mégalérythème et la mononucléose (p. 83, 86)."},{"t":"Exanthème subit, rubéole, primo-infection VIH et syphilis secondaire en sont des causes","ok":true,"why":"Vrai : ce sont les quatre causes principales d'exanthème roséoliforme (p. 83)."},{"t":"L'exanthème subit survient chez le nourrisson de 6 à 18 mois","ok":true,"why":"Vrai : l'exanthème subit (primo-infection HHV6) touche le nourrisson de 6 à 18 mois (p. 85)."}],"explanation":"Roséoliforme : exanthème subit (nourrisson de 6 à 18 mois, HHV6), rubéole (15 à 25 ans), primo-infection VIH, syphilis secondaire (p. 83, 85).","src":"p. 83, 85","deep":"**Pourquoi** : roséoliforme = petites macules rosées, pâles, bien séparées (p. 85).\n**Piège** : « souvent asymptomatique » qualifie l'exanthème subit dans le tableau 4.1, pas la rubéole (p. 85).\n**À relier** : primo-infection VIH et syphilis rejoignent les causes à évoquer devant tout exanthème de l'adulte, avec les médicaments (p. 83, 90)."},{"id":"d114-qcm-707","type":"QRM","rank":"A","objective":"d114-obj-16","tags":["rappel"],"difficulty":2,"stem":"Un enfant a un exanthème avec fièvre élevée. Quels éléments orientent vers la rougeole ?","options":[{"t":"Catarrhe oculo-nasal","ok":true,"why":"Vrai : il appartient à la phase pré-éruptive de la rougeole ; avec la conjonctivite et l'exanthème fébrile, il doit la faire évoquer (p. 86, 90)."},{"t":"Desquamation en doigt de gant","ok":false,"why":"Faux : c'est l'évolution de l'atteinte des extrémités du syndrome de Kawasaki (p. 88)."},{"t":"Langue framboisée","ok":false,"why":"Faux : langue framboisée = scarlatine (dépapillation en « V ») ou énanthème du Kawasaki (p. 88)."},{"t":"Début de l'exanthème en rétro-auriculaire","ok":true,"why":"Vrai : l'exanthème de la rougeole débute en rétro-auriculaire puis s'étend à tout le corps en une seule poussée (p. 86)."},{"t":"Joues « souffletées » en guirlande","ok":false,"why":"Faux : l'aspect souffleté des joues est celui du mégalérythème épidémique (parvovirus B19) ; l'érythème à bords émiettés en guirlande touche le tronc (p. 86-87)."}],"explanation":"Rougeole : phase pré-éruptive (catarrhe oculo-nasal, fièvre 39-40 °C, signe de Köplick, conjonctivite) puis exanthème débutant en rétro-auriculaire et s'étendant en une seule poussée (p. 86, 90).","src":"p. 86, 90","deep":"**Pourquoi** : le Collège demande de savoir évoquer une rougeole devant l'association catarrhe oculo-nasal, conjonctivite et exanthème fébrile (p. 90).\n**Piège** : desquamation en doigt de gant (Kawasaki) et joues souffletées (mégalérythème) appartiennent à d'autres fièvres éruptives (p. 86, 88).\n**À relier** : complications : pneumopathie, hépatite, pancréatite, encéphalite grave, kératite et cécité (p. 86)."},{"id":"d114-qcm-708","type":"QRM","rank":"B","objective":"d114-obj-32","tags":["rappel"],"difficulty":2,"stem":"Quelles propositions sont exactes à propos du syndrome de Kawasaki ?","options":[{"t":"Le traitement antibiotique par oxacilline est le traitement de référence","ok":false,"why":"Faux : l'oxacilline traite la scarlatine staphylococcique ; le Kawasaki est une vasculite systémique aiguë, pour laquelle le Collège indique l'hospitalisation indispensable (p. 88)."},{"t":"L'éviction de la collectivité est le traitement","ok":false,"why":"Faux : l'éviction est une mesure de la scarlatine ou de la rougeole ; pour le Kawasaki, le Collège indique l'hospitalisation indispensable (p. 86, 88)."},{"t":"Hospitalisation indispensable","ok":true,"why":"Vrai : hospitalisation indispensable ; un retard thérapeutique expose aux anévrismes coronariens (p. 88, 90)."},{"t":"L'exanthème polymorphe fait partie des signes cliniques","ok":true,"why":"Vrai : exanthème polymorphe, avec conjonctivite bilatérale, chéilite et langue framboisée, érythème et œdème des extrémités, lymphadénite souvent asymétrique et fièvre > 38,5 °C plus de 5 jours (p. 88)."},{"t":"Le terrain est l'enfant de moins de 5 ans","ok":true,"why":"Vrai : terrain = enfant de moins de 5 ans, quand la scarlatine touche l'enfant de 5 à 10 ans (p. 88)."}],"explanation":"Kawasaki : vasculite systémique aiguë de l'enfant de moins de 5 ans ; diagnostic si au moins cinq des six critères ; hospitalisation indispensable (p. 88).","src":"p. 88, 90","deep":"**Pourquoi** : le risque est cardiaque : anévrismes coronariens, troubles du rythme, décès par myocardite ou infarctus (p. 88).\n**Piège** : langue framboisée et desquamation ne suffisent pas à dire scarlatine : le Kawasaki a son énanthème et sa desquamation en doigt de gant (p. 88).\n**À relier** : biologie : CRP élevée, hyperleucocytose à PNN, thrombocytose (p. 88)."},{"id":"d114-qcm-709","type":"QRM","rank":"A","objective":"d114-obj-31","tags":["rappel"],"difficulty":2,"stem":"Un enfant de 6 ans a une angine rouge avec adénopathies sous-maxillaires et une éruption des plis. Quelles propositions sont exactes ?","options":[{"t":"Une éviction scolaire de 5 jours est obligatoire","ok":false,"why":"Faux : dans la scarlatine, l'éviction de la collectivité dure jusqu'à 48 heures après le début du traitement ; « 5 jours après le début de l'éruption » est la règle de la rougeole (p. 86, 88)."},{"t":"Un prélèvement de gorge est réalisé","ok":true,"why":"Vrai : le prélèvement de gorge figure dans la colonne scarlatine du tableau 4.3 (p. 88)."},{"t":"Le traitement est l'oxacilline","ok":false,"why":"Faux : l'oxacilline traite la scarlatine staphylococcique (sans angine) ; l'angine rouge oriente ici vers la scarlatine streptococcique (p. 88)."},{"t":"Le germe est le streptocoque du groupe A","ok":true,"why":"Vrai : la scarlatine est due au streptocoque du groupe A sécréteur d'exotoxines, chez l'enfant de 5 à 10 ans (p. 88)."},{"t":"L'antibiotique est l'amoxicilline","ok":true,"why":"Vrai : traitement antibiotique de la scarlatine par amoxicilline (p. 88)."}],"explanation":"Enfant de 6 ans, angine rouge avec adénopathies sous-maxillaires et éruption des grands plis : scarlatine (streptocoque du groupe A) → prélèvement de gorge, amoxicilline, éviction jusqu'à 48 heures après le début du traitement (p. 88).","src":"p. 88","deep":"**Pourquoi** : la contagiosité de la scarlatine, de 2 à 3 semaines, persiste 48 heures après la mise en route du traitement (p. 88).\n**Piège** : l'absence d'angine oriente vers la forme staphylococcique, traitée par oxacilline (p. 88).\n**À relier** : complications post-streptococciques : glomérulonéphrites, rhumatisme articulaire aigu (p. 88)."},{"id":"d114-qcm-710","type":"QRM","rank":"B","objective":"d114-obj-15","tags":["rappel"],"difficulty":2,"stem":"Quelles associations agent-risque pendant la grossesse sont exactes ?","options":[{"t":"Rubéole : mort fœtale ou malformations neurologiques et sensorielles","ok":true,"why":"Vrai : chez la femme enceinte non immunisée, risque de mort fœtale ou de malformations neurologiques sensorielles (p. 85)."},{"t":"Rougeole : anasarque fœtale","ok":false,"why":"Faux : l'anasarque fœtale est le risque du parvovirus B19 ; la rougeole ne figure pas parmi les quatre exanthèmes à risque chez la femme enceinte (p. 83, 86)."},{"t":"Parvovirus B19 : anasarque fœtale","ok":true,"why":"Vrai : infection au 2e trimestre : risque d'anasarque fœtale, de myocardite et d'anémie fœtale, sans risque tératogène (p. 86)."},{"t":"Syphilis : forme congénitale","ok":true,"why":"Vrai : la syphilis expose à la forme congénitale (p. 83)."},{"t":"Toxoplasmose : sans risque fœtal","ok":false,"why":"Faux : la toxoplasmose figure parmi les quatre exanthèmes à risque chez la femme enceinte, et sa sérologie fait partie du bilan (p. 83, 85)."}],"explanation":"Quatre exanthèmes à risque chez la femme enceinte : rubéole (mort fœtale ou malformations), parvovirus B19 (anasarque fœtale), toxoplasmose, syphilis (forme congénitale) (p. 83, 85-86).","src":"p. 83, 85, 90","deep":"**Pourquoi** : le bilan d'un exanthème de la femme enceinte s'interprète selon son statut sérologique de début de grossesse : toxoplasmose, rubéole, CMV, parvovirus B19, syphilis (p. 85).\n**Piège** : le parvovirus B19 n'a pas de risque tératogène, à la différence de la rubéole (malformations) (p. 85-86).\n**À relier** : rubéole : pas d'éviction recommandée, mais information du personnel, des parents et de la femme enceinte (p. 85)."},{"id":"d114-qcm-711","type":"QRM","rank":"A","objective":"d114-obj-09","tags":["rappel"],"difficulty":2,"stem":"Quels éléments de prise en charge d'une érythrodermie sont corrects ?","options":[{"t":"Sortir le patient avec une surveillance ambulatoire","ok":false,"why":"Faux : une érythrodermie nécessite une hospitalisation urgente, dans un service spécialisé (p. 91, 93)."},{"t":"Refroidir le patient","ok":false,"why":"Faux : on réchauffe le malade, ce qui limite les pertes caloriques, l'hypercatabolisme et la dénutrition (p. 93)."},{"t":"Hospitalisation en urgence","ok":true,"why":"Vrai : hospitalisation en urgence, avec examens biologiques pour évaluer la gravité de la dermatose (p. 93)."},{"t":"Rééquilibrer les troubles hydro-électrolytiques","ok":true,"why":"Vrai : la déperdition hydro-électrolytique peut décompenser une insuffisance cardiaque, respiratoire ou rénale ; sa correction fait partie de l'hospitalisation en urgence (p. 93)."},{"t":"Chercher et traiter la cause","ok":true,"why":"Vrai : recherche et traitement étiologiques (psoriasis, dermatite atopique, lymphome cutané, toxidermie…) (p. 93)."}],"explanation":"Érythrodermie : hospitalisation en urgence (biologie de gravité, rééquilibration hydro-électrolytique, défaillances viscérales, enquête étiologique) ; réchauffement ; dermocorticoïde de niveau 1 dans les formes graves (p. 93).","src":"p. 93","deep":"**Pourquoi** : c'est une urgence dermatologique : la prise en charge est immédiate, à la fois thérapeutique et étiologique (p. 90).\n**Piège** : malgré les épisodes de fièvre (dysrégulation thermique), on réchauffe le malade (p. 90, 93).\n**À relier** : complications à prévenir : décubitus (dénutrition, cachexie, escarres), infections ; mortalité jusqu'à 20 % (p. 93)."},{"id":"d114-qcm-712","type":"QRM","rank":"B","objective":"d114-obj-27","tags":["rappel"],"difficulty":2,"stem":"Quelles propositions sont exactes à propos de la rubéole ?","options":[{"t":"Cause de syndrome mononucléosique systématique","ok":false,"why":"Faux : le syndrome mononucléosique figure parmi les complications rares de l'exanthème subit, pas de la rubéole (p. 85)."},{"t":"Âge de survenue 15 à 25 ans","ok":true,"why":"Vrai : âge de survenue de la rubéole : 15 à 25 ans (p. 85)."},{"t":"Sans risque pour la femme enceinte","ok":false,"why":"Faux : chez la femme enceinte non immunisée, risque de mort fœtale ou de malformations neurologiques sensorielles (p. 85)."},{"t":"Exanthème roséoliforme discret","ok":true,"why":"Vrai : exanthème roséoliforme discret, de 2 à 4 jours, avec arthralgies et conjonctivite (p. 85)."},{"t":"Souvent asymptomatique","ok":false,"why":"Faux : dans le tableau 4.1, « souvent asymptomatique » qualifie l'exanthème subit (roséole infantile), pas la rubéole (p. 85)."}],"explanation":"Rubéole : adulte jeune (15 à 25 ans), incubation 3 semaines, exanthème roséoliforme discret (2 à 4 jours) avec arthralgies et conjonctivite ; risque chez la femme enceinte non immunisée (p. 85, 90).","src":"p. 85, 90","deep":"**Pourquoi** : chez la femme enceinte non immunisée, la rubéole expose à une mort fœtale ou à des malformations ; le bilan d'une femme enceinte tient compte de son statut sérologique (p. 85, 90).\n**Piège** : c'est l'exanthème subit, autre roséoliforme, qui est « souvent asymptomatique » et peut se compliquer d'un syndrome mononucléosique (p. 85).\n**À relier** : pas de recommandation d'éviction pour la rubéole, mais information du personnel, des parents et de la femme enceinte (p. 85)."},{"id":"d114-qcm-713","type":"QRM","rank":"A","objective":"d114-obj-25","tags":["rappel"],"difficulty":2,"stem":"Quelles étiologies d'exanthème de l'enfant sont virales ?","options":[{"t":"Rougeole","ok":true,"why":"Vrai : due au morbillivirus (paramyxovirus) (p. 86)."},{"t":"Scarlatine","ok":false,"why":"Faux : la scarlatine est bactérienne : streptocoque du groupe A sécréteur d'exotoxines (p. 88)."},{"t":"Exanthème subit","ok":true,"why":"Vrai : primo-infection par HHV6 (human herpesvirus 6) (p. 85)."},{"t":"Mononucléose infectieuse","ok":true,"why":"Vrai : due à l'Epstein-Barr virus (EBV) (p. 86)."},{"t":"Mégalérythème épidémique","ok":true,"why":"Vrai : dû au parvovirus B19 (p. 86)."}],"explanation":"Les exanthèmes fébriles de l'enfant sont le plus souvent viraux (rougeole, exanthème subit, mononucléose, mégalérythème…), mais peuvent être bactériens (scarlatine), inflammatoires ou médicamenteux (p. 85-86, 90).","src":"p. 85-86","deep":"**Pourquoi** : les signes d'origine virale sont fièvre, syndrome grippal, énanthème, poly-adénopathie (p. 85).\n**Piège** : scarlatine (streptocoque) et épidermolyse staphylococcique sont bactériennes ; le Kawasaki est une vasculite systémique aiguë (p. 88).\n**À relier** : chez l'adulte, penser au VIH, à la syphilis et aux médicaments (p. 90)."},{"id":"d114-qcm-714","type":"QRM","rank":"A","objective":"d114-obj-21","tags":["rappel"],"difficulty":2,"stem":"Quels éléments cliniques peuvent s'observer au cours d'une érythrodermie évoluée ?","options":[{"t":"Ongles dystrophiques avec ligne de Beau","ok":true,"why":"Vrai : après quelques semaines, ongles dystrophiques, de croissance ralentie, d'où une ligne de Beau, voire une chute de l'ongle (p. 91)."},{"t":"Œdème du visage avec ectropion","ok":true,"why":"Vrai : œdème souvent marqué du visage, où il peut exister un ectropion (p. 91)."},{"t":"Chute des cheveux, sourcils et cils","ok":true,"why":"Vrai : l'atteinte des phanères comporte une chute des cheveux, des sourcils et des cils (p. 91)."},{"t":"Des intervalles de peau saine entre les plaques","ok":false,"why":"Faux : des éléments séparés par des intervalles de peau saine excluent l'érythrodermie, définie par un érythème confluant sur plus de 90 % de la surface corporelle (p. 90-91)."},{"t":"Pachydermie des plis","ok":true,"why":"Vrai : pachydermie mieux visible aux plis, témoignant d'une infiltration cellulaire spécifique (p. 91)."}],"explanation":"Érythrodermie évoluée : érythème, desquamation et prurit constants, pachydermie des plis, œdème du visage (ectropion possible), atteinte des phanères après quelques semaines, poly-adénopathie (p. 90-91).","src":"p. 90-91","deep":"**Pourquoi** : l'atteinte des phanères apparaît après quelques semaines d'évolution, d'où sa place dans une érythrodermie évoluée (p. 91).\n**Piège** : l'atteinte muqueuse (chéilite, conjonctivite, stomatite) est possible, pas constante (p. 91).\n**À relier** : troubles hémodynamiques avec déperditions hydro-électrolytiques et/ou protéiques et altération de l'état général complètent le tableau (p. 91)."}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"d114-pareto","points":[{"id":"d114-par-01","rank":"A","cat":"définition","text":"**Exanthème** = érythème d'apparition **brutale et transitoire** (± énanthème) ; causes : **virales** (enfant), **VIH/syphilis** et **médicaments** (adulte)","src":"p. 84, 90"},{"id":"d114-par-02","rank":"A","cat":"clinique","text":"3 types : **roséoliforme** (petites macules rosées séparées), **morbilliforme** (maculo-papuleux, peau saine entre les plaques), **scarlatiniforme** (rouge vif, **sans peau saine**, plis)","src":"p. 85"},{"id":"d114-par-03","rank":"A","cat":"clinique","text":"Origine **virale** : fièvre, syndrome grippal, énanthème, adénopathies ; origine **médicamenteuse** : **prurit**, éruption polymorphe, **hyperéosinophilie**","src":"p. 85"},{"id":"d114-par-04","rank":"A","cat":"clinique","text":"**Rougeole** : catarrhe oculo-nasal + conjonctivite + exanthème fébrile ; **signe de Köplick** ; début rétro-auriculaire ; complications : pneumopathie, **encéphalite**, kératite","src":"p. 86, 90"},{"id":"d114-par-05","rank":"A","cat":"prévention","text":"Rougeole = maladie à **déclaration obligatoire** ; éviction de la collectivité jusqu'à **5 jours** après le début de l'éruption","src":"p. 86"},{"id":"d114-par-06","rank":"A","cat":"clinique","text":"**Exanthème subit** : nourrisson, **HHV6**, fièvre isolée **3 jours** puis éruption roséoliforme du tronc, en une seule poussée","src":"p. 85, 90"},{"id":"d114-par-07","rank":"A","cat":"gravité","text":"Grossesse : **rubéole** → **malformations**/mort fœtale ; **parvovirus B19** (mégalérythème épidémique) → **anasarque fœtale**, pas de risque tératogène","src":"p. 85-86, 90"},{"id":"d114-par-08","rank":"A","cat":"clinique","text":"**Mégalérythème épidémique** (parvovirus B19, enfant 5-10 ans) : érythème-œdème des joues, tronc à bords émiettés, puis **gants et chaussettes** ; contagiosité pré-éruptive","src":"p. 86"},{"id":"d114-par-09","rank":"A","cat":"piège","text":"**MNI** (EBV, adolescent) : **lymphocytes hyperbasophiles** ; exanthème inconstant sauf **pénicilline A** → **rash à l'ampicilline**, à ne pas confondre avec une toxidermie","src":"p. 82, 86"},{"id":"d114-par-10","rank":"A","cat":"clinique","text":"**Scarlatine** : streptocoque A, début brutal + angine, grands plis, **langue framboisée** ; prélèvement de gorge, **amoxicilline**, éviction 48 h ; complications **GNA/RAA**","src":"p. 88"},{"id":"d114-par-11","rank":"A","cat":"gravité","text":"**Kawasaki** : vasculite, enfant < 5 ans, fièvre > 38,5 °C **> 5 jours**, **≥ 5 critères sur 6** ; risque d'**anévrismes coronariens** ; **hospitalisation** indispensable","src":"p. 88, 90"},{"id":"d114-par-12","rank":"B","cat":"piège","text":"Scarlatine **staphylococcique** : **pas d'angine**, grands plis puis décollement bulleux, **oxacilline** ; exanthème scarlatiniforme brutal fébrile → chercher un **choc toxique**","src":"p. 88, 90"},{"id":"d114-par-13","rank":"A","cat":"définition","text":"**Érythrodermie** = érythème + desquamation > **90 %** de la surface, depuis ≥ **6 semaines** ; prurit constant, **dysrégulation thermique** ; ≠ exanthème ; **urgence**","src":"p. 90-91, 93"},{"id":"d114-par-14","rank":"A","cat":"étiologie","text":"Causes d'érythrodermie : **psoriasis**, **dermatite atopique**, **DRESS**, **syndrome de Sézary** ; mortalité jusqu'à **20 %** (troubles hydro-électrolytiques, escarres, infections)","src":"p. 91-93"},{"id":"d114-par-15","rank":"A","cat":"traitement","text":"Érythrodermie : **hospitalisation en urgence**, **rééquilibration hydro-électrolytique**, **réchauffement**, recherche étiologique, corticothérapie locale de niveau 1 si forme grave","src":"p. 90, 93"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
